}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::None => "none",
            Value::Auto => "auto",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) | Value::Decimal(_) => "float",
            Value::Str(_) => "string",
            Value::Length(_) => "length",
            Value::Ratio(_) => "ratio",
            Value::Relative(_) => "relative length",
            Value::Angle(_) => "angle",
            Value::Fraction(_) => "fraction",
            Value::Color(_) => "color",
            Value::Array(_) => "array",
            Value::Dict(_) => "dictionary",
            Value::Content(_) => "content",
            Value::Func(_) => "function",
            Value::Closure(_) => "function",
            Value::Module(_) => "module",
            Value::Type(_) => "type",
            Value::Label(_) => "label",
            Value::Symbol(_) => "symbol",
            Value::Version(_) => "version",
            Value::Datetime(_) | Value::DatetimeFields(_) => "datetime",
            Value::Duration(_) => "duration",
            Value::Bytes(_) => "bytes",
            Value::Regex(_) => "regex",
            Value::Alignment(_) => "alignment",
            Value::Counter(_) => "counter",
            Value::Selector(_) => "selector",
            Value::Arguments(..) => "arguments",
        }
    }
    // Short display name used in some errors ("integer" etc.) – same as type_name except content element?
    pub fn err_name(&self) -> String {
        self.type_name().to_string()
    }
    pub fn truthy(&self) -> Option<bool> {
        match self { Value::Bool(b)=>Some(*b), _=>None }
    }
    pub fn repr(&self) -> String {
        match self {
            Value::None => "none".into(),
            Value::Auto => "auto".into(),
            Value::Bool(b) => if *b {"true".into()} else {"false".into()},
            Value::Int(i) => i.to_string(),
            Value::Float(f) => format_float_repr(*f),
            Value::Decimal(f) => format_float_repr(*f),
            Value::Str(s) => format!("{:?}", s),
            Value::Length(l) => format_length(l),
            Value::Ratio(r) => format_ratio(*r),
            Value::Relative(rel) => {
                let mut parts: Vec<String> = Vec::new();
                if rel.ratio != 0.0 { parts.push(format_ratio(rel.ratio)); }
                if rel.length.pt != 0.0 || rel.length.em != 0.0 { parts.push(format_length(&rel.length)); }
                if parts.is_empty() { "0%".into() } else { parts.join(" + ") }
            }
            Value::Angle(d) => format!("{}deg", trim_num(round_to(*d, 2))),
            Value::Fraction(f) => format!("{}fr", trim_num(*f)),
            Value::Color(c) => c.clone(),
            Value::Array(items) => {
                if items.is_empty() { "()".into() }
                else if items.len()==1 { format!("({},)", items[0].repr()) }
                else { format!("({})", items.iter().map(|v| v.repr()).collect::<Vec<_>>().join(", ")) }
            }
            Value::Dict(entries) => {
                if entries.is_empty() { "(:)".into() }
                else { format!("({})", entries.iter().map(|(k,v)| format!("{}: {}", k, v.repr())).collect::<Vec<_>>().join(", ")) }
            }
            Value::Content(c) => c.repr(),
            Value::Func(n) => n.clone(),
            Value::Closure(cl) => cl.name.clone().unwrap_or_else(|| "..".to_string()),
            Value::Module(n) => format!("<module {}>", n),
            Value::Type(n) => n.clone(),
            Value::Label(l) => format!("<{}>", l),
            Value::Symbol(s) => format!("symbol({:?})", s),
            Value::Version(v) => format!("version({})", v.iter().map(|i| i.to_string()).collect::<Vec<_>>().join(", ")),
            Value::Datetime(s) => format!("datetime({})", s),
            Value::DatetimeFields(f) => format!("datetime({})", f.iter().map(|(k,v)| format!("{}: {}", k, v)).collect::<Vec<_>>().join(", ")),
            Value::Duration(f) => format!("duration({})", f.iter().map(|(k,v)| format!("{}: {}", k, trim_num(*v))).collect::<Vec<_>>().join(", ")),
            Value::Bytes(b) => format!("bytes({})", b.len()),
            Value::Regex(r) => format!("regex({:?})", r),
            Value::Alignment(a) => a.clone(),
            Value::Counter(s) => format!("counter({})", s),
            Value::Selector(s) => s.clone(),
            Value::Arguments(pos, named) => {
                let mut parts: Vec<String> = pos.iter().map(|v| v.repr()).collect();
                for (k,v) in named { parts.push(format!("{}: {}", k, v.repr())); }
                format!("arguments({})", parts.join(", "))
            }
        }
    }
    // Display conversion used when content shows a value (e.g. #x in markup) and str() subset.
    pub fn display_str(&self) -> String {
        match self {
            Value::Str(s) => s.clone(),
            Value::Int(i) => i.to_string(),
            Value::Float(f) => format_float_display(*f),
            Value::Bool(b) => if *b {"true".into()} else {"false".into()},
            Value::Label(l) => l.clone(),
            Value::Symbol(s) => s.clone(),
            _ => self.repr(),
        }
    }
}

impl Content {
    pub fn new(func: &str) -> Self { Content{ func: func.to_string(), fields: Vec::new(), label: None } }
    pub fn text(t: String) -> Self {
        let mut c = Content::new("text"); c.fields.push(("text".into(), Value::Str(t))); c
    }
    pub fn simple(func: &str, body: Content) -> Self {
        let mut c = Content::new(func); c.fields.push(("body".into(), Value::Content(body))); c
    }
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.fields.iter().find(|(k,_)| k==key).map(|(_,v)| v)
    }
    pub fn repr(&self) -> String {
        match self.func.as_str() {
            "text" => {
                if let Some(Value::Str(t)) = self.get("text") { format!("[{}]", t) } else { "[]".into() }
            }
            "sequence" => {
                if let Some(Value::Array(children)) = self.get("children") {
                    let mut s = String::from("[");
                    for ch in children {
                        if let Value::Content(c) = ch {
                            match c.func.as_str() {
                                "text" => { if let Some(Value::Str(t))=c.get("text") { s.push_str(t); } }
                                "space" => s.push(' '),
                                "parbreak" => s.push_str("\n\n"),
                                _ => s.push_str(&strip_brackets(&ch.repr())),
                            }
                        }
                    }
                    s.push(']'); s
                } else { "[]".into() }
            }
            "space" => "[ ]".into(),
            "parbreak" => "[]".into(),
            _ => {
                // e.g. strong(body: [Hi])
                if self.fields.is_empty() { return self.func.clone(); }
                let parts: Vec<String> = self.fields.iter().map(|(k,v)| {
                    if k=="body" {
                        if let Value::Content(_) = v { format!("body: {}", v.repr()) } else { format!("body: {}", v.repr()) }
                    } else { format!("{}: {}", k, v.repr()) }
                }).collect();
                format!("{}({})", self.func, parts.join(", "))
            }
        }
    }
    pub fn plain_text(&self) -> String {
        match self.func.as_str() {
            "text" => if let Some(Value::Str(t))=self.get("text") { t.clone() } else { String::new() },
            "space" => " ".into(),
            "parbreak" => "\n\n".into(),
            "linebreak" => "\n".into(),
            "sequence" => {
                let mut s=String::new();
                if let Some(Value::Array(ch))=self.get("children") { for c in ch { if let Value::Content(cc)=c { s.push_str(&cc.plain_text()); } } }
                s
            }
            "raw" => if let Some(Value::Str(t))=self.get("text") { t.clone() } else { String::new() },
            "symbol" => if let Some(Value::Str(t))=self.get("text") { t.clone() } else { String::new() },
            _ => {
                if let Some(Value::Content(b))=self.get("body") { b.plain_text() }
                else if let Some(Value::Content(b))=self.get("child") { b.plain_text() }
                else if let Some(Value::Array(ch))=self.get("children") {
                    let mut s=String::new(); for c in ch { if let Value::Content(cc)=c { s.push_str(&cc.plain_text()); } } s
                } else { String::new() }
            }
        }
    }
}

pub fn strip_brackets(s: &str) -> String {
    if s.starts_with('[') && s.ends_with(']') { s[1..s.len()-1].to_string() } else { s.to_string() }
}

pub fn round_to(x: f64, places: i32) -> f64 {
    let m = 10f64.powi(places);
    (x * m).round() / m
}

pub fn trim_num(x: f64) -> String {
    if x == x.trunc() && x.abs() < 1e15 {
        format!("{}", x as i64)
    } else {
        // Use up-to-10 decimal trimming (Rust default Display for f64 is shortest in recent versions? format with {} )
        let s = format!("{}", x);
        s
    }
}

pub fn format_float_repr(f: f64) -> String {
    if f.is_infinite() { return if f > 0.0 { "float.inf".into() } else { "-float.inf".into() }; }
    if f.is_nan() { return "float.nan".into(); }
    // serde_json-like: if integral, ensure ".0" unless exponent form
    let s = serde_json::Number::from_f64(f).map(|n| n.to_string()).unwrap_or_else(|| format!("{}", f));
    if s.contains('.') || s.contains('e') || s.contains('E') { s } else { format!("{}.0", s) }
}

pub fn format_float_display(f: f64) -> String {
    // str(float) in Typst: probe shows str(1.5)="1.5"; assume same shortest without forcing .0? Keep repr-style minus float.inf handling.
    if f.is_infinite() { return if f>0.0 {"inf".into()} else {"-inf".into()} }
    if f.is_nan() { return "nan".into(); }
    let s = serde_json::Number::from_f64(f).map(|n| n.to_string()).unwrap_or_else(|| format!("{}", f));
    s
}

pub fn format_length(l: &LengthVal) -> String {
    if l.em == 0.0 {
        format!("{}pt", trim_num(round_to(l.pt, 2)))
    } else if l.pt == 0.0 {
        format!("{}em", trim_num(l.em))
    } else {
        format!("{}pt + {}em", trim_num(round_to(l.pt,2)), trim_num(l.em))
    }
}

pub fn format_ratio(r: f64) -> String {
    format!("{}%", trim_num(round_to(r*100.0, 2)))
}

// ---- Serialization to serde_json::Value (Typst's JSON representation) ----
pub fn to_json(v: &Value) -> serde_json::Value {
    use serde_json::Value as J;
    match v {
        Value::None => J::Null,
        Value::Auto => J::String("auto".into()),
        Value::Bool(b) => J::Bool(*b),
        Value::Int(i) => J::Number((*i).into()),
        Value::Float(f) | Value::Decimal(f) => {
            if let Some(n) = serde_json::Number::from_f64(*f) { J::Number(n) } else { J::Null }
        }
        Value::Str(s) => J::String(s.clone()),
        Value::Array(items) => J::Array(items.iter().map(to_json).collect()),
        Value::Dict(entries) => {
            let mut map = serde_json::Map::new();
            for (k, val) in entries { map.insert(k.clone(), to_json(val)); }
            J::Object(map)
        }
        Value::Content(c) => {
            let mut map = serde_json::Map::new();
            map.insert("func".into(), J::String(c.func.clone()));
            for (k, val) in &c.fields { map.insert(k.clone(), to_json(val)); }
            if let Some(l) = &c.label { map.insert("label".into(), J::String(format!("<{}>", l))); }
            J::Object(map)
        }
        // Everything else serializes as its repr string, except label/symbol special-cases below.
        Value::Label(l) => J::String(format!("<{}>", l)),
        Value::Symbol(s) => J::String(s.clone()),
        Value::Type(n) => J::String(n.clone()),
        Value::Func(n) => J::String(n.clone()),
        _ => J::String(v.repr()),
    }
}

// Convert a JSON value into a YAML string the way serde_yaml would, but we just use serde_yaml on the JSON value.
// We keep a helper here for consistency.
pub fn value_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::None, Value::None) => true,
        (Value::Auto, Value::Auto) => true,
        (Value::Bool(x), Value::Bool(y)) => x==y,
        (Value::Int(x), Value::Int(y)) => x==y,
        (Value::Float(x), Value::Float(y)) => x==y,
        (Value::Int(x), Value::Float(y)) => (*x as f64)==*y,
        (Value::Float(x), Value::Int(y)) => *x==(*y as f64),
        (Value::Str(x), Value::Str(y)) => x==y,
        (Value::Array(x), Value::Array(y)) => x.len()==y.len() && x.iter().zip(y.iter()).all(|(u,v)| value_eq(u,v)),
        (Value::Dict(x), Value::Dict(y)) => x.len()==y.len() && x.iter().zip(y.iter()).all(|((k1,v1),(k2,v2))| k1==k2 && value_eq(v1,v2)),
        (Value::Label(x), Value::Label(y)) => x==y,
        (Value::Length(x), Value::Length(y)) => x.pt==y.pt && x.em==y.em,
        (Value::Ratio(x), Value::Ratio(y)) => x==y,
        (Value::Angle(x), Value::Angle(y)) => x==y,
        (Value::Color(x), Value::Color(y)) => x==y,
        (Value::Alignment(x), Value::Alignment(y)) => x==y,
        (Value::Version(x), Value::Version(y)) => x==y,
        _ => a.repr() == b.repr() && a.type_name() == b.type_name(),
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{}", self.repr()) }
}

// Placeholder map type used elsewhere (ordered dict via Vec).
pub type OrderedMap = Vec<(String, Value)>;

pub fn dict_get<'a>(entries: &'a [(String, Value)], key: &str) -> Option<&'a Value> {
    entries.iter().find(|(k,_)| k==key).map(|(_,v)| v)
}
