    LetPattern(Vec<String>, SpExpr),
    LetFunc(String, Vec<String>, Option<String>, SpExpr),
    SetRule(SpExpr), // set call expression (already a Call)
    ShowRule, // ignored
    Import(String, Vec<(String,String)>), // path, (name, alias)
    ImportAll(String),
    Include(String),
    Expr(SpExpr),
    Assign(String, String, SpExpr), // name, op ("=", "+=", ...), value
    AssignField(SpExpr, String, String, SpExpr),
    For(Vec<String>, SpExpr, Vec<Stmt>),
    While(SpExpr, Vec<Stmt>),
    IfStmt(SpExpr, Vec<Stmt>, Option<Vec<Stmt>>, bool), // cond, then, else(body), else-is-if handled via Expr? simplified
    Break,
    Continue,
    Return(Option<SpExpr>),
    Context(Vec<Stmt>),
}

impl ExprKind {
    pub fn boxed(self) -> Expr { Box::new(self) }
}

pub fn ident_expr(name: &str, start: usize, end: usize) -> SpExpr {
    SpExpr{ kind: ExprKind::Ident(name.to_string(), start, end).boxed(), start, end }
}
