// Diagnostics: human (Typst style) and short formats, plus plain eval format.
#[derive(Clone, Debug)]
pub struct Diag {
    pub message: String,
    pub hints: Vec<String>,
    pub line: usize, // 1-based, 0 = unknown
    pub col: usize, // 0-based byte/col index within line for caret placement; display col = col (we match reference where span col printed as col index)
    pub span_len: usize, // in chars
    pub severity: Severity,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Severity { Error, Warning }

impl Diag {
    pub fn error(msg: impl Into<String>) -> Self {
        Diag{ message: msg.into(), hints: Vec::new(), line: 0, col: 0, span_len: 1, severity: Severity::Error }
    }
    pub fn error_at(msg: impl Into<String>, line: usize, col: usize, len: usize) -> Self {
        Diag{ message: msg.into(), hints: Vec::new(), line, col, span_len: len.max(1), severity: Severity::Error }
    }
    pub fn warning(msg: impl Into<String>) -> Self {
        let mut d = Diag::error(msg); d.severity = Severity::Warning; d
    }
    pub fn with_hint(mut self, h: impl Into<String>) -> Self { self.hints.push(h.into()); self }
}

pub fn line_col_of(source: &str, byte_offset: usize) -> (usize, usize) {
    // returns (1-based line, 0-based col in chars)
    let mut line = 1usize;
    let mut col = 0usize;
    for (i, ch) in source.char_indices() {
        if i >= byte_offset { break; }
        if ch == '\n' { line += 1; col = 0; } else { col += 1; }
    }
    (line, col)
}

pub fn format_plain(d: &Diag) -> String {
    // eval style: "error: message\n = hint: ...\n\n"
    let mut s = format!("error: {}\n", d.message);
    for h in &d.hints { s.push_str(&format!(" = hint: {}\n", h)); }
    s.push('\n');
    s
}

pub fn format_short(d: &Diag, path_display: &str) -> String {
    let sev = if d.severity == Severity::Warning { "warning" } else { "error" };
    if d.line == 0 {
        format!("{}: {}\n", sev, d.message)
    } else {
        format!("{}:{}:{}: {}: {}\n", path_display, d.line, d.col, sev, d.message)
    }
}

pub fn format_human(d: &Diag, source: &str, path_display: &str, use_color: bool) -> String {
    let sev = if d.severity == Severity::Warning { "warning" } else { "error" };
    let sev_rendered = if use_color {
        if d.severity == Severity::Warning {
            format!("\x1b[0m\x1b[1m\x1b[38;5;11m{}\x1b[0m", sev)
        } else {
            format!("\x1b[0m\x1b[1m\x1b[38;5;9m{}\x1b[0m", sev)
        }
    } else { sev.to_string() };
    let mut s = format!("{}: {}\n", sev_rendered, d.message);
    if d.line > 0 {
        let lines: Vec<&str> = source.lines().collect();
        let src_line = if d.line - 1 < lines.len() { lines[d.line-1] } else { "" };
        let line_num_str = d.line.to_string();
        let width = line_num_str.len();
        // Reference format:
        //   ┌─ <stdin>:1:1
        //   │
        // 1 │ #bad()
        //   │  ^^^
        let gutter_pad = " ".repeat(width);
        s.push_str(&format!("{}┌─ {}:{}:{}\n", gutter_pad, path_display, d.line, d.col));
        s.push_str(&format!("{}│\n", gutter_pad));
        s.push_str(&format!("{} │ {}\n", line_num_str, src_line));
        // caret line: gutter + │ + space + col spaces + carets
        // Col is 0-based position in line; reference underlines starting at that char.
        let carets = "^".repeat(d.span_len.max(1));
        // For tabs, expand naively (count chars).
        let mut caret_pad = String::new();
        for ch in src_line.chars().take(d.col) {
            if ch == '\t' { caret_pad.push('\t'); } else { caret_pad.push(' '); }
        }
        s.push_str(&format!("{}│ {}{}\n", gutter_pad, caret_pad, carets));
    }
    for h in &d.hints {
        s.push_str(&format!(" = hint: {}\n", h));
    }
    s.push('\n');
    s
}

/// Render a simple "error: message\n" with optional color (single line, no trailing blank).
pub fn render_simple_error(message: &str, use_color: bool) -> String {
    if use_color {
        format!("\x1b[0m\x1b[1m\x1b[38;5;9merror\x1b[0m: {}\n", message)
    } else {
        format!("error: {}\n", message)
    }
}

pub fn render_warning_hints(title: &str, hints: &[&str], use_color: bool) -> String {
    let w = if use_color { "\x1b[0m\x1b[1m\x1b[38;5;11mwarning\x1b[0m".to_string() } else { "warning".to_string() };
    let mut s = format!("{}: {}\n", w, title);
    for h in hints { s.push_str(&format!(" = hint: {}\n", h)); }
    s.push('\n');
    s
}
