// Project world: file access with Typst-like path rules, packages, fonts listing.
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub struct Project {
    pub root: PathBuf,
    pub main_path: Option<PathBuf>, // None = stdin / no project
    pub package_path: PathBuf,
    pub package_cache_path: PathBuf,
    pub font_paths: Vec<PathBuf>,
    pub ignore_system_fonts: bool,
    pub ignore_embedded_fonts: bool,
    pub inputs: Vec<(String,String)>,
}

pub fn home_dir() -> PathBuf {
    if let Ok(h) = std::env::var("HOME") {
        if !h.is_empty() { return PathBuf::from(h); }
    }
    PathBuf::from("/")
}

pub fn default_package_path(explicit_env: Option<&str>) -> PathBuf {
    if let Some(v) = explicit_env {
        // caller passes env value if set and non-empty? clap handles; here just use it.
        return PathBuf::from(v);
    }
    if let Ok(x) = std::env::var("XDG_DATA_HOME") {
        if !x.is_empty() { return PathBuf::from(x).join("typst").join("packages"); }
    }
    home_dir().join(".local/share/typst/packages")
}

pub fn default_package_cache_path(explicit_env: Option<&str>) -> PathBuf {
    if let Some(v) = explicit_env {
        return PathBuf::from(v);
    }
    if let Ok(x) = std::env::var("XDG_CACHE_HOME") {
        if !x.is_empty() { return PathBuf::from(x).join("typst").join("packages"); }
    }
    home_dir().join(".cache/typst/packages")
}

/// Display path for diagnostics: relative to CWD if under it (matching observed "../tmp/..." behavior).
pub fn display_path(p: &Path) -> String {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    // Canonical-ish absolute version of p (without requiring existence for all components).
    let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
    // Normalize . and .. textually.
    let abs = normalize(&abs);
    let cwd = normalize(&cwd);
    match path_relative(&cwd, &abs) {
        Some(rel) => rel.to_string_lossy().to_string(),
        None => abs.to_string_lossy().to_string(),
    }
}

pub fn normalize(p: &Path) -> PathBuf {
    let mut out: Vec<std::ffi::OsString> = Vec::new();
    let mut absolute = p.is_absolute();
    for comp in p.components() {
        match comp {
            std::path::Component::RootDir => { absolute = true; out.clear(); }
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => { out.pop(); }
            std::path::Component::Normal(s) => out.push(s.to_os_string()),
            std::path::Component::Prefix(_) => {}
        }
    }
    let mut r = if absolute { PathBuf::from("/") } else { PathBuf::new() };
    for o in out { r.push(o); }
    if r.as_os_str().is_empty() { r = PathBuf::from("."); }
    r
}

fn path_relative(base: &Path, target: &Path) -> Option<PathBuf> {
    let b: Vec<_> = base.components().collect();
    let t: Vec<_> = target.components().collect();
    let mut i = 0;
    while i < b.len() && i < t.len() && b[i].as_os_str() == t[i].as_os_str() { i += 1; }
    if i == 0 && base.is_absolute() != target.is_absolute() { return None; }
    let mut rel = PathBuf::new();
    for _ in i..b.len() { rel.push(".."); }
    for c in &t[i..] { rel.push(c.as_os_str()); }
    if rel.as_os_str().is_empty() { rel.push("."); }
    Some(rel)
}

impl Project {
    pub fn new_default() -> Self {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        Project{
            root: cwd.clone(), main_path: None,
            package_path: default_package_path(None),
            package_cache_path: default_package_cache_path(None),
            font_paths: Vec::new(), ignore_system_fonts: false, ignore_embedded_fonts: false,
            inputs: Vec::new(),
        }
    }
    /// Resolve a Typst path string (relative to a source file's directory, or "/"-absolute from root).
    pub fn resolve(&self, from_file: Option<&Path>, typst_path: &str) -> PathBuf {
        if let Some(abs) = typst_path.strip_prefix('/') {
            return self.root.join(abs);
        }
        if let Some(f) = from_file {
            if let Some(parent) = f.parent() { return parent.join(typst_path); }
        }
        self.root.join(typst_path)
    }
    pub fn read_file(&self, path: &Path) -> Result<Vec<u8>, String> {
        match std::fs::read(path) {
            Ok(b) => Ok(b),
            Err(e) => Err(format!("{}", e)),
        }
    }
}

// ---------- Fonts ----------
#[derive(Clone, Debug)]
pub struct FontVariant {
    pub style: String, // Normal / Italic / Oblique
    pub weight: u16,
    pub stretch: u16,
    pub path: String, // file path or "<embedded>"
}

#[derive(Clone, Debug)]
pub struct FontFamily {
    pub name: String,
    pub variants: Vec<FontVariant>,
}

pub fn embedded_fonts() -> Vec<FontFamily> {
    let v = |style:&str, w:u16| FontVariant{ style: style.into(), weight: w, stretch: 1000, path: "<embedded>".into() };
    vec![
        FontFamily{ name: "DejaVu Sans Mono".into(), variants: vec![v("Normal",700), v("Italic",700), v("Italic",400), v("Normal",400)] },
        FontFamily{ name: "Libertinus Serif".into(), variants: vec![v("Normal",400), v("Normal",700), v("Italic",400), v("Italic",700), v("Normal",600), v("Italic",600)] },
        FontFamily{ name: "New Computer Modern".into(), variants: vec![v("Normal",400), v("Normal",700), v("Italic",400), v("Italic",700)] },
        FontFamily{ name: "New Computer Modern Math".into(), variants: vec![v("Normal",700), v("Normal",450), v("Normal",400)] },
    ]
}

fn system_font_dirs() -> Vec<PathBuf> {
    vec![
        PathBuf::from("/usr/share/fonts"),
        PathBuf::from("/usr/local/share/fonts"),
        home_dir().join(".fonts"),
        home_dir().join(".local/share/fonts"),
    ]
}

fn is_font_file(p: &Path) -> bool {
    if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
        matches!(ext.to_ascii_lowercase().as_str(), "ttf" | "otf" | "ttc" | "otc")
    } else { false }
}

fn collect_font_files(dir: &Path, out: &mut Vec<PathBuf>) {
    let rd = match std::fs::read_dir(dir) { Ok(r)=>r, Err(_)=>return };
    let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|x| x.path())).collect();
    entries.sort();
    for e in entries {
        if e.is_dir() { collect_font_files(&e, out); }
        else if is_font_file(&e) { out.push(e); }
    }
}

/// Minimal TTF/OTF name-table parser (handles TTC first font only).
fn parse_font(path: &Path) -> Option<(String, FontVariant)> {
    let data = std::fs::read(path).ok()?;
    parse_font_data(&data, &path.to_string_lossy())
}

fn u16be(d: &[u8], off: usize) -> Option<u16> {
    Some(u16::from_be_bytes([*d.get(off)?, *d.get(off+1)?]))
}
fn u32be(d: &[u8], off: usize) -> Option<u32> {
    Some(u32::from_be_bytes([*d.get(off)?, *d.get(off+1)?, *d.get(off+2)?, *d.get(off+3)?]))
}

fn parse_font_data(data: &[u8], path_str: &str) -> Option<(String, FontVariant)> {
    let mut base = 0usize;
    if data.len() > 12 && &data[0..4] == b"ttcf" {
        base = u32be(data, 12)? as usize;
    }
    if data.len() < base + 12 { return None; }
    let num_tables = u16be(data, base+4)? as usize;
    let mut name_off: Option<usize> = None;
    let mut os2_off: Option<usize> = None;
    let mut head_off: Option<usize> = None;
    for i in 0..num_tables {
        let rec = base + 12 + i*16;
        if data.len() < rec+16 { break; }
        let tag = &data[rec..rec+4];
        let off = u32be(data, rec+8)? as usize;
        if tag == b"name" { name_off = Some(off); }
        else if tag == b"OS/2" { os2_off = Some(off); }
        else if tag == b"head" { head_off = Some(off); }
    }
    let noff = name_off?;
    let count = u16be(data, noff+2)? as usize;
    let str_off = u16be(data, noff+4)? as usize;
    // Gather name records: prefer (3,1,1033), then any platform 3/0, then platform 1.
    #[derive(Clone)]
    struct Rec { platform: u16, encoding: u16, lang: u16, text: String }
    let mut by_id: std::collections::HashMap<u16, Vec<Rec>> = std::collections::HashMap::new();
    for i in 0..count {
        let rec = noff + 6 + i*12;
        if data.len() < rec+12 { break; }
        let platform = u16be(data, rec)?;
        let encoding = u16be(data, rec+2)?;
        let lang = u16be(data, rec+4)?;
        let name_id = u16be(data, rec+6)?;
        let len = u16be(data, rec+8)? as usize;
        let off = u16be(data, rec+10)? as usize;
        let start = noff + str_off + off;
        let end = (start+len).min(data.len());
        if start >= end && len > 0 { continue; }
        let raw = &data[start..end];
        let text = if platform == 3 || platform == 0 {
            // UTF-16BE
            let mut units: Vec<u16> = Vec::new();
            let mut j = 0;
            while j+1 < raw.len() { units.push(u16::from_be_bytes([raw[j], raw[j+1]])); j+=2; }
            String::from_utf16_lossy(&units)
        } else {
            raw.iter().map(|b| *b as char).collect()
        };
        by_id.entry(name_id).or_default().push(Rec{platform, encoding, lang, text});
    }
    let pick = |id: u16| -> Option<String> {
        let recs = by_id.get(&id)?;
        // preference score
        let score = |r: &Rec| -> i32 {
            let mut s = 0;
            if r.platform == 3 { s += 100; if r.lang == 1033 { s += 10; } }
            else if r.platform == 0 { s += 50; }
            else if r.platform == 1 { s += 10; }
            s
        };
        recs.iter().max_by_key(|r| score(r)).map(|r| r.text.clone())
    };
    let family = pick(16).or_else(|| pick(1))?;
    let family = family.trim().to_string();
    if family.is_empty() { return None; }
    let mut weight: u16 = 400;
    let mut italic = false;
    if let Some(o) = os2_off {
        if let Some(w) = u16be(data, o+4) { if w > 0 { weight = w; } }
        if let Some(fs) = u16be(data, o+62) { italic = italic || (fs & 1) != 0; }
    }
    if let Some(h) = head_off {
        if let Some(mac) = u16be(data, h+44) { italic = italic || (mac & 2) != 0; }
    }
    let style = if italic { "Italic".to_string() } else { "Normal".to_string() };
    Some((family, FontVariant{ style, weight, stretch: 1000, path: path_str.to_string() }))
}

pub fn discover_fonts(font_paths: &[PathBuf], ignore_system: bool, ignore_embedded: bool) -> Vec<FontFamily> {
    // Order: system (sorted by path), then custom paths (in order, sorted), then embedded (in embedded order).
    let mut families: Vec<FontFamily> = Vec::new();
    let mut add = |families: &mut Vec<FontFamily>, name: String, variant: FontVariant| {
        if let Some(f) = families.iter_mut().find(|f| f.name == name) {
            f.variants.push(variant);
        } else {
            families.push(FontFamily{ name, variants: vec![variant] });
        }
    };
    let mut files: Vec<PathBuf> = Vec::new();
    if !ignore_system {
        for d in system_font_dirs() { collect_font_files(&d, &mut files); }
    }
    for d in font_paths { collect_font_files(d, &mut files); }
    for f in &files {
        if let Some((name, var)) = parse_font(f) {
            add(&mut families, name, var);
        }
    }
    if !ignore_embedded {
        for fam in embedded_fonts() {
            for var in fam.variants {
                add(&mut families, fam.name.clone(), var);
            }
        }
    }
    families.sort_by(|a,b| a.name.cmp(&b.name));
    families
}

pub fn split_font_paths_env(v: &str) -> Vec<PathBuf> {
    if v.is_empty() { return Vec::new(); }
    v.split(':').filter(|s| !s.is_empty()).map(|s| PathBuf::from(s)).collect()
}

pub fn font_family_names(font_paths: &[PathBuf], ignore_system: bool, ignore_embedded: bool) -> Vec<String> {
    discover_fonts(font_paths, ignore_system, ignore_embedded).into_iter().map(|f| f.name).collect()
}
