    fn err_at(&mut self, msg: String, start: usize, end: usize) {
        let (line, col) = crate::diag::line_col_of(&self.src, start);
        let len = self.src[start..end.min(self.src.len())].chars().count().max(1);
        self.errors.push(crate::diag::Diag::error_at(msg, line, col, len));
    }

    pub fn next_token(&mut self) -> Token {
        self.skip_ws_comments();
        let start = self.pos;
        let c = match self.peek_char() {
            None => return Token{ tok: Tok::Eof, start, end: start, text: String::new() },
            Some(c) => c,
        };
        // Identifiers / keywords
        if is_ident_start(c) {
            let mut s = String::new();
            while let Some(ch) = self.peek_char() {
                if is_ident_char(ch) {
                    // Trailing '-' handling: Typst idents allow '-' between ident chars but not trailing before digit/space ambiguities.
                    // Simple rule used by Typst: a '-' is part of ident if not followed by a digit? Observed: "assert-eq" lexes as one ident.
                    // We'll greedily consume '-' only if next char after it is ident-start alphanumeric/_.
                    if ch == '-' {
                        let after = self.src[self.pos + ch.len_utf8()..].chars().next();
                        match after {
                            Some(n) if n.is_alphanumeric() || n == '_' => { s.push(ch); self.bump_char(); }
                            _ => break,
                        }
                    } else {
                        s.push(ch); self.bump_char();
                    }
                } else { break; }
            }
            let end = self.pos;
            // Trim trailing dashes just in case.
            let text = s.clone();
            return Token{ tok: Tok::Ident(s), start, end, text };
        }
        // Numbers
        if c.is_ascii_digit() || (c == '.' && self.src[start+1..].chars().next().map(|n| n.is_ascii_digit()).unwrap_or(false)) {
            return self.lex_number(start);
        }
        // Strings
        if c == '"' {
            return self.lex_string(start);
        }
        // Labels: <name>  (only when it looks like <ident...>)
        if c == '<' {
            // Check for label: < [A-Za-z0-9... ] > with no spaces; otherwise it's '<' operator.
            let rest = &self.src[start..];
            let mut label: Option<(String, usize)> = None;
            let mut chars = rest.char_indices();
            chars.next(); // '<'
            let mut name = String::new();
            let mut ok = false;
            for (i, ch) in chars {
                if ch == '>' {
                    if !name.is_empty() { ok = true; label = Some((name.clone(), start + i + 1)); }
                    break;
                } else if ch.is_alphanumeric() || matches!(ch, '_'|'-'|':'|'.'|'/') {
                    name.push(ch);
                } else { break; }
            }
            if ok {
                let (name, end) = label.unwrap();
                self.pos = end;
                return Token{ tok: Tok::Label(name.clone()), start, end, text: format!("<{}>", name) };
            }
            // fall through to symbol handling
        }
        // Multi-char symbols, longest first
        const SYMS: &[&str] = &[
            "..=", "...", "..", "=>", "==", "!=", "<=", ">=", "+=", "-=", "*=", "/=", "::",
            "(", ")", "[", "]", "{", "}", ",", ":", ";", ".", "+", "-", "*", "/", "=", "<", ">", "#", "$", "@", "!", "?", "&", "|", "~", "^", "_", "`", "\\",
        ];
        for sym in SYMS {
            if self.starts_with(sym) {
                self.pos += sym.len();
                return Token{ tok: Tok::Sym(sym.to_string()), start, end: self.pos, text: sym.to_string() };
            }
        }
        // Invalid character (e.g. '%' standalone, '\'' etc.)
        self.bump_char();
        let msg = format!("the character `{}` is not valid in code", c);
        // Reference: `%` gives exactly that message. For other chars use similar.
        self.err_at(msg, start, self.pos);
        Token{ tok: Tok::Sym(c.to_string()), start, end: self.pos, text: c.to_string() }
    }

    fn lex_number(&mut self, start: usize) -> Token {
        let rest = &self.src[start..];
        // Hex / oct / bin
        if rest.starts_with("0x") || rest.starts_with("0X") || rest.starts_with("0o") || rest.starts_with("0O") || rest.starts_with("0b") || rest.starts_with("0B") {
            let radix = match &rest[1..2] { "x"|"X" => 16, "o"|"O" => 8, _ => 2 };
            let mut end = 2;
            let bytes = rest.as_bytes();
            while end < rest.len() {
                let ch = bytes[end] as char;
                let valid = match radix { 16 => ch.is_ascii_hexdigit(), 8 => ('0'..='7').contains(&ch), _ => ch=='0'||ch=='1' };
                if valid || ch == '_' { end += 1; } else { break; }
            }
            let digits: String = rest[2..end].replace('_', "");
            let val = i64::from_str_radix(&digits, radix).unwrap_or(0);
            self.pos = start + end;
            // suffix?
            let suffix = self.lex_unit_suffix();
            if !suffix.is_empty() {
                return Token{ tok: Tok::Numeric(val as f64, suffix), start, end: self.pos, text: self.src[start..self.pos].to_string() };
            }
            return Token{ tok: Tok::Int(val, rest[..end].to_string()), start, end: self.pos, text: self.src[start..self.pos].to_string() };
        }
        // Decimal / float
        let mut i = 0usize;
        let bytes = rest.as_bytes();
        let mut seen_dot = false;
        let mut seen_exp = false;
        while i < rest.len() {
            let ch = bytes[i] as char;
            if ch.is_ascii_digit() || ch == '_' { i += 1; continue; }
            if ch == '.' && !seen_dot && !seen_exp {
                // ".." spread check: if next is '.' then stop.
                if i+1 < rest.len() && bytes[i+1] == b'.' { break; }
                seen_dot = true; i += 1; continue;
            }
            if (ch == 'e' || ch == 'E') && !seen_exp {
                // Could be exponent or 'em' unit — only exponent if followed by digit or +/-digit.
                let next = rest[i+1..].chars().next();
                let next2 = rest[i+1..].chars().nth(1);
                let is_exp = match next {
                    Some(n) if n.is_ascii_digit() => true,
                    Some('+') | Some('-') => next2.map(|n| n.is_ascii_digit()).unwrap_or(false),
                    _ => false,
                };
                if is_exp { seen_exp = true; i += 1; continue; } else { break; }
            }
            if (ch == '+' || ch == '-') && seen_exp && i > 0 && (bytes[i-1] == b'e' || bytes[i-1] == b'E') { i += 1; continue; }
            break;
        }
        // Trailing '.' with no digits after and not part of float like "1." — Typst treats "1." as float? Keep: if ends with '.', include it as float.
        let num_str = rest[..i].replace('_', "");
        self.pos = start + i;
        let suffix = self.lex_unit_suffix();
        let is_float = seen_dot || seen_exp;
        if !suffix.is_empty() {
            let val: f64 = num_str.parse().unwrap_or(0.0);
            return Token{ tok: Tok::Numeric(val, suffix), start, end: self.pos, text: self.src[start..self.pos].to_string() };
        }
        if is_float {
            let val: f64 = num_str.parse().unwrap_or(0.0);
            Token{ tok: Tok::Float(val), start, end: self.pos, text: self.src[start..self.pos].to_string() }
        } else {
            // Might overflow i64 → float
            match num_str.parse::<i64>() {
                Ok(v) => Token{ tok: Tok::Int(v, num_str), start, end: self.pos, text: self.src[start..self.pos].to_string() },
                Err(_) => {
                    let val: f64 = num_str.parse().unwrap_or(0.0);
                    Token{ tok: Tok::Float(val), start, end: self.pos, text: self.src[start..self.pos].to_string() }
                }
            }
        }
    }

    fn lex_unit_suffix(&mut self) -> String {
        if self.starts_with("%") {
            self.pos += 1;
            return "%".to_string();
        }
        let start = self.pos;
        let mut s = String::new();
        while let Some(c) = self.peek_char() {
            if c.is_alphabetic() { s.push(c); self.bump_char(); } else { break; }
        }
        let _ = start;
        s
    }

    fn lex_string(&mut self, start: usize) -> Token {
        // self.pos at opening quote
        self.bump_char(); // '"'
        let mut out = String::new();
        loop {
            match self.peek_char() {
                None => {
                    self.err_at("unclosed string".to_string(), start, self.pos);
                    break;
                }
                Some('"') => { self.bump_char(); break; }
                Some('\\') => {
                    self.bump_char();
                    match self.bump_char() {
                        Some('n') => out.push('\n'),
                        Some('r') => out.push('\r'),
                        Some('t') => out.push('\t'),
                        Some('\\') => out.push('\\'),
                        Some('"') => out.push('"'),
                        Some('`') => out.push('`'),
                        Some('{') => out.push('{'),
                        Some('}') => out.push('}'),
                        Some('$') => out.push('$'),
                        Some('#') => out.push('#'),
                        Some('[') => out.push('['),
                        Some(']') => out.push(']'),
                        Some('_') => out.push('_'),
                        Some('*') => out.push('*'),
                        Some('~') => out.push('\u{00a0}'),
                        Some('u') => {
                            // \u{XXXX} or \uXXXX ?
                            if self.peek_char() == Some('{') {
                                self.bump_char();
                                let mut hex = String::new();
                                while let Some(c) = self.peek_char() {
                                    if c == '}' { break; }
                                    hex.push(c); self.bump_char();
                                }
                                if self.peek_char() == Some('}') { self.bump_char(); }
                                if let Ok(n) = u32::from_str_radix(&hex, 16) {
                                    if let Some(ch) = char::from_u32(n) { out.push(ch); }
                                }
                            } else {
                                out.push('u');
                            }
                        }
                        Some(other) => out.push(other),
                        None => {}
                    }
                }
                Some(c) => { out.push(c); self.bump_char(); }
            }
        }
        Token{ tok: Tok::Str(out), start, end: self.pos, text: self.src[start..self.pos].to_string() }
    }

    pub fn tokenize_all(&mut self) -> Vec<Token> {
        let mut toks = Vec::new();
        loop {
            let t = self.next_token();
            let is_eof = t.tok == Tok::Eof;
            toks.push(t);
            if is_eof { break; }
        }
        toks
    }
}
