// Code-mode parser: parses expressions over a token stream. Content blocks `[...]` are
// handled by delegating to the markup parser on the raw source span (see MarkupDoc positions).
use crate::ast::*;
use crate::diag::Diag;
use crate::lexer::{Lexer, Tok, Token};
use crate::value::{LengthVal, Value};

pub struct Parser {
    pub toks: Vec<Token>,
    pub idx: usize,
    pub src: String,
    pub errors: Vec<Diag>,
}

const KEYWORDS_EXPR_START: &[&str] = &["none","auto","true","false"];

impl Parser {
    pub fn new(src: &str) -> Self {
        let mut lx = Lexer::new(src);
        let toks = lx.tokenize_all();
        let errors = lx.errors.clone();
        Parser{ toks, idx: 0, src: src.to_string(), errors }
    }
    pub fn new_from_tokens(src: &str, toks: Vec<Token>, mut errors: Vec<Diag>) -> Self {
        let _ = &mut errors;
        Parser{ toks, idx: 0, src: src.to_string(), errors }
    }
    fn peek(&self) -> &Token { &self.toks[self.idx.min(self.toks.len()-1)] }
    fn peek2(&self) -> &Token { &self.toks[(self.idx+1).min(self.toks.len()-1)] }
    fn bump(&mut self) -> Token { let t = self.toks[self.idx.min(self.toks.len()-1)].clone(); if self.idx < self.toks.len()-1 { self.idx += 1; } t }
    fn at_eof(&self) -> bool { self.peek().tok == Tok::Eof }
    fn is_sym(&self, s: &str) -> bool { self.peek().tok == Tok::Sym(s.to_string()) }
    fn is_ident(&self, s: &str) -> bool { matches!(&self.peek().tok, Tok::Ident(n) if n==s) }
    fn eat_sym(&mut self, s: &str) -> bool { if self.is_sym(s) { self.bump(); true } else { false } }
    fn eat_ident(&mut self, s: &str) -> bool { if self.is_ident(s) { self.bump(); true } else { false } }

    fn err(&mut self, msg: &str, start: usize, end: usize) {
        let (line, col) = crate::diag::line_col_of(&self.src, start);
        let len = self.src[start..end.min(self.src.len())].chars().count().max(1);
        self.errors.push(Diag::error_at(msg.to_string(), line, col, len));
    }
    fn err_tok(&mut self, msg: &str) {
        let t = self.peek().clone();
        // For EOF, point at end (col = last col?). Reference: `#let x =` points at col 8 (just past '=').
        self.err(msg, t.start, t.end.max(t.start+1));
    }

    /// Parse a full eval expression source. Returns expr (or a dummy on error).
    pub fn parse_eval(&mut self) -> SpExpr {
        if self.at_eof() {
            self.err_tok("expected expression");
            return SpExpr{ kind: ExprKind::NoneLit.boxed(), start: 0, end: 0 };
        }
        // Top-level statements? eval is usually a single expression but sequences like `1;2` produce join error.
        // We parse a code-block-like sequence: if there are multiple statements separated by `;` or juxtaposition of
        // non-content values, produce CodeBlock and let evaluator raise "cannot join ...".
        let expr = self.parse_expr_full();
        expr
    }

    // Full: handles statement keywords at expression position (let/set/show/import/include/if/for/while/context as expressions producing values via CodeBlock wrapper when needed)
    pub fn parse_expr_full(&mut self) -> SpExpr {
        // Statement-as-expression handling: collect leading stmts then final expr.
        // Only trigger if first token is a stmt keyword.
        if self.is_ident("let") || self.is_ident("set") || self.is_ident("import") || self.is_ident("include") || self.is_ident("for") {
            let start = self.peek().start;
            let mut stmts = Vec::new();
            while !self.at_eof() && !self.is_sym("}") && !self.is_sym("]") && !self.is_sym(")") {
                // Try a statement; if it consumes something and next is EOF/;/expr-start, continue.
                let before = self.idx;
                if let Some(st) = self.try_parse_stmt() {
                    stmts.push(st);
                    self.eat_sym(";");
                    // If next token starts an expression that is not a stmt keyword, parse as final expr below.
                    if self.at_eof() || self.is_sym("}") || self.is_sym("]") || self.is_sym(")") { break; }
                    if !(self.is_ident("let") || self.is_ident("set") || self.is_ident("show") || self.is_ident("import") || self.is_ident("include") || self.is_ident("for") || self.is_ident("while")) {
                        break;
                    }
                } else {
                    if self.idx == before { break; }
                }
            }
            if !self.at_eof() && !self.is_sym("}") && !self.is_sym("]") && !self.is_sym(")") {
                let e = self.parse_expr();
                stmts.push(Stmt::Expr(e));
            }
            let end = self.peek().start;
            return SpExpr{ kind: ExprKind::CodeBlock(stmts).boxed(), start, end };
        }
        self.parse_expr()
    }

    pub fn try_parse_stmt(&mut self) -> Option<Stmt> {
        if self.is_ident("let") {
            self.bump();
            // let func(params) = body | let name = expr | let (a,b) = expr | let name
            if self.is_sym("(") {
                // pattern
                self.bump();
                let mut names = Vec::new();
                loop {
                    if let Tok::Ident(n) = self.peek().tok.clone() { names.push(n); self.bump(); } else { break; }
                    if !self.eat_sym(",") { break; }
                    if self.is_sym(")") { break; }
                }
                self.eat_sym(")");
                if self.eat_sym("=") {
                    let v = self.parse_expr();
                    return Some(Stmt::LetPattern(names, v));
                }
                return Some(Stmt::LetPattern(names, SpExpr{kind: ExprKind::NoneLit.boxed(), start:0, end:0}));
            }
            if let Tok::Ident(name) = self.peek().tok.clone() {
                self.bump();
                if self.is_sym("(") {
                    // function def
                    let (params, vararg) = self.parse_params();
                    if self.eat_sym("=") {
                        let body = self.parse_expr_full();
                        return Some(Stmt::LetFunc(name, params, vararg, body));
                    } else {
                        return Some(Stmt::LetFunc(name, params, vararg, SpExpr{kind: ExprKind::NoneLit.boxed(), start:0, end:0}));
                    }
                }
                if self.eat_sym("=") {
                    let v = self.parse_expr();
                    return Some(Stmt::Let(name, Some(v)));
                }
                return Some(Stmt::Let(name, None));
            }
            self.err_tok("expected pattern");
            return Some(Stmt::Let(String::new(), None));
        }
        if self.is_ident("set") {
            let start = self.peek().start;
            self.bump();
            // set ident(...)[...]? or set ident
            if let Tok::Ident(_) = self.peek().tok.clone() {
                let e = self.parse_postfix_primary_chain();
                let _ = start;
                return Some(Stmt::SetRule(e));
            }
            self.err_tok("expected identifier");
            return Some(Stmt::ShowRule);
        }
        if self.is_ident("show") {
            // show ... : ...  — consume to end of line-ish (until ; or EOF or newline at token level can't detect; consume until ':' then a primary)
            self.bump();
            // skip tokens until ':' at depth 0
            let mut depth = 0i32;
            while !self.at_eof() {
                match &self.peek().tok {
                    Tok::Sym(s) if s=="("||s=="["||s=="{" => { depth+=1; self.bump(); }
                    Tok::Sym(s) if s==")"||s=="]"||s=="}" => { if depth==0 { break; } depth-=1; self.bump(); }
                    Tok::Sym(s) if s==":" && depth==0 => { self.bump(); break; }
                    Tok::Sym(s) if s==";" && depth==0 => break,
                    _ => { self.bump(); }
                }
            }
            if !self.at_eof() && !self.is_sym(";") && !self.is_sym(")") && !self.is_sym("}") {
                let _ = self.parse_expr();
            }
            return Some(Stmt::ShowRule);
        }
        if self.is_ident("import") {
            self.bump();
            // import "path": a, b as c | import "path": * | import @pkg/... (path may be string only in practice)
            let path = if let Tok::Str(s) = self.peek().tok.clone() { self.bump(); s } else {
                // package path like @preview/foo: parse as raw? treat following expr text as path string
                let e = self.parse_expr();
                crate::markup::expr_to_path_string(&e, &self.src)
            };
            let mut all = false;
            let mut items: Vec<(String,String)> = Vec::new();
            if self.eat_sym(":") {
                if self.eat_sym("*") { all = true; }
                else {
                    loop {
                        if let Tok::Ident(n) = self.peek().tok.clone() {
                            self.bump();
                            let mut alias = n.clone();
                            if self.is_ident("as") { self.bump(); if let Tok::Ident(a)=self.peek().tok.clone() { alias=a; self.bump(); } }
                            items.push((n, alias));
                        } else { break; }
                        if !self.eat_sym(",") { break; }
                        if matches!(&self.peek().tok, Tok::Eof) || self.is_sym(";") || self.is_sym("}") { break; }
                    }
                }
            }
            if all { return Some(Stmt::ImportAll(path)); }
            return Some(Stmt::Import(path, items));
        }
        if self.is_ident("include") {
            self.bump();
            if let Tok::Str(s) = self.peek().tok.clone() { self.bump(); return Some(Stmt::Include(s)); }
            let e = self.parse_expr();
            return Some(Stmt::Include(crate::markup::expr_to_path_string(&e, &self.src)));
        }
        if self.is_ident("for") {
            self.bump();
            // for x in expr { body } | for (k,v) in expr {...} | for x in expr [markup]? (markup handled elsewhere; here expect code block)
            let mut vars = Vec::new();
            if self.eat_sym("(") {
                loop {
                    if let Tok::Ident(n)=self.peek().tok.clone() { vars.push(n); self.bump(); }
                    if !self.eat_sym(",") { break; }
                    if self.is_sym(")") { break; }
                }
                self.eat_sym(")");
            } else if let Tok::Ident(n)=self.peek().tok.clone() { vars.push(n); self.bump(); }
            else { self.err_tok("expected pattern"); }
            if self.is_ident("in") { self.bump(); } else { self.err_tok("expected keyword `in`"); }
            let iter = self.parse_expr_no_block();
            let body = self.parse_block_stmts();
            return Some(Stmt::For(vars, iter, body));
        }
        if self.is_ident("while") {
            self.bump();
            let cond = self.parse_expr_no_block();
            let body = self.parse_block_stmts();
            return Some(Stmt::While(cond, body));
        }
        if self.is_ident("break") { self.bump(); return Some(Stmt::Break); }
        if self.is_ident("continue") { self.bump(); return Some(Stmt::Continue); }
        if self.is_ident("return") {
            self.bump();
            if self.at_eof() || self.is_sym(";") || self.is_sym("}") || self.is_sym(")") || self.is_sym(",") {
                return Some(Stmt::Return(None));
            }
            let e = self.parse_expr();
            return Some(Stmt::Return(Some(e)));
        }
        if self.is_ident("context") {
            self.bump();
            if self.is_sym("{") {
                let body = self.parse_block_stmts();
                return Some(Stmt::Context(body));
            }
            let e = self.parse_expr();
            return Some(Stmt::Context(vec![Stmt::Expr(e)]));
        }
        None
    }

    fn parse_params(&mut self) -> (Vec<String>, Option<String>) {
        // assumes current tok is '('
        self.eat_sym("(");
        let mut params = Vec::new();
        let mut vararg = None;
        loop {
            if self.is_sym(")") { self.bump(); break; }
            if self.at_eof() { break; }
            if self.is_sym("..") || self.is_sym("...") {
                self.bump();
                if let Tok::Ident(n)=self.peek().tok.clone() { vararg=Some(n); self.bump(); }
            } else if let Tok::Ident(n)=self.peek().tok.clone() {
                params.push(n); self.bump();
                // default value `: expr`? In Typst, `let f(x: 1) = ...`? Actually named with default uses `:`? Skip: if ':' then skip expr.
                if self.eat_sym(":") { let _ = self.parse_expr(); }
            } else if self.is_sym("(") {
                // destructured param — flatten names
                self.bump();
                loop {
                    if let Tok::Ident(n)=self.peek().tok.clone() { params.push(n); self.bump(); }
                    if !self.eat_sym(",") { break; }
                    if self.is_sym(")") { break; }
                }
                self.eat_sym(")");
            } else {
                self.bump();
            }
            if !self.eat_sym(",") {
                if self.is_sym(")") { self.bump(); }
                break;
            }
        }
        (params, vararg)
    }

    pub fn parse_block_stmts(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        if !self.eat_sym("{") {
            // Single expression body?
            self.err_tok("expected block");
            return stmts;
        }
        loop {
            while self.eat_sym(";") {}
            if self.at_eof() { self.err_tok("unclosed block"); break; }
            if self.eat_sym("}") { break; }
            if let Some(st) = self.try_parse_stmt() {
                stmts.push(st);
                continue;
            }
            if self.is_ident("if") {
                let e = self.parse_expr();
                stmts.push(Stmt::Expr(e));
                continue;
            }
            // Assignment detection: ident (=|+=|...) or expr . field =
            let save = self.idx;
            let e = self.parse_expr();
            // assignment ops
            let op = if self.is_sym("=") { Some("=") } else if self.is_sym("+=") { Some("+=") } else if self.is_sym("-=") { Some("-=") } else if self.is_sym("*=") { Some("*=") } else if self.is_sym("/=") { Some("/=") } else { None };
            if let Some(op) = op {
                // LHS must be ident or field
                self.bump();
                let rhs = self.parse_expr();
                match &*e.kind {
                    ExprKind::Ident(name, _, _) => { stmts.push(Stmt::Assign(name.clone(), op.to_string(), rhs)); }
                    ExprKind::Field(base, field, _, _) => {
                        let b = SpExpr{ kind: base.kind.clone(), start: base.start, end: base.end };
                        stmts.push(Stmt::AssignField(b, field.clone(), op.to_string(), rhs));
                    }
                    _ => { stmts.push(Stmt::Expr(e)); stmts.push(Stmt::Expr(rhs)); }
                }
                let _ = save;
                continue;
            }
            stmts.push(Stmt::Expr(e));
        }
        stmts
    }

    // Expression without consuming a trailing block as if-body etc. (for loop headers we parse with restricted if handling)
    fn parse_expr_no_block(&mut self) -> SpExpr { self.parse_binary(0) }

    pub fn parse_expr(&mut self) -> SpExpr {
        // if / context / blocks as expressions
        if self.is_ident("if") {
            return self.parse_if();
        }
        if self.is_ident("context") {
            let start = self.peek().start;
            self.bump();
            if self.is_sym("{") {
                let body = self.parse_block_stmts();
                let end = self.peek().start;
                return SpExpr{ kind: ExprKind::CodeBlock(body).boxed(), start, end };
            }
            let e = self.parse_expr();
            let end = e.end;
            return SpExpr{ kind: e.kind, start, end };
        }
        if self.is_ident("for") || self.is_ident("while") || self.is_ident("let") || self.is_ident("set") || self.is_ident("break") || self.is_ident("continue") || self.is_ident("return") {
            let start = self.peek().start;
            if let Some(st) = self.try_parse_stmt() {
                let end = self.peek().start;
                return SpExpr{ kind: ExprKind::CodeBlock(vec![st]).boxed(), start, end };
            }
        }
        // Sequence joining at code-block level is handled by caller; here binary expression.
        self.parse_binary(0)
    }

    fn parse_if(&mut self) -> SpExpr {
        let start = self.peek().start;
        self.bump(); // if
        let cond = self.parse_binary(0);
        // then: block {..} or single expr? Typst requires block. Support {..} and [..] content.
        let then_e = if self.is_sym("{") {
            let body = self.parse_block_stmts();
            SpExpr{ kind: ExprKind::CodeBlock(body).boxed(), start, end: self.peek().start }
        } else if self.is_sym("[") {
            self.parse_primary()
        } else {
            self.err_tok("expected block");
            self.parse_binary(0)
        };
        let else_e = if self.is_ident("else") {
            self.bump();
            if self.is_ident("if") {
                Some(self.parse_if())
            } else if self.is_sym("{") {
                let body = self.parse_block_stmts();
                Some(SpExpr{ kind: ExprKind::CodeBlock(body).boxed(), start, end: self.peek().start })
            } else if self.is_sym("[") {
                Some(self.parse_primary())
            } else {
                Some(self.parse_expr())
            }
        } else { None };
        let end = else_e.as_ref().map(|e| e.end).unwrap_or(then_e.end);
        SpExpr{ kind: ExprKind::If(cond, then_e, else_e).boxed(), start, end }
    }

    fn binding_power(op: &str) -> Option<u8> {
        Some(match op {
            "or" => 1,
            "and" => 2,
            "==" | "!=" | "<" | "<=" | ">" | ">=" | "in" | "not-in" => 3,
            "+" | "-" => 4,
            "*" | "/" => 5,
            _ => return None,
        })
    }

    pub fn parse_binary(&mut self, min_bp: u8) -> SpExpr {
        let mut lhs = self.parse_unary();
        loop {
            // binary operator?
            let (op, bp) = match &self.peek().tok {
                Tok::Sym(s) => {
                    match Self::binding_power(s) { Some(b)=> (s.clone(), b), None=> break }
                }
                Tok::Ident(n) if n=="and" || n=="or" || n=="in" => (n.clone(), Self::binding_power(n).unwrap()),
                _ => break,
            };
            if bp <= min_bp { break; }
            self.bump();
            // `not in`
            let op = if op == "in" { op } else { op };
            let rhs = self.parse_binary(bp);
            let start = lhs.start; let end = rhs.end;
            lhs = SpExpr{ kind: ExprKind::Binary(op, lhs, rhs).boxed(), start, end };
        }
        lhs
    }

    fn parse_unary(&mut self) -> SpExpr {
        if self.is_sym("-") {
            let t = self.bump();
            let e = self.parse_unary();
            let end = e.end;
            return SpExpr{ kind: ExprKind::Unary("-".into(), e).boxed(), start: t.start, end };
        }
        if self.is_sym("+") {
            let t = self.bump();
            let e = self.parse_unary();
            let end = e.end;
            return SpExpr{ kind: ExprKind::Unary("+".into(), e).boxed(), start: t.start, end };
        }
        if self.is_ident("not") {
            // `not in` handled in binary? `x not in y` — rare; ignore. Here prefix not.
            let t = self.bump();
            if self.is_ident("in") {
                // shouldn't happen as prefix; treat as error path
            }
            let e = self.parse_unary();
            let end = e.end;
            return SpExpr{ kind: ExprKind::Unary("not".into(), e).boxed(), start: t.start, end };
        }
        self.parse_postfix_primary_chain()
    }

    pub fn parse_postfix_primary_chain(&mut self) -> SpExpr {
        let mut e = self.parse_primary();
        loop {
            if self.is_sym(".") {
                // field access (but `..` is different token, and `.5` handled in number lexer)
                self.bump();
                if let Tok::Ident(name) = self.peek().tok.clone() {
                    let t = self.bump();
                    let start = e.start;
                    e = SpExpr{ kind: ExprKind::Field(e, name, t.start, t.end).boxed(), start, end: t.end };
                    continue;
                } else {
                    self.err_tok("expected field access");
                    break;
                }
            }
            if self.is_sym("(") {
                // call
                let args = self.parse_args();
                // trailing content block(s): f(...)[..] — merge multiple into sequence? take first, extra become separate args at eval (simplify: combine)
                let mut trailing: Option<crate::markup::MarkupDoc> = None;
                if self.is_sym("[") {
                    if let Some(doc) = self.parse_content_block() { trailing = Some(doc); }
                    // additional blocks: append children textually? Wrap: create combined doc by merging nodes.
                    while self.is_sym("[") {
                        if let Some(mut doc2) = self.parse_content_block() {
                            if let Some(t) = &mut trailing { t.nodes.append(&mut doc2.nodes); } else { trailing = Some(doc2); }
                        } else { break; }
                    }
                }
                let start = e.start; let end = self.peek().start;
                e = SpExpr{ kind: ExprKind::Call(e, args, trailing).boxed(), start, end };
                continue;
            }
            if self.is_sym("[") {
                // Callee without parens: strong[Hi]  OR indexing attempt `(1,2)[0]` (reference errors "expected function") — parse as Call with empty args so eval reproduces the error for non-functions.
                if let Some(doc) = self.parse_content_block() {
                    let start = e.start; let end = self.peek().start;
                    e = SpExpr{ kind: ExprKind::Call(e, Vec::new(), Some(doc)).boxed(), start, end };
                    continue;
                } else { break; }
            }
            break;
        }
        e
    }

    fn parse_args(&mut self) -> Vec<ParenItem> {
        // current tok is '('
        self.eat_sym("(");
        let mut items = Vec::new();
        loop {
            if self.is_sym(")") { self.bump(); break; }
            if self.at_eof() { self.err_tok("unclosed delimiter"); break; }
            if self.is_sym("..") || self.is_sym("...") {
                self.bump();
                let e = self.parse_expr();
                items.push(ParenItem::Spread(e));
            } else {
                // named? ident ':' (but not `::`, and not label etc.) Need lookahead: Ident followed by ':'
                let is_named = matches!(&self.peek().tok, Tok::Ident(_)) && *&self.peek2().tok == Tok::Sym(":".to_string());
                if is_named {
                    let name = if let Tok::Ident(n)=self.bump().tok { n } else { String::new() };
                    self.bump(); // ':'
                    // dict-entry with empty value `(:)` handled in paren-items path, not call args; here a value is expected.
                    if self.is_sym(")") || self.is_sym(",") {
                        self.err_tok("expected expression");
                        items.push(ParenItem::Named(name, SpExpr{kind: ExprKind::NoneLit.boxed(), start:0, end:0}));
                    } else {
                        let v = self.parse_expr();
                        items.push(ParenItem::Named(name, v));
                    }
                } else {
                    let e = self.parse_expr();
                    items.push(ParenItem::Pos(e));
                }
            }
            if self.eat_sym(",") { continue; }
            if self.is_sym(")") { self.bump(); break; }
            if self.at_eof() { self.err_tok("unclosed delimiter"); break; }
            // Missing comma: reference would error "expected comma"; recover by continuing.
            // But only error if next token isn't ')'
            // self.err_tok("expected comma"); (avoid spurious errors in edge parses)
        }
        items
    }

    /// Parse `(` items `)` as array/dict/paren/closure-params. Returns SpExpr.
    fn parse_paren(&mut self) -> SpExpr {
        let open = self.bump(); // '('
        // Empty parens could be closure `() => ...`
        if self.is_sym(")") {
            self.bump();
            if self.is_sym("=>") {
                self.bump();
                let body = self.parse_expr();
                let end = body.end;
                return SpExpr{ kind: ExprKind::Closure(Vec::new(), None, body).boxed(), start: open.start, end };
            }
            return SpExpr{ kind: ExprKind::ParenItems(Vec::new()).boxed(), start: open.start, end: self.peek().start };
        }
        // `(:)` empty dict
        if self.is_sym(":") {
            self.bump();
            self.eat_sym(")");
            return SpExpr{ kind: ExprKind::ParenItems(vec![]).boxed(), start: open.start, end: self.peek().start };
            // Note: eval must distinguish () (array) vs (:) (dict). Encode with a sentinel Named with empty name.
        }
        // Distinguish (:) by inserting sentinel — handle above properly:
        // (Handled: we returned empty items; eval treats () as empty array. For (:) we need dict marker; fix by checking source.)
        // The above is unreachable issue: rework — see parse_paren_items below.
        unreachable!()
    }

    fn parse_content_block(&mut self) -> Option<crate::markup::MarkupDoc> {
        // Current token must be '[' (Tok::Sym("[")). We need the raw source span up to matching ']'
        // accounting for nesting, strings, escapes, code blocks, math, raw.
        // Because tokens were lexed in code mode, '[' inside markup plain text was split incorrectly (e.g. `Hello` inside [Hello] lexes as Ident — fine),
        // but characters like '!' '*' '_' etc. are separate tokens. Rather than reconstruct from tokens, we scan the raw source from the '[' byte offset.
        let open_tok = self.peek().clone();
        if open_tok.tok != Tok::Sym("[".to_string()) { return None; }
        let start_byte = open_tok.start;
        let inner_start = open_tok.end;
        let (inner_end, after) = crate::markup::scan_content_block(&self.src, start_byte);
        let inner_src = self.src[inner_start..inner_end].to_string();
        // Advance token index past all tokens with start < after.
        while self.idx < self.toks.len() && self.toks[self.idx].start < after {
            self.idx += 1;
        }
        let mut doc = crate::markup::parse_markup(&inner_src);
        doc.base_offset = inner_start;
        Some(doc)
    }

    pub fn parse_primary(&mut self) -> SpExpr {
        let t = self.peek().clone();
        match &t.tok {
            Tok::Int(v, _) => { self.bump(); SpExpr{ kind: ExprKind::IntLit(*v).boxed(), start: t.start, end: t.end } }
            Tok::Float(v) => { self.bump(); SpExpr{ kind: ExprKind::FloatLit(*v).boxed(), start: t.start, end: t.end } }
            Tok::Numeric(val, unit) => {
                self.bump();
                match numeric_value(*val, unit) {
                    Ok(v) => SpExpr{ kind: ExprKind::ValueLit(v).boxed(), start: t.start, end: t.end },
                    Err(msg) => {
                        self.err(&msg, t.start, t.end);
                        SpExpr{ kind: ExprKind::FloatLit(*val).boxed(), start: t.start, end: t.end }
                    }
                }
            }
            Tok::Str(s) => { let s=s.clone(); self.bump(); SpExpr{ kind: ExprKind::StrLit(s).boxed(), start: t.start, end: t.end } }
            Tok::Label(l) => { let l=l.clone(); self.bump(); SpExpr{ kind: ExprKind::LabelLit(l).boxed(), start: t.start, end: t.end } }
            Tok::Ident(name) => {
                let name = name.clone();
                match name.as_str() {
                    "none" => { self.bump(); SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end } }
                    "auto" => { self.bump(); SpExpr{ kind: ExprKind::AutoLit.boxed(), start: t.start, end: t.end } }
                    "true" => { self.bump(); SpExpr{ kind: ExprKind::BoolLit(true).boxed(), start: t.start, end: t.end } }
                    "false" => { self.bump(); SpExpr{ kind: ExprKind::BoolLit(false).boxed(), start: t.start, end: t.end } }
                    "if" => self.parse_if(),
                    "context" => self.parse_expr(),
                    "else" => { self.bump(); self.err("unexpected keyword `else`", t.start, t.end); SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end } }
                    "in" => { self.bump(); self.err("unexpected keyword `in`", t.start, t.end); SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end } }
                    "as" => { self.bump(); self.err("unexpected keyword `as`", t.start, t.end); SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end } }
                    "and" => { self.bump(); self.err("unexpected operator `and`", t.start, t.end); SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end } }
                    "or" => { self.bump(); self.err("unexpected operator `or`", t.start, t.end); SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end } }
                    "not" => self.parse_unary(),
                    "let" | "set" | "show" | "for" | "while" | "import" | "include" | "break" | "continue" | "return" => {
                        // Statement keywords in primary position produce specific parse errors in reference for bare `eval let` etc.
                        // If followed by operands, treat as statement expr; bare keyword → the stmt parser emits the right-ish error.
                        self.parse_expr()
                    }
                    _ => {
                        // Closure single param without parens: `x => body`
                        if self.peek2().tok == Tok::Sym("=>".to_string()) {
                            self.bump(); // ident
                            self.bump(); // =>
                            let body = self.parse_expr();
                            let end = body.end;
                            return SpExpr{ kind: ExprKind::Closure(vec![name], None, body).boxed(), start: t.start, end };
                        }
                        self.bump();
                        SpExpr{ kind: ExprKind::Ident(name, t.start, t.end).boxed(), start: t.start, end: t.end }
                    }
                }
            }
            Tok::Sym(s) if s == "(" => {
                self.parse_paren_items()
            }
            Tok::Sym(s) if s == "[" => {
                if let Some(doc) = self.parse_content_block() {
                    SpExpr{ kind: ExprKind::ContentBlock(doc).boxed(), start: t.start, end: self.peek().start }
                } else {
                    self.bump();
                    SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end }
                }
            }
            Tok::Sym(s) if s == "{" => {
                let start = t.start;
                let body = self.parse_block_stmts();
                SpExpr{ kind: ExprKind::CodeBlock(body).boxed(), start, end: self.peek().start }
            }
            Tok::Sym(s) if s == "$" => {
                // Math in code context (eval `$x^2$`): scan raw source to closing '$'.
                let start_byte = t.start;
                let rest = &self.src[start_byte+1..];
                let mut close_off: Option<usize> = None;
                let mut escaped = false;
                for (i, ch) in rest.char_indices() {
                    if escaped { escaped = false; continue; }
                    if ch == '\\' { escaped = true; continue; }
                    if ch == '$' { close_off = Some(start_byte + 1 + i); break; }
                }
                match close_off {
                    Some(close) => {
                        let inner = self.src[start_byte+1..close].to_string();
                        let after = close + 1;
                        while self.idx < self.toks.len() && self.toks[self.idx].start < after { self.idx += 1; }
                        let block = inner.starts_with(' ') && inner.ends_with(' ') && inner.trim().len() > 0 || (inner.starts_with(char::is_whitespace) && inner.ends_with(char::is_whitespace) && !inner.trim().is_empty());
                        // Typst rule (approx): block if space on both sides (or newline).
                        let block = {
                            let first = inner.chars().next();
                            let last = inner.chars().last();
                            matches!(first, Some(c) if c.is_whitespace()) && matches!(last, Some(c) if c.is_whitespace()) && !inner.trim().is_empty()
                        };
                        let _ = block;
                        let trimmed_block = block;
                        SpExpr{ kind: ExprKind::Equation(inner.trim().to_string(), trimmed_block).boxed(), start: t.start, end: after }
                    }
                    None => {
                        self.bump();
                        self.err("expected dollar sign", t.start, t.end);
                        SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end }
                    }
                }
            }
            Tok::Sym(s) if s == ".." || s == "..." => {
                self.bump();
                let e = self.parse_expr();
                let end = e.end;
                SpExpr{ kind: ExprKind::Spread(e).boxed(), start: t.start, end }
            }
            Tok::Sym(s) if s == "-" || s == "+" => {
                self.parse_unary()
            }
            Tok::Eof => {
                self.err_tok("expected expression");
                SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end }
            }
            _ => {
                // Unexpected token.
                let txt = t.text.clone();
                self.bump();
                // Choose message: for ')' ']' '}' etc reference says "expected expression".
                let _ = txt;
                self.err("expected expression", t.start, t.end.max(t.start+1));
                SpExpr{ kind: ExprKind::NoneLit.boxed(), start: t.start, end: t.end }
            }
        }
    }

    fn parse_paren_items(&mut self) -> SpExpr {
        let open = self.bump(); // '('
        if self.is_sym(")") {
            self.bump();
            if self.is_sym("=>") {
                self.bump();
                let body = self.parse_expr();
                let end = body.end;
                return SpExpr{ kind: ExprKind::Closure(Vec::new(), None, body).boxed(), start: open.start, end };
            }
            return SpExpr{ kind: ExprKind::ParenItems(Vec::new()).boxed(), start: open.start, end: self.peek().start };
        }
        if self.is_sym(":") {
            // empty dict (:)  — encode as ParenItems with a single sentinel Named("", NoneLit) that eval interprets as empty dict.
            self.bump();
            self.eat_sym(")");
            let sentinel = SpExpr{ kind: ExprKind::NoneLit.boxed(), start: open.start, end: open.end };
            return SpExpr{ kind: ExprKind::ParenItems(vec![ParenItem::Named("\u{1}empty-dict".to_string(), sentinel)]).boxed(), start: open.start, end: self.peek().start };
        }
        let mut items: Vec<ParenItem> = Vec::new();
        let mut has_comma = false;
        loop {
            if self.is_sym(")") { self.bump(); break; }
            if self.at_eof() { self.err_tok("unclosed delimiter"); break; }
            if self.is_sym("..") || self.is_sym("...") {
                self.bump();
                // closure param sink handled at closure-detection stage below by inspecting items; store as Spread(Ident)
                let e = self.parse_expr();
                items.push(ParenItem::Spread(e));
            } else {
                let is_named = matches!(&self.peek().tok, Tok::Ident(_)) && self.peek2().tok == Tok::Sym(":".to_string());
                // Also string keys: ("key": value)
                let is_str_named = matches!(&self.peek().tok, Tok::Str(_)) && self.peek2().tok == Tok::Sym(":".to_string());
                if is_named {
                    let name = if let Tok::Ident(n)=self.bump().tok { n } else { String::new() };
                    self.bump(); // ':'
                    let v = self.parse_expr();
                    items.push(ParenItem::Named(name, v));
                } else if is_str_named {
                    let name = if let Tok::Str(n)=self.bump().tok { n } else { String::new() };
                    self.bump();
                    let v = self.parse_expr();
                    items.push(ParenItem::Named(name, v));
                } else {
                    let e = self.parse_expr();
                    items.push(ParenItem::Pos(e));
                }
            }
            if self.eat_sym(",") { has_comma = true; continue; }
            if self.is_sym(")") { self.bump(); break; }
            if self.at_eof() { self.err_tok("unclosed delimiter"); break; }
            // unexpected: break to avoid infinite loop
            break;
        }
        let _ = has_comma;
        // Closure detection: `(x) => body` / `(x, y) => body` / `(..args) => body`
        if self.is_sym("=>") {
            let mut params: Vec<String> = Vec::new();
            let mut vararg: Option<String> = None;
            let mut ok = true;
            for it in &items {
                match it {
                    ParenItem::Pos(e) => {
                        if let ExprKind::Ident(n, _, _) = &*e.kind { params.push(n.clone()); } else { ok = false; }
                    }
                    ParenItem::Spread(e) => {
                        if let ExprKind::Ident(n, _, _) = &*e.kind { vararg = Some(n.clone()); } else { ok = false; }
                    }
                    ParenItem::Named(n, _) => { params.push(n.clone()); } // param with default: ignore default
                }
            }
            if ok {
                self.bump(); // =>
                let body = self.parse_expr();
                let end = body.end;
                return SpExpr{ kind: ExprKind::Closure(params, vararg, body).boxed(), start: open.start, end };
            }
        }
        SpExpr{ kind: ExprKind::ParenItems(items).boxed(), start: open.start, end: self.peek().start }
    }
}

pub fn numeric_value(val: f64, unit: &str) -> Result<Value, String> {
    match unit {
        "%" => Ok(Value::Ratio(val / 100.0)),
        "pt" => Ok(Value::Length(LengthVal{ pt: val, em: 0.0 })),
        "mm" => Ok(Value::Length(LengthVal{ pt: val * 72.0 / 25.4, em: 0.0 })),
        "cm" => Ok(Value::Length(LengthVal{ pt: val * 72.0 / 2.54, em: 0.0 })),
        "in" => Ok(Value::Length(LengthVal{ pt: val * 72.0, em: 0.0 })),
        "em" => Ok(Value::Length(LengthVal{ pt: 0.0, em: val })),
        "deg" => Ok(Value::Angle(val)),
        "rad" => Ok(Value::Angle(val * 180.0 / std::f64::consts::PI)),
        "fr" => Ok(Value::Fraction(val)),
        "" => Ok(Value::Float(val)),
        other => Err(format!("invalid number suffix: {}", other)),
    }
}

pub fn parse_eval_expression(src: &str) -> (SpExpr, Vec<Diag>, Parser) {
    let mut p = Parser::new(src);
    let e = p.parse_eval_surface();
    let errs = p.errors.clone();
    (e, errs, p)
}

impl Parser {
    // Surface handling for `eval`: sequences with `;` or newline-joined exprs (e.g. `1 // c\n+2` in reference gives join error — meaning comment-newline split it into two code lines?).
    // Typst code blocks join consecutive expressions. For eval, `1;2` errors cannot join. Our parse: if after first expr there's `;` or another expr start, wrap in CodeBlock with multiple Expr stmts → evaluator's join rule fires.
    pub fn parse_eval_surface(&mut self) -> SpExpr {
        if self.at_eof() {
            self.err_tok("expected expression");
            return SpExpr{ kind: ExprKind::NoneLit.boxed(), start: 0, end: 0 };
        }
        let first = self.parse_expr_full();
        // Trailing `;` sequence?
        if self.is_sym(";") {
            let mut stmts = vec![Stmt::Expr(first)];
            while self.eat_sym(";") {
                if self.at_eof() { break; }
                if let Some(st) = self.try_parse_stmt() { stmts.push(st); }
                else { let e = self.parse_expr(); stmts.push(Stmt::Expr(e)); }
            }
            let end = self.peek().start;
            return SpExpr{ kind: ExprKind::CodeBlock(stmts).boxed(), start: 0, end };
        }
        // Leftover tokens: e.g. `show` produces extra diagnostics; `1 // hi\n+ 2` → after `1`, next is `+`? Binary parser would consume `1+2`... but reference gave join error.
        // Reason: `//` comment ends the "code line", and `+ 2` on next line is a new statement? Hmm. Reproduce: if the source contains a `//` comment followed by newline then `+`, reference parses as two joined exprs (1 and +2?) → join error.
        // Simplify: if leftover exists, try parsing more exprs and wrap as CodeBlock (join semantics).
        if !self.at_eof() && !self.is_sym(")") && !self.is_sym("]") && !self.is_sym("}") && !self.is_sym(",") {
            let mut stmts = vec![Stmt::Expr(first)];
            let mut guard = 0;
            while !self.at_eof() && guard < 20 {
                guard += 1;
                let before = self.idx;
                if let Some(st) = self.try_parse_stmt() { stmts.push(st); }
                else {
                    let e = self.parse_expr();
                    stmts.push(Stmt::Expr(e));
                }
                if self.idx == before { self.bump(); }
                self.eat_sym(";");
            }
            let end = self.peek().start;
            return SpExpr{ kind: ExprKind::CodeBlock(stmts).boxed(), start: 0, end };
        }
        first
    }
}
