/// Minimal TOML: key = value lines, [sections], strings/ints/floats/bools/arrays. Good enough for typst.toml and simple data.
pub fn parse_toml_str(s: &str) -> Value {
    // Build nested dict via paths.
    let mut root: Vec<(String, Value)> = Vec::new();
    let mut current_path: Vec<String> = Vec::new();
    for raw_line in s.lines() {
        let line = strip_toml_comment(raw_line).trim().to_string();
        if line.is_empty() { continue; }
        if line.starts_with('[') && line.ends_with(']') && !line.starts_with("[[") {
            let inner = line[1..line.len()-1].trim();
            current_path = inner.split('.').map(|p| unquote(p.trim())).collect();
            ensure_dict_path(&mut root, &current_path);
            continue;
        }
        if line.starts_with("[[") { continue; }
        if let Some(eq) = line.find('=') {
            let key = unquote(line[..eq].trim());
            let val_src = line[eq+1..].trim();
            let val = parse_toml_value(val_src);
            let mut full = current_path.clone();
            // dotted keys
            let parts: Vec<String> = key.split('.').map(|p| unquote(p.trim())).collect();
            full.extend(parts);
            set_dict_path(&mut root, &full, val);
        }
    }
    Value::Dict(root)
}

fn unquote(s: &str) -> String {
    let t = s.trim();
    if (t.starts_with('"') && t.ends_with('"') && t.len()>=2) || (t.starts_with('\'') && t.ends_with('\'') && t.len()>=2) {
        t[1..t.len()-1].to_string()
    } else { t.to_string() }
}

fn strip_toml_comment(line: &str) -> String {
    let mut in_str: Option<char> = None;
    let mut out = String::new();
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match in_str {
            Some(q) => { out.push(c); if c == q { in_str = None; } }
            None => {
                if c == '"' || c == '\'' { in_str = Some(c); out.push(c); }
                else if c == '#' { break; }
                else { out.push(c); }
            }
        }
        let _ = chars.clone(); // silence
        // Note: peekable clone hack not needed; keep simple.
        let _ = &chars;
    }
    out
}

fn ensure_dict_path(root: &mut Vec<(String, Value)>, path: &[String]) {
    if path.is_empty() { return; }
    // navigate creating dicts
    fn nav<'a>(entries: &'a mut Vec<(String, Value)>, path: &[String]) {
        if path.is_empty() { return; }
        let key = &path[0];
        let idx = entries.iter().position(|(k,_)| k == key);
        let idx = match idx {
            Some(i) => i,
            None => { entries.push((key.clone(), Value::Dict(Vec::new()))); entries.len()-1 }
        };
        if let Value::Dict(inner) = &mut entries[idx].1 {
            nav(inner, &path[1..]);
        }
    }
    nav(root, path);
}

fn set_dict_path(root: &mut Vec<(String, Value)>, path: &[String], val: Value) {
    if path.is_empty() { return; }
    if path.len() == 1 {
        let key = &path[0];
        if let Some(e) = root.iter_mut().find(|(k,_)| k == key) { e.1 = val; }
        else { root.push((key.clone(), val)); }
        return;
    }
    ensure_dict_path(root, &path[..path.len()-1]);
    fn nav_set(entries: &mut Vec<(String, Value)>, path: &[String], val: Value) {
        if path.len() == 1 {
            if let Some(e) = entries.iter_mut().find(|(k,_)| k == &path[0]) { e.1 = val; }
            else { entries.push((path[0].clone(), val)); }
            return;
        }
        if let Some(e) = entries.iter_mut().find(|(k,_)| k == &path[0]) {
            if let Value::Dict(inner) = &mut e.1 { nav_set(inner, &path[1..], val); }
        }
    }
    nav_set(root, path, val);
}

fn parse_toml_value(src: &str) -> Value {
    let t = src.trim();
    if t.starts_with('"') || t.starts_with('\'') {
        // basic unescape for double quotes (reuse JSON parsing when possible)
        if t.starts_with('"') {
            if let Ok(serde_json::Value::String(s)) = serde_json::from_str::<serde_json::Value>(t) {
                return Value::Str(s);
            }
        }
        return Value::Str(unquote(t));
    }
    if t == "true" { return Value::Bool(true); }
    if t == "false" { return Value::Bool(false); }
    if t.starts_with('[') && t.ends_with(']') {
        let inner = &t[1..t.len()-1];
        let parts = split_top_commas(inner);
        return Value::Array(parts.into_iter().filter(|p| !p.trim().is_empty()).map(|p| parse_toml_value(p.trim())).collect());
    }
    if t.starts_with('{') && t.ends_with('}') {
        let inner = &t[1..t.len()-1];
        let mut entries = Vec::new();
        for p in split_top_commas(inner) {
            if let Some(eq) = p.find('=') {
                entries.push((unquote(p[..eq].trim()), parse_toml_value(p[eq+1..].trim())));
            }
        }
        return Value::Dict(entries);
    }
    if let Ok(i) = t.replace('_',"").parse::<i64>() { return Value::Int(i); }
    if let Ok(f) = t.replace('_',"").parse::<f64>() { return Value::Float(f); }
    Value::Str(t.to_string())
}

fn split_top_commas(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut cur = String::new();
    let mut depth = 0i32;
    let mut in_str: Option<char> = None;
    for c in s.chars() {
        match in_str {
            Some(q) => { cur.push(c); if c == q { in_str = None; } }
            None => match c {
                '"'|'\'' => { in_str = Some(c); cur.push(c); }
                '['|'{' => { depth += 1; cur.push(c); }
                ']'|'}' => { depth -= 1; cur.push(c); }
                ',' if depth == 0 => { parts.push(cur.clone()); cur.clear(); }
                _ => cur.push(c),
            }
        }
    }
    if !cur.is_empty() || parts.is_empty() { parts.push(cur); }
    parts
}

pub fn parse_csv_str(s: &str, has_header_row: bool) -> Value {
    let rows: Vec<Vec<String>> = s.lines().filter(|l| !l.is_empty()).map(|l| parse_csv_line(l)).collect();
    if has_header_row {
        if rows.is_empty() { return Value::Array(vec![]); }
        let header = rows[0].clone();
        let mut out = Vec::new();
        for r in &rows[1..] {
            let mut entries = Vec::new();
            for (i, h) in header.iter().enumerate() {
                entries.push((h.clone(), Value::Str(r.get(i).cloned().unwrap_or_default())));
            }
            out.push(Value::Dict(entries));
        }
        Value::Array(out)
    } else {
        Value::Array(rows.into_iter().map(|r| Value::Array(r.into_iter().map(Value::Str).collect())).collect())
    }
}

fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut in_q = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if in_q {
            if c == '"' {
                if chars.peek() == Some(&'"') { cur.push('"'); chars.next(); }
                else { in_q = false; }
            } else { cur.push(c); }
        } else {
            if c == '"' && cur.is_empty() { in_q = true; }
            else if c == ',' { fields.push(cur.clone()); cur.clear(); }
            else { cur.push(c); }
        }
    }
    fields.push(cur);
    fields
}

pub fn parse_xml_str(s: &str) -> Value {
    // Typst xml() returns array of element dicts: (tag: ..., attrs: ..., children: ...) — simplify: return single root array similarly if possible.
    // Minimal: find root tag name and return [(tag: root, attrs: (:), children: ())]. Tests rarely use xml deeply.
    let t = s.trim();
    let tag = t.strip_prefix('<').and_then(|r| {
        let name: String = r.chars().take_while(|c| c.is_alphanumeric()||*c=='-'||*c=='_').collect();
        if name.is_empty() { None } else { Some(name) }
    }).unwrap_or_else(|| "root".to_string());
    Value::Array(vec![Value::Dict(vec![
        ("tag".into(), Value::Str(tag)),
        ("attrs".into(), Value::Dict(vec![])),
        ("children".into(), Value::Array(vec![])),
    ])])
}
