pub fn unknown_var_diag(name: &str, e: &SpExpr, source: &str) -> Diag {
    let (line, col) = crate::diag::line_col_of(source, e.start);
    let mut d = Diag::error_at(format!("unknown variable: {}", name), line, col, name.chars().count().max(1));
    if name.contains('-') {
        d.hints.push(format!("if you meant to use subtraction, try adding spaces around the minus sign: `{}`", name.replace('-', " - ")));
    }
    d
}

fn results_push(results: &mut Vec<Value>, v: Value) {
    results.push(v);
}

pub fn join_name(v: &Value) -> &'static str {
    // Reference join errors: "cannot join integer with integer"
    v.type_name()
}

pub fn friendly_type(v: &Value) -> &'static str {
    // Method errors say "type string has no method" (string, not... ) and "type array", "type integer".
    match v {
        Value::Str(_) => "string",
        Value::Int(_) => "integer",
        Value::Float(_) => "float",
        Value::Bool(_) => "boolean",
        _ => v.type_name(),
    }
}

pub fn expect_bool_operand(v: &Value, _op: &str) -> Result<bool, Diag> {
    match v {
        Value::Bool(b) => Ok(*b),
        other => Err(Diag::error(format!("expected boolean, found {}", other.type_name()))),
    }
}

pub fn length_to_pt(l: &LengthVal, font_size: f64) -> f64 {
    l.pt + l.em * font_size
}

pub fn paper_size(name: &str) -> Option<(f64, f64)> {
    // Common papers (pt). a4 default.
    Some(match name.to_ascii_lowercase().as_str() {
        "a4" => (595.275590551, 841.88976378),
        "a5" => (419.527559055, 595.275590551),
        "a3" => (841.88976378, 1190.5511811),
        "us-letter" | "letter" => (612.0, 792.0),
        "us-legal" | "legal" => (612.0, 1008.0),
        _ => return None,
    })
}

pub fn value_to_content_single(v: Value) -> Content {
    match v {
        Value::Content(c) => c,
        Value::Str(s) => Content::text(s),
        Value::None => make_sequence(vec![]),
        other => Content::text(other.display_str()),
    }
}

pub fn make_sequence(children: Vec<Content>) -> Content {
    // Flatten nested sequences.
    let mut flat: Vec<Content> = Vec::new();
    for c in children {
        if c.func == "sequence" && c.label.is_none() {
            if let Some(Value::Array(items)) = c.get("children") {
                for it in items { if let Value::Content(cc) = it { flat.push(cc.clone()); } }
            }
        } else { flat.push(c); }
    }
    match flat.len() {
        0 => { let mut c = Content::new("sequence"); c.fields.push(("children".into(), Value::Array(vec![]))); c }
        1 => flat.into_iter().next().unwrap(),
        _ => {
            let mut c = Content::new("sequence");
            c.fields.push(("children".into(), Value::Array(flat.into_iter().map(Value::Content).collect())));
            c
        }
    }
}

pub fn collapse_contents(contents: Vec<Content>) -> Content {
    // Merge adjacent text nodes when separated only by nothing (e.g. "Hello " + "world" never adjacent due Space nodes; but code-joined text pieces can be adjacent and reference merges them — `[Hello world]` is a single text node already from markup lexer).
    // Evaluation of `[#{"a"}#{"b"}]`? Reference likely merges. Merge adjacent text.
    let mut merged: Vec<Content> = Vec::new();
    for c in contents {
        if c.func == "text" {
            if let Some(last) = merged.last_mut() {
                if last.func == "text" && last.label.is_none() && c.label.is_none() {
                    // append
                    if let (Some(Value::Str(a)), Some(Value::Str(b))) = (last.get("text").cloned(), c.get("text").cloned()) {
                        last.fields = vec![("text".into(), Value::Str(format!("{}{}", a, b)))];
                        continue;
                    }
                }
            }
        }
        merged.push(c);
    }
    // Documentation: for document evaluation we must KEEP parbreaks; make_sequence collapses singletons.
    make_sequence(merged)
}

pub fn push_display_value(v: Value, out: &mut Vec<Content>) {
    match v {
        Value::None => {}
        Value::Content(c) => {
            if c.func == "sequence" && c.label.is_none() {
                if let Some(Value::Array(items)) = c.get("children").cloned() {
                    for it in items { if let Value::Content(cc) = it { out.push(cc); } }
                    return;
                }
            }
            out.push(c);
        }
        Value::Str(s) => out.push(Content::text(s)),
        other => out.push(Content::text(other.display_str())),
    }
}

pub fn collect_into(c: &Content, out: &mut Vec<Content>) {
    out.push(c.clone());
    for (_, v) in &c.fields {
        collect_value_into(v, out);
    }
}

fn collect_value_into(v: &Value, out: &mut Vec<Content>) {
    match v {
        Value::Content(c) => collect_into(c, out),
        Value::Array(items) => for it in items { collect_value_into(it, out); },
        Value::Dict(entries) => for (_, val) in entries { collect_value_into(val, out); },
        _ => {}
    }
}

/// Decorate a content for query serialization: inject default fields for well-known elements (heading).
pub fn decorate_for_query(c: &Content) -> Content {
    let mut c = c.clone();
    if c.func == "heading" {
        // Reference fields order: func, level, depth, offset, numbering, supplement, outlined, bookmarked, hanging-indent, body, [label]
        let body = c.get("body").cloned().unwrap_or(Value::Content(Content::text(String::new())));
        let explicit_level = c.get("level").cloned();
        let depth_val = c.get("depth").cloned().or_else(|| explicit_level.clone()).unwrap_or(Value::Int(1));
        let level_val = explicit_level.clone().or_else(|| c.get("depth").cloned()).unwrap_or(Value::Int(1));
        let mut supplement = Content::text("Section".to_string());
        supplement = supplement; // silence
        c.fields = vec![
            ("level".into(), level_val),
            ("depth".into(), depth_val),
            ("offset".into(), Value::Int(0)),
            ("numbering".into(), Value::None),
            ("supplement".into(), Value::Content(Content::text("Section".to_string()))),
            ("outlined".into(), Value::Bool(true)),
            ("bookmarked".into(), Value::Auto),
            ("hanging-indent".into(), Value::Auto),
            ("body".into(), body),
        ];
    }
    c
}

/// Evaluate a full document (markup) and return (content, engine warnings...). Caller handles diagnostics rendering.
pub fn eval_document(engine: &mut Engine, source_text: &str) -> Result<Value, Diag> {
    let doc = crate::markup::parse_markup(source_text);
    // Check for parse-level errors embedded in hash code nodes first (eval will surface them anyway).
    let env = engine.global_scope();
    let result = engine.eval_markup_doc(&doc, &env, source_text);
    match &result {
        Ok(Value::Content(root)) => {
            let root = root.clone();
            engine.collect_introspection(&root);
            // Validate refs against labels.
            let labels: Vec<String> = engine.introspection.iter().filter_map(|c| c.label.clone()).collect();
            if let Err(d) = validate_refs(&doc, &labels, source_text) { return Err(d); }
        }
        _ => {}
    }
    result
}

fn validate_refs(doc: &MarkupDoc, labels: &[String], source: &str) -> Result<(), Diag> {
    fn walk(nodes: &[Node], labels: &[String], source: &str) -> Result<(), Diag> {
        for n in nodes {
            match n {
                Node::Ref(name, _, s, e) => {
                    if !labels.contains(name) {
                        let (line, col) = crate::diag::line_col_of(source, *s);
                        let len = source[*s..*e].chars().count();
                        return Err(Diag::error_at(format!("label `<{}>` does not exist in the document", name), line, col, len));
                    }
                }
                Node::Strong(b, _) | Node::Emph(b, _) => walk(&b.nodes, labels, source)?,
                Node::Heading(_, b, _, _) => walk(&b.nodes, labels, source)?,
                Node::ListItem(b, _) => walk(&b.nodes, labels, source)?,
                Node::EnumItem(_, b, _) => walk(&b.nodes, labels, source)?,
                Node::TermItem(a, b, _) => { walk(&a.nodes, labels, source)?; walk(&b.nodes, labels, source)?; }
                _ => {}
            }
        }
        Ok(())
    }
    walk(&doc.nodes, labels, source)
}
