        ("orange", "rgb(\"#ff851b\")"),
        ("red", "rgb(\"#ff4136\")"),
        ("maroon", "rgb(\"#85144b\")"),
        ("fuchsia", "rgb(\"#f012be\")"),
        ("purple", "rgb(\"#b10dc9\")"),
    ]
}

pub fn element_functions() -> Vec<&'static str> {
    vec![
        "page","text","par","heading","strong","emph","link","image","table","align","list","enum","terms","grid","stack","columns","figure","outline","bibliography","cite","footnote","place","rotate","scale","move","rect","circle","ellipse","line","polygon","path","raw","underline","strike","highlight","box","block","pad","document","metadata","h","v","pagebreak","linebreak","colbreak","parbreak","title","equation","ref","smallcaps","super","sub","overline","censor","smartquote","quote","caption",
    ]
}

pub fn install_globals(env: &Env, engine: &Engine) {
    let d = |name: &str, v: Value| env_define(env, name, v);
    // Modules
    d("calc", Value::Module("calc".into()));
    d("sys", Value::Module("sys".into()));
    d("math", Value::Module("math".into()));
    d("color", Value::Func("color".into()));
    // Types as callable Func values (eval `int` → returns Func so JSON gives "int")
    // Note: `type(int)` → "type"? Value::Func type_name is "function" but display_type_name(Func) = "function". Typst: type(int) == type. Hmm! `type` builtin special-cases Func values whose name is a type name → returns Type("type"). And `repr(int)` = "int" (Func repr). JSON of `int` alone = "int". So Func works with that special case.
    for t in ["int","float","bool","str","length","angle","ratio","relative","fraction","symbol","version","datetime","duration","bytes","label","regex","array","dictionary","content","type"] {
        d(t, Value::Func(t.into()));
    }
    // Core functions
    for f in ["type","repr","str","panic","assert","eval","range","upper","lower","read","json","yaml","toml","csv","xml","cbor","rgb","cmyk","luma","oklab","oklch","color","counter","state","query","here","locate","metadata","style","measure","layout","int","float"] {
        // (int/float already defined; redefining same value is fine)
        d(f, Value::Func(f.into()));
    }
    // Elements
    for f in element_functions() { d(f, Value::Func(f.into())); }
    // Alignment / constants
    for a in ["left","right","center","start","end","top","bottom","horizon"] {
        d(a, Value::Alignment(a.into()));
    }
    // Colors
    for (name, repr) in named_colors() { d(name, Value::Color(repr.into())); }
    let _ = engine;
}

pub fn module_field(engine: &mut Engine, module: &str, field: &str) -> Result<Value, Diag> {
    match (module, field) {
        ("calc", "pi") => Ok(Value::Float(std::f64::consts::PI)),
        ("calc", "tau") => Ok(Value::Float(std::f64::consts::TAU)),
        ("calc", "e") => Ok(Value::Float(std::f64::consts::E)),
        ("calc", "inf") => Ok(Value::Float(f64::INFINITY)),
        ("sys", "version") => Ok(Value::Version(vec![0,14,2])),
        ("sys", "inputs") => {
            let entries = engine.inputs.iter().map(|(k,v)| (k.clone(), Value::Str(v.clone()))).collect();
            Ok(Value::Dict(entries))
        }
        ("color", "map") => Ok(Value::Module("map".into())),
        ("math", _) => Ok(Value::Func(format!("math.{}", field))),
        ("calc", _) => {
            if crate::builtins::methods::is_calc_func(field) {
                Ok(Value::Func(format!("calc.{}", field)))
            } else {
                Err(Diag::error(format!("module `calc` does not contain `{}`", field)))
            }
        }
        ("sys", _) => Err(Diag::error(format!("module `sys` does not contain `{}`", field))),
        (other, _) => {
            // User-imported module fields.
            if let Some(fields) = Engine::module_fields_get(other) {
                if let Some((_, v)) = fields.iter().find(|(k,_)| k==field) { return Ok(v.clone()); }
            }
            Err(Diag::error(format!("module `{}` does not contain `{}`", other, field)))
        }
    }
}

pub fn func_field(_engine: &mut Engine, func: &str, field: &str) -> Result<Value, Diag> {
    // heading.where / float.inf / datetime.today / str methods-as-fields etc.
    match (func, field) {
        (_, "where") => Ok(Value::Func(format!("{}.where", plain_func_name(func)))),
        ("float", "inf") => Ok(Value::Float(f64::INFINITY)),
        ("float", "nan") => Ok(Value::Float(f64::NAN)),
        ("datetime", "today") => Ok(Value::Func("datetime.today".into())),
        _ => Ok(Value::Func(format!("{}.{}", plain_func_name(func), field))),
    }
}

pub fn plain_func_name(func: &str) -> &str {
    func.strip_prefix("type:").unwrap_or(func)
}

struct Args {
    pos: Vec<Value>,
    named: Vec<(String, Value)>,
}

fn eval_all(engine: &mut Engine, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<Args, Diag> {
    let (mut pos, named) = engine.eval_args(args, env, source)?;
    if let Some(doc) = trailing {
        let v = engine.eval_markup_doc(doc, env, source)?;
        pos.push(v);
    }
    Ok(Args{ pos, named })
}

fn named_get<'a>(named: &'a [(String, Value)], key: &str) -> Option<&'a Value> {
    named.iter().find(|(k,_)| k==key).map(|(_,v)| v)
}

fn color_from_rgb(r: i64, g: i64, b: i64, a: Option<i64>) -> String {
    match a {
        Some(alpha) if alpha != 255 => format!("rgb(\"#{:02x}{:02x}{:02x}{:02x}\")", clamp255(r), clamp255(g), clamp255(b), clamp255(alpha)),
        _ => format!("rgb(\"#{:02x}{:02x}{:02x}\")", clamp255(r), clamp255(g), clamp255(b)),
    }
}
fn clamp255(x: i64) -> i64 { x.clamp(0,255) }

pub fn call_builtin(engine: &mut Engine, name: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str, whole: &SpExpr) -> Result<Value, Diag> {
    let plain = plain_func_name(name).to_string();
    // Qualified names
    if let Some(rest) = plain.strip_prefix("calc.") {
        return crate::builtins::methods::call_calc(engine, rest, args, env, source);
    }
    if let Some(_) = plain.strip_prefix("math.") {
        return math::call_math(engine, &plain, args, trailing, env, source);
    }
    if plain.ends_with(".where") {
        let base = plain.strip_suffix(".where").unwrap().to_string();
        let a = eval_all(engine, args, trailing, env, source)?;
        let mut parts: Vec<String> = Vec::new();
        for (k, v) in &a.named { parts.push(format!("{}: {}", k, v.repr())); }
        for v in &a.pos { parts.push(v.repr()); }
        return Ok(Value::Selector(format!("{}.where({})", base, parts.join(", "))));
    }
    if plain == "datetime.today" {
        let dt = chrono::DateTime::from_timestamp(engine.clock_unix, 0).unwrap_or_else(|| chrono::Utc::now());
        use chrono::Datelike;
        return Ok(Value::DatetimeFields(vec![
            ("year".into(), dt.year() as i64),
            ("month".into(), dt.month() as i64),
            ("day".into(), dt.day() as i64),
        ]));
    }

    match plain.as_str() {
        "type" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let v = a.pos.into_iter().next().ok_or_else(|| Diag::error("missing argument: value".to_string()))?;
            // Special: type names / none / auto
            match &v {
                Value::None => Ok(Value::Type("type(none)".into())),
                Value::Auto => Ok(Value::Type("type(auto)".into())),
                Value::Func(n) if TYPE_NAMES.contains(&n.as_str()) || element_functions().contains(&n.as_str()) => {
                    // type(heading) probed = "function"! Wait: earlier probe `type(heading)` → "function". And type(int)? not probed. Typst: elements are functions; `int` is a type. type(int) → type. Distinguish: TYPE_NAMES → type; elements → function.
                    if TYPE_NAMES.contains(&n.as_str()) {
                        Ok(Value::Type("type".into()))
                    } else {
                        Ok(Value::Type("function".into()))
                    }
                }
                Value::Type(_) => Ok(Value::Type("type".into())),
                other => Ok(Value::Type(display_type_name(other))),
            }
        }
        "repr" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let v = a.pos.into_iter().next().ok_or_else(|| Diag::error("missing argument: value".to_string()))?;
            Ok(Value::Str(v.repr()))
        }
        "str" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            // str(x) formatting with named args (base etc.) — support basics.
            let v = a.pos.into_iter().next().ok_or_else(|| Diag::error("missing argument: value".to_string()))?;
            match &v {
                Value::Int(i) => {
                    if let Some(Value::Int(base)) = named_get(&a.named, "base") {
                        return Ok(Value::Str(format_radix(*i, *base as u32)));
                    }
                    Ok(Value::Str(i.to_string()))
                }
                Value::Float(f) => Ok(Value::Str(crate::value::format_float_display(*f))),
                Value::Str(s) => Ok(Value::Str(s.clone())),
                Value::Label(l) => Ok(Value::Str(l.clone())),
                Value::Version(ver) => Ok(Value::Str(ver.iter().map(|x| x.to_string()).collect::<Vec<_>>().join("."))),
                Value::Bytes(b) => Ok(Value::Str(String::from_utf8_lossy(b).to_string())),
                Value::Type(t) => Ok(Value::Str(t.clone())),
                Value::Func(n) if TYPE_NAMES.contains(&n.as_str()) => Ok(Value::Str(n.clone())),
                Value::Symbol(s) => Ok(Value::Str(s.clone())),
                other => Err(Diag::error(format!("expected integer, float, decimal, version, bytes, label, type, or string, found {}", other.type_name()))),
            }
        }
        "int" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let v = a.pos.into_iter().next().ok_or_else(|| Diag::error("missing argument: value".to_string()))?;
            match &v {
                Value::Int(i) => Ok(Value::Int(*i)),
                Value::Float(f) => Ok(Value::Int(*f as i64)),
                Value::Str(s) => {
                    let base = named_get(&a.named, "base").and_then(|x| if let Value::Int(b)=x { Some(*b as u32) } else { None }).unwrap_or(10);
                    match i64::from_str_radix(s.trim(), base) {
                        Ok(i) => Ok(Value::Int(i)),
                        Err(_) => Err(Diag::error(format!("invalid integer: \"{}\"", s))),
                    }
                }
                Value::Bool(b) => Ok(Value::Int(if *b {1} else {0})),
                other => Err(Diag::error(format!("expected integer, float, boolean, decimal, version, bytes, or string, found {}", other.type_name()))),
            }
        }
        "float" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let v = a.pos.into_iter().next().ok_or_else(|| Diag::error("missing argument: value".to_string()))?;
            match &v {
                Value::Int(i) => Ok(Value::Float(*i as f64)),
                Value::Float(f) => Ok(Value::Float(*f)),
                Value::Str(s) => match s.trim().parse::<f64>() { Ok(f)=>Ok(Value::Float(f)), Err(_)=>Err(Diag::error(format!("invalid float: \"{}\"", s))) },
                other => Err(Diag::error(format!("expected integer, float, decimal, or string, found {}", other.type_name()))),
            }
        }
        "bool" => Err(Diag::error("type boolean does not have a constructor".to_string())),
        "array" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            Ok(Value::Array(a.pos))
        }
        "dictionary" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            Ok(Value::Dict(a.named))
        }
        "panic" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            if a.pos.is_empty() {
                Err(Diag::error("panicked".to_string()))
            } else {
                let parts: Vec<String> = a.pos.iter().map(|v| v.repr()).collect();
                Err(Diag::error(format!("panicked with: {}", parts.join(", "))))
            }
        }
        "assert" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let v = a.pos.into_iter().next().unwrap_or(Value::Bool(false));
            match v {
                Value::Bool(true) => Ok(Value::None),
                Value::Bool(false) => {
                    if let Some(Value::Str(m)) = named_get(&a.named, "message") {
                        Err(Diag::error(m.clone()))
                    } else { Err(Diag::error("assertion failed".to_string())) }
                }
                other => Err(Diag::error(format!("expected boolean, found {}", other.type_name()))),
            }
        }
        "range" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let geti = |v: &Value| -> Result<i64, Diag> { match v { Value::Int(i)=>Ok(*i), other=>Err(Diag::error(format!("expected integer, found {}", other.type_name()))) } };
            let (start, end) = if a.pos.len() == 1 { (0, geti(&a.pos[0])?) } else if a.pos.len() >= 2 { (geti(&a.pos[0])?, geti(&a.pos[1])?) } else { return Err(Diag::error("missing argument: end".to_string())); };
            let step = match named_get(&a.named, "step") { Some(v)=> geti(v)?, None=> 1 };
            if step == 0 { return Err(Diag::error("step must not be zero".to_string())); }
            let mut out = Vec::new();
            let mut x = start;
            if step > 0 { while x < end { out.push(Value::Int(x)); x += step; if out.len() > 1_000_000 { break; } } }
            else { while x > end { out.push(Value::Int(x)); x += step; if out.len() > 1_000_000 { break; } } }
            Ok(Value::Array(out))
        }
        "eval" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let code = match a.pos.into_iter().next() { Some(Value::Str(s))=>s, Some(other)=> return Err(Diag::error(format!("expected string, found {}", other.type_name()))), None=> return Err(Diag::error("missing argument: string".to_string())) };
            // mode: code (default) | markup | math
            let mode = named_get(&a.named, "mode").and_then(|v| if let Value::Str(s)=v { Some(s.clone()) } else { None }).unwrap_or_else(|| "code".to_string());
            match mode.as_str() {
                "markup" => {
                    let doc = crate::markup::parse_markup(&code);
                    engine.eval_markup_doc(&doc, env, &code)
                }
                "math" => {
                    let eq = crate::builtins::math::parse_equation(&code, false, engine, env, &code)?;
                    Ok(Value::Content(eq))
                }
                _ => {
                    let (expr, errs, _p) = crate::code::parse_eval_expression(&code);
                    if let Some(d) = errs.first() { return Err(d.clone()); }
                    engine.eval_expr(&expr, env, &code)
                }
            }
        }
        "upper" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            match a.pos.into_iter().next() {
                Some(Value::Str(s)) => Ok(Value::Str(s.to_uppercase())),
                Some(Value::Content(c)) => Ok(Value::Content(map_text(c, &|t: &str| t.to_uppercase()))),
                _ => Err(Diag::error("expected string or content".to_string())),
            }
        }
        "lower" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            match a.pos.into_iter().next() {
                Some(Value::Str(s)) => Ok(Value::Str(s.to_lowercase())),
                Some(Value::Content(c)) => Ok(Value::Content(map_text(c, &|t: &str| t.to_lowercase()))),
                _ => Err(Diag::error("expected string or content".to_string())),
            }
        }
        "label" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            match a.pos.into_iter().next() {
                Some(Value::Str(s)) => Ok(Value::Label(s)),
                Some(other) => Err(Diag::error(format!("expected string, found {}", other.type_name()))),
                None => Err(Diag::error("missing argument: string".to_string())),
            }
        }
        "regex" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            match a.pos.into_iter().next() {
                Some(Value::Str(s)) => Ok(Value::Regex(s)),
                _ => Err(Diag::error("expected string".to_string())),
            }
        }
        "symbol" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            match a.pos.into_iter().next() {
                Some(Value::Str(s)) => Ok(Value::Symbol(s)),
                _ => Err(Diag::error("expected string".to_string())),
            }
        }
        "version" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut out = Vec::new();
            for v in a.pos { if let Value::Int(i)=v { out.push(i); } }
            Ok(Value::Version(out))
        }
        "bytes" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            match a.pos.into_iter().next() {
                Some(Value::Str(s)) => Ok(Value::Bytes(s.into_bytes())),
                Some(Value::Array(items)) => {
                    let mut b = Vec::new();
                    for it in items { if let Value::Int(i)=it { b.push((i.clamp(0,255)) as u8); } }
                    Ok(Value::Bytes(b))
                }
                Some(Value::Bytes(b)) => Ok(Value::Bytes(b)),
                Some(Value::Int(i)) => Ok(Value::Bytes(vec![i.clamp(0,255) as u8])),
                _ => Ok(Value::Bytes(vec![])),
            }
        }
        "datetime" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut fields: Vec<(String, i64)> = Vec::new();
            for (k, v) in &a.named { if let Value::Int(i)=v { fields.push((k.clone(), *i)); } }
            // Order like reference: year, month, day, hour, minute, second (insertion order from call usually matches).
            Ok(Value::DatetimeFields(fields))
        }
        "duration" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut fields: Vec<(String, f64)> = Vec::new();
            for (k, v) in &a.named {
                match v { Value::Int(i)=> fields.push((k.clone(), *i as f64)), Value::Float(f)=> fields.push((k.clone(), *f)), _=>{} }
            }
            Ok(Value::Duration(fields))
        }
        "rgb" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            if a.pos.len() == 1 {
                if let Value::Str(s) = &a.pos[0] {
                    let hex = s.trim().trim_start_matches('#').to_ascii_lowercase();
                    return Ok(Value::Color(format!("rgb(\"#{}\")", hex)));
                }
            }
            let nums: Vec<i64> = a.pos.iter().filter_map(|v| match v { Value::Int(i)=>Some(*i), Value::Float(f)=>Some(*f as i64), Value::Ratio(r)=>Some((r*255.0).round() as i64), _=>None }).collect();
            if nums.len() >= 3 {
                let alpha = if nums.len() >= 4 { Some(nums[3]) } else { None };
                return Ok(Value::Color(color_from_rgb(nums[0], nums[1], nums[2], alpha)));
            }
            // named r/g/b?
            Err(Diag::error("missing argument: red".to_string()))
        }
        "cmyk" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let parts: Vec<String> = a.pos.iter().map(|v| v.repr()).collect();
            Ok(Value::Color(format!("cmyk({})", parts.join(", "))))
        }
        "luma" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            match a.pos.into_iter().next() {
                Some(Value::Ratio(r)) => Ok(Value::Color(format!("luma({})", crate::value::format_ratio(r)))),
                Some(Value::Int(i)) => Ok(Value::Color(format!("luma({}%)", (i as f64 * 100.0 / 255.0 * 100.0).round()/100.0))),
                Some(other) => Ok(Value::Color(format!("luma({})", other.repr()))),
                None => Err(Diag::error("missing argument: lightness".to_string())),
            }
        }
        "oklab" | "oklch" | "color" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            if plain == "color" {
                // color() with no args? Return black-ish. Not critical.
                return Ok(Value::Color("luma(0%)".into()));
            }
            let parts: Vec<String> = a.pos.iter().map(|v| v.repr()).collect();
            Ok(Value::Color(format!("{}({})", plain, parts.join(", "))))
        }
        "counter" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let key = match a.pos.into_iter().next() {
                Some(Value::Func(n)) => n,
                Some(Value::Label(l)) => format!("<{}>", l),
                Some(Value::Str(s)) => s,
                Some(other) => other.repr(),
                None => "page".to_string(),
            };
            Ok(Value::Counter(key))
        }
        "state" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            // Represent state as counter-like string repr `state("key", init)`? Rare in eval tests; return Content-less placeholder via Counter variant with prefix.
            let key = a.pos.get(0).map(|v| v.display_str()).unwrap_or_default();
            Ok(Value::Counter(format!("state:{}", key)))
        }
        "query" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let sel = a.pos.into_iter().next().ok_or_else(|| Diag::error("missing argument: selector".to_string()))?;
            let results = query_elements(engine, &sel)?;
            Ok(Value::Array(results))
        }
        "here" => {
            let mut d = Diag::error("can only be used when context is known".to_string());
            d.hints.push("try wrapping this in a `context` expression".to_string());
            d.hints.push("the `context` expression should wrap everything that depends on this function".to_string());
            Err(d)
        }
        "locate" => Ok(Value::None),
        "read" | "json" | "yaml" | "toml" | "csv" | "xml" | "cbor" => {
            crate::builtins::methods::call_data_func(engine, &plain, args, env, source)
        }
        "image" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new("image");
            if let Some(v) = a.pos.into_iter().next() { c.fields.push(("source".into(), v)); }
            Ok(Value::Content(c))
        }
        "metadata" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new("metadata");
            if let Some(v) = a.pos.into_iter().next() { c.fields.push(("value".into(), v)); }
            Ok(Value::Content(c))
        }
        _ => {
            // Element functions and generic content constructors.
            if element_functions().contains(&plain.as_str()) || is_known_content_func(&plain) {
                return make_element(engine, &plain, args, trailing, env, source);
            }
            // Unknown Func name (e.g. from func_field fallback like "foo.bar") → treat as element? Reference would have errored earlier at field access. Return generic element to be safe.
            let _ = whole;
            make_element(engine, &plain, args, trailing, env, source)
        }
    }
}

pub fn is_known_content_func(name: &str) -> bool {
    matches!(name, "strong"|"emph"|"heading"|"par"|"text"|"list"|"enum"|"terms"|"table"|"grid"|"stack"|"columns"|"align"|"link"|"raw"|"box"|"block"|"rect"|"circle"|"ellipse"|"line"|"polygon"|"path"|"figure"|"outline"|"quote"|"title")
}

fn make_element(engine: &mut Engine, name: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<Value, Diag> {
    // Special forms that return styled/empty etc.
    match name {
        "pagebreak" | "linebreak" | "colbreak" | "parbreak" => {
            // Evaluate args (weak: etc.) for errors but serialization is just {func}.
            let _ = eval_all(engine, args, trailing, env, source)?;
            return Ok(Value::Content(Content::new(name)));
        }
        "h" | "v" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new(name);
            if let Some(v) = a.pos.into_iter().next() { c.fields.push(("amount".into(), v)); }
            return Ok(Value::Content(c));
        }
        "raw" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new("raw");
            // raw("code") → {func:raw, text:"code"} (no block field!). raw(block:true)[..]? Handle named.
            let mut text_val: Option<Value> = None;
            for v in a.pos {
                match v {
                    Value::Str(s) => { text_val = Some(Value::Str(s)); }
                    Value::Content(cc) => { text_val = Some(Value::Str(cc.plain_text())); }
                    other => { text_val = Some(other); }
                }
            }
            if let Some(t) = text_val { c.fields.push(("text".into(), t)); }
            for (k, v) in &a.named { c.fields.push((k.clone(), v.clone())); }
            return Ok(Value::Content(c));
        }
        "link" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new("link");
            let mut pos = a.pos.into_iter();
            let dest = pos.next().unwrap_or(Value::Str(String::new()));
            c.fields.push(("dest".into(), dest.clone()));
            let body = match pos.next() {
                Some(v) => value_to_content_single(v),
                None => match &dest { Value::Str(s)=> Content::text(s.clone()), Value::Label(l)=> Content::text(l.clone()), other=> Content::text(other.display_str()) },
            };
            c.fields.push(("body".into(), Value::Content(body)));
            return Ok(Value::Content(c));
        }
        "align" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new("align");
            let mut pos = a.pos.into_iter();
            if let Some(v) = pos.next() { c.fields.push(("alignment".into(), v)); }
            if let Some(v) = pos.next() { c.fields.push(("body".into(), Value::Content(value_to_content_single(v)))); }
            return Ok(Value::Content(c));
        }
        "table" | "grid" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new(name);
            for (k, v) in &a.named { c.fields.push((k.clone(), v.clone())); }
            let mut cells = Vec::new();
            for v in a.pos {
                // Wrap each cell value as cell element unless already cell.
                let cell_body = value_to_content_single(v);
                if cell_body.func == "cell" { cells.push(Value::Content(cell_body)); }
                else {
                    let mut cell = Content::new("cell");
                    cell.fields.push(("body".into(), Value::Content(cell_body)));
                    cells.push(Value::Content(cell));
                }
            }
            if !cells.is_empty() || trailing.is_none() {
                c.fields.push(("children".into(), Value::Array(cells)));
            }
            return Ok(Value::Content(c));
        }
        "list" | "enum" | "terms" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new(name);
            for (k, v) in &a.named {
                // list(tight:...) etc. not serialized unless set non-default; include as-is (reference omits defaults; including explicit is correct).
                c.fields.push((k.clone(), v.clone()));
            }
            let mut items = Vec::new();
            for v in a.pos {
                let body = value_to_content_single(v);
                if body.func == "item" || body.func == "term" { items.push(Value::Content(body)); }
                else if body.func == "sequence" {
                    // list[Hi] trailing content evaluates to text; single item.
                    let mut item = Content::new("item");
                    item.fields.push(("body".into(), Value::Content(body)));
                    items.push(Value::Content(item));
                } else {
                    let mut item = Content::new("item");
                    item.fields.push(("body".into(), Value::Content(body)));
                    items.push(Value::Content(item));
                }
            }
            c.fields.push(("children".into(), Value::Array(items)));
            return Ok(Value::Content(c));
        }
        "text" => {
            // text[Hi] → {func:text, text:"Hi"} when the trailing content is plain text and no style args.
            // text(red)[Hi] → {func:styled, child:{text}, styles:"styles(..)"}
            // text("Hello")? → text element with text field.
            // Determine if there are styling args (any positional before trailing, or named). Our eval_all appends trailing as last pos. So: styling = named non-empty OR pos.len() > 1 OR (pos.len()==1 && trailing.is_none() && arg is not string/content?) Hmm text(red) without body is a set-like? In eval, `text(red)[hi]` gave styled. `text[Hi]` gave text.
            let raw_has_named = args.iter().any(|a| matches!(a, ParenItem::Named(_, _)));
            let raw_pos_count = args.iter().filter(|a| matches!(a, ParenItem::Pos(_)|ParenItem::Spread(_))).count();
            let a = eval_all(engine, args, trailing, env, source)?;
            let has_style = raw_has_named || raw_pos_count > 0;
            // If has_style, body is the trailing content (last pos if trailing present).
            if has_style && trailing.is_some() {
                let body_val = a.pos.last().cloned().unwrap_or(Value::Content(Content::text(String::new())));
                let child = value_to_content_single(body_val);
                let mut c = Content::new("styled");
                c.fields.push(("child".into(), Value::Content(child)));
                c.fields.push(("styles".into(), Value::Str("styles(..)".into())));
                return Ok(Value::Content(c));
            }
            if has_style && trailing.is_none() {
                // e.g. text("Hello") — body is first positional string? Typst text() requires body as content argument usually via [..]; text("x")? Treat positional string as text content.
                if a.pos.len() == 1 {
                    if let Value::Str(s) = &a.pos[0] {
                        return Ok(Value::Content(Content::text(s.clone())));
                    }
                }
                // Set-rule-like constructor without body (used in set/show) — return empty text element.
                let mut c = Content::new("text");
                c.fields.push(("text".into(), Value::Str(String::new())));
                return Ok(Value::Content(c));
            }
            // No style: trailing content is the text.
            let body_val = a.pos.into_iter().next().unwrap_or(Value::Content(Content::text(String::new())));
            let body = value_to_content_single(body_val);
            if body.func == "text" { return Ok(Value::Content(body)); }
            // Wrap: text element's plain serialization expects text string; if body is sequence, reference? Return body as-is wrapped in styled? Choose: return Content{text, text: plain}.
            return Ok(Value::Content(Content::text(body.plain_text())));
        }
        "heading" => {
            let a = eval_all(engine, args, trailing, env, source)?;
            let mut c = Content::new("heading");
            for (k, v) in &a.named { c.fields.push((k.clone(), v.clone())); }
            if let Some(v) = a.pos.into_iter().last() {
                c.fields.push(("body".into(), Value::Content(value_to_content_single(v))));
            }
            return Ok(Value::Content(c));
        }
        _ => {}
    }
    // Generic element: named fields + body (trailing / last positional content) or children.
    let a = eval_all(engine, args, trailing, env, source)?;
    let mut c = Content::new(name);
    for (k, v) in &a.named {
        c.fields.push((k.clone(), v.clone()));
    }
    if !a.pos.is_empty() {
        // If exactly one content positional → body. If multiple → children (for stack etc.) or positional fields p0..? Reference for e.g. `rect[Hi]` → body. `stack([A],[B])`? Unknown; use children.
        if a.pos.len() == 1 {
            let v = a.pos.into_iter().next().unwrap();
            match v {
                Value::Content(cc) => { c.fields.push(("body".into(), Value::Content(cc))); }
                other => { c.fields.push(("body".into(), Value::Content(value_to_content_single(other)))); }
            }
        } else {
            let children: Vec<Value> = a.pos.into_iter().map(|v| Value::Content(value_to_content_single(v))).collect();
            c.fields.push(("children".into(), Value::Array(children)));
        }
    }
    Ok(Value::Content(c))
}

pub fn map_text(c: Content, f: &dyn Fn(&str) -> String) -> Content {
    let mut c = c;
    if c.func == "text" {
        if let Some(Value::Str(t)) = c.get("text").cloned() {
            c.fields = vec![("text".into(), Value::Str(f(&t)))];
        }
        return c;
    }
    c.fields = c.fields.into_iter().map(|(k, v)| {
        let nv = match v {
            Value::Content(inner) => Value::Content(map_text(inner, f)),
            Value::Array(items) => Value::Array(items.into_iter().map(|it| match it { Value::Content(inner)=> Value::Content(map_text(inner, f)), other=> other }).collect()),
            other => other,
        };
        (k, nv)
    }).collect();
    c
}

pub fn format_radix(mut n: i64, radix: u32) -> String {
    if radix < 2 || radix > 36 { return n.to_string(); }
    if n == 0 { return "0".into(); }
    let neg = n < 0;
    if neg { n = -n; }
    let mut digits = Vec::new();
    let mut x = n as u64;
    while x > 0 {
        let d = (x % radix as u64) as u32;
        digits.push(char::from_digit(d, radix).unwrap_or('0'));
        x /= radix as u64;
    }
    let mut s: String = digits.into_iter().rev().collect();
    if neg { s.insert(0, '-'); }
    s
}

pub fn query_elements(engine: &Engine, selector: &Value) -> Result<Vec<Value>, Diag> {
    // selector: Label | Func(element name) | Selector("name.where(...)")
    let mut out = Vec::new();
    for c in &engine.introspection {
        let matches = match selector {
            Value::Label(l) => c.label.as_deref() == Some(l.as_str()),
            Value::Func(name) => &c.func == name,
            Value::Selector(s) => selector_matches(c, s),
            Value::Str(s) => &c.func == s,
            _ => false,
        };
        if matches {
            out.push(Value::Content(crate::eval::decorate_for_query(c)));
        }
    }
    Ok(out)
}

pub fn selector_matches(c: &Content, selector: &str) -> bool {
    // Forms: "heading" | "<label>" | "heading.where(level: 1)"
    if let Some(inner) = selector.strip_prefix('<').and_then(|s| s.strip_suffix('>')) {
        return c.label.as_deref() == Some(inner);
    }
    if let Some(dot) = selector.find(".where(") {
        let base = &selector[..dot];
        if c.func != base { return false; }
        let inside = &selector[dot + ".where(".len()..selector.len().saturating_sub(1)];
        // parse k: v pairs (simple)
        for part in inside.split(',') {
            let part = part.trim();
            if part.is_empty() { continue; }
            if let Some((k, v)) = part.split_once(':') {
                let k = k.trim(); let v = v.trim();
                // Compare against decorated fields.
                let decorated = crate::eval::decorate_for_query(c);
                match decorated.get(k) {
                    Some(fv) => { if fv.repr() != v && fv.display_str() != v { return false; } }
                    None => {
                        // Special: heading level vs depth equivalence handled by decoration (both present).
                        return false;
                    }
                }
            }
        }
        return true;
    }
    c.func == selector
}

/// Serialize a Typst value with `eval`/`query` formatting.
pub fn serialize_value(v: &Value, format: &str, pretty: bool) -> String {
    let j = crate::value::to_json(v);
    // Float formatting: serde_json prints 1.0 as "1.0" (good), inf as null (handled in to_json).
    match format {
        "yaml" => {
            // serde_yaml on the JSON value. Note: reference YAML ends without "..."? serde_yaml adds trailing newline; observed yaml output has no explicit document markers. Strip leading "---\n" if present.
            let mut s = serde_yaml::to_string(&j).unwrap_or_default();
            if s.starts_with("---\n") { s = s[4..].to_string(); }
            s
        }
        _ => {
            if pretty {
                let mut s = serde_json::to_string_pretty(&j).unwrap_or_default();
                s.push('\n');
                s
            } else {
                let mut s = serde_json::to_string(&j).unwrap_or_default();
                s.push('\n');
                s
            }
        }
    }
}

// Helpers reused by ops/methods
pub fn to_f64(v: &Value) -> Option<f64> {
    match v { Value::Int(i)=>Some(*i as f64), Value::Float(f)=>Some(*f), _=>None }
}
pub fn is_number(v: &Value) -> bool { matches!(v, Value::Int(_) | Value::Float(_)) }
pub fn length_of(v: &Value) -> Option<LengthVal> {
    match v { Value::Length(l)=>Some(l.clone()), _=>None }
}
pub fn relative_of(v: &Value) -> Option<RelativeVal> {
    match v {
        Value::Ratio(r)=>Some(RelativeVal{ ratio: *r, length: LengthVal::default() }),
        Value::Length(l)=>Some(RelativeVal{ ratio: 0.0, length: l.clone() }),
        Value::Relative(r)=>Some(r.clone()),
        _=>None,
    }
}
pub fn simplify_relative(r: RelativeVal) -> Value {
    if r.length.pt == 0.0 && r.length.em == 0.0 { Value::Ratio(r.ratio) }
    else if r.ratio == 0.0 { Value::Length(r.length) }
    else { Value::Relative(r) }
}
