fn is_num(v: &Value) -> bool { matches!(v, Value::Int(_) | Value::Float(_)) }
fn to_f(v: &Value) -> f64 { match v { Value::Int(i)=>*i as f64, Value::Float(f)=>*f, _=>0.0 } }

fn compare(op: &str, a: &Value, b: &Value) -> Result<Value, Diag> {
    let ord = partial_cmp_values(a, b);
    match ord {
        Some(std::cmp::Ordering::Less) => Ok(Value::Bool(matches!(op, "<"|"<="))),
        Some(std::cmp::Ordering::Equal) => Ok(Value::Bool(matches!(op, "<="|">="))),
        Some(std::cmp::Ordering::Greater) => Ok(Value::Bool(matches!(op, ">"|">="))),
        None => Err(Diag::error(format!("cannot compare {} and {}", a.type_name(), b.type_name()))),
    }
}

pub fn partial_cmp_values(a: &Value, b: &Value) -> Option<std::cmp::Ordering> {
    use std::cmp::Ordering;
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => Some(x.cmp(y)),
        _ if is_num(a) && is_num(b) => to_f(a).partial_cmp(&to_f(b)),
        (Value::Str(x), Value::Str(y)) => Some(x.cmp(y)),
        (Value::Length(x), Value::Length(y)) => {
            if x.em == 0.0 && y.em == 0.0 { x.pt.partial_cmp(&y.pt) }
            else if x.pt == 0.0 && y.pt == 0.0 { x.em.partial_cmp(&y.em) }
            else { None }
        }
        (Value::Ratio(x), Value::Ratio(y)) => x.partial_cmp(y),
        (Value::Angle(x), Value::Angle(y)) => x.partial_cmp(y),
        (Value::Bool(x), Value::Bool(y)) => Some(x.cmp(y)),
        (Value::Version(x), Value::Version(y)) => Some(x.cmp(y)),
        _ => {
            // Ordering fallback: if equal → Equal else None (so < on equal non-comparable still errors correctly.)
            None
        }
    }
}

fn apply_in(a: &Value, b: &Value) -> Result<Value, Diag> {
    match b {
        Value::Array(items) => Ok(Value::Bool(items.iter().any(|x| crate::value::value_eq(x, a)))),
        Value::Dict(entries) => {
            match a {
                Value::Str(k) => Ok(Value::Bool(entries.iter().any(|(ek, _)| ek == k))),
                other => Err(Diag::error(format!("cannot apply 'in' to {} and {}", other.type_name(), b.type_name()))),
            }
        }
        Value::Str(s) => {
            match a {
                Value::Str(sub) => Ok(Value::Bool(s.contains(sub.as_str()))),
                other => Err(Diag::error(format!("cannot apply 'in' to {} and {}", other.type_name(), b.type_name()))),
            }
        }
        _ => Err(Diag::error(format!("cannot apply 'in' to {} and {}", a.type_name(), b.type_name()))),
    }
}
