    let mut any = false;
    while *i < chars.len() && (chars[*i] == '^' || chars[*i] == '_') {
        let is_top = chars[*i] == '^';
        *i += 1;
        // skip spaces
        while *i < chars.len() && chars[*i].is_whitespace() { *i += 1; }
        let arg = parse_math_atom(chars, i);
        if is_top { top = Some(arg); } else { bottom = Some(arg); }
        any = true;
        while *i < chars.len() && chars[*i].is_whitespace() { *i += 1; }
    }
    if any {
        if let Some(base) = items.pop() {
            let mut c = Content::new("attach");
            c.fields.push(("base".into(), Value::Content(base)));
            // Reference key for superscript is "t" (probed). Subscript presumably "b".
            if let Some(b) = bottom { c.fields.push(("b".into(), Value::Content(b))); }
            if let Some(t) = top { c.fields.push(("t".into(), Value::Content(t))); }
            items.push(c);
        }
    }
    items
}

fn parse_math_atom(chars: &[char], i: &mut usize) -> Content {
    while *i < chars.len() && chars[*i].is_whitespace() { *i += 1; }
    if *i >= chars.len() { return Content::text(String::new()); }
    let c = chars[*i];
    if c == '(' {
        let (inner, next) = extract_parens(chars, *i);
        *i = next;
        return parse_math_body(&inner);
    }
    if c.is_ascii_digit() {
        let mut num = String::new();
        while *i < chars.len() && (chars[*i].is_ascii_digit() || chars[*i] == '.') { num.push(chars[*i]); *i += 1; }
        return Content::text(num);
    }
    if c.is_alphabetic() {
        let mut name = String::new();
        while *i < chars.len() && (chars[*i].is_alphanumeric() || chars[*i] == '.') { name.push(chars[*i]); *i += 1; }
        if name.chars().count() == 1 { return symbol_content(&name); }
        // In subscript position like F_n, n is a single letter (handled). Multi → symbol.
        return symbol_content(&name);
    }
    *i += 1;
    Content::text(c.to_string())
}

fn extract_parens(chars: &[char], start: usize) -> (String, usize) {
    debug_assert!(chars[start] == '(');
    let mut depth = 0i32;
    let mut out = String::new();
    let mut i = start;
    while i < chars.len() {
        let c = chars[i];
        if c == '(' {
            depth += 1;
            if depth > 1 { out.push(c); }
        } else if c == ')' {
            depth -= 1;
            if depth == 0 { return (out, i + 1); }
            out.push(c);
        } else { out.push(c); }
        i += 1;
    }
    (out, i)
}

fn split_top(s: &str, delim: char) -> Vec<String> {
    let mut parts = Vec::new();
    let mut cur = String::new();
    let mut depth = 0i32;
    for c in s.chars() {
        match c { '('|'['|'{' => depth += 1, ')'|']'|'}' => depth -= 1, _=>{} }
        if c == delim && depth == 0 { parts.push(cur.clone()); cur.clear(); } else { cur.push(c); }
    }
    parts.push(cur);
    parts
}

fn collapse_math(items: Vec<Content>) -> Content {
    // Merge adjacent text items.
    let mut merged: Vec<Content> = Vec::new();
    for it in items {
        if it.func == "text" {
            if let Some(last) = merged.last_mut() {
                if last.func == "text" {
                    if let (Some(Value::Str(a)), Some(Value::Str(b))) = (last.get("text").cloned(), it.get("text").cloned()) {
                        last.fields = vec![("text".into(), Value::Str(format!("{}{}", a, b)))];
                        continue;
                    }
                }
            }
        }
        if it.func == "sequence" {
            if let Some(Value::Array(children)) = it.get("children").cloned() {
                for ch in children { if let Value::Content(cc) = ch { merged.push(cc); } }
                continue;
            }
        }
        merged.push(it);
    }
    crate::eval::make_sequence(merged)
}

pub fn call_math(engine: &mut Engine, name: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<Value, Diag> {
    // math.sqrt(x), math.frac(a,b), math.equation[..] etc. Produce content elements.
    let short = name.strip_prefix("math.").unwrap_or(name);
    let (mut pos, named) = engine.eval_args(args, env, source)?;
    if let Some(doc) = trailing { pos.push(engine.eval_markup_doc(doc, env, source)?); }
    let mut c = Content::new(short);
    for (k, v) in &named { c.fields.push((k.clone(), v.clone())); }
    if pos.len() == 1 { c.fields.push(("body".into(), pos.into_iter().next().unwrap())); }
    else if !pos.is_empty() { c.fields.push(("children".into(), Value::Array(pos))); }
    Ok(Value::Content(c))
}
