use crate::ast::*;
use crate::builtins::relative_of;
use crate::diag::Diag;
use crate::eval::{Engine, Env, length_to_pt, value_to_content_single};
use crate::markup::MarkupDoc;
use crate::value::{Content, Value};

pub fn is_calc_func(name: &str) -> bool {
    matches!(name,
        "abs"|"pow"|"exp"|"sqrt"|"cbrt"|"log"|"ln"|"sin"|"cos"|"tan"|"asin"|"acos"|"atan"|"atan2"|"sinh"|"cosh"|"tanh"|"min"|"max"|"clamp"|"floor"|"ceil"|"round"|"trunc"|"fract"|"div-euclid"|"rem"|"rem-euclid"|"gcd"|"lcm"|"fact"|"permute"|"binom"|"norm"|"even"|"odd"
    )
}

fn to_f(v: &Value) -> Result<f64, Diag> {
    match v { Value::Int(i)=>Ok(*i as f64), Value::Float(f)=>Ok(*f), Value::Angle(a)=>Ok(*a * std::f64::consts::PI / 180.0), other=>Err(Diag::error(format!("expected number, found {}", other.type_name()))) }
}
fn to_f_angle_raw(v: &Value) -> Result<f64, Diag> { to_f(v) }

pub fn call_calc(engine: &mut Engine, name: &str, args: &[ParenItem], env: &Env, source: &str) -> Result<Value, Diag> {
    if !is_calc_func(name) {
        return Err(Diag::error(format!("module `calc` does not contain `{}`", name)));
    }
    let (pos, named) = engine.eval_args(args, env, source)?;
    let need = |idx: usize, label: &str| -> Result<Value, Diag> { pos.get(idx).cloned().ok_or_else(|| Diag::error(format!("missing argument: {}", label))) };
    let num_result = |originals: &[Value], r: f64| -> Value {
        // Int-preservation: calc.floor returns int for float input (probed: floor(1.9)=1 int, ceil similar, round returns float 2.0, sqrt float, abs preserves).
        let _ = originals;
        Value::Float(r)
    };
    match name {
        "abs" => {
            let v = need(0, "value")?;
            match v {
                Value::Int(i) => Ok(Value::Int(i.abs())),
                Value::Float(f) => Ok(Value::Float(f.abs())),
                Value::Length(l) => Ok(Value::Length(crate::value::LengthVal{ pt: l.pt.abs(), em: l.em.abs() })),
                Value::Angle(a) => Ok(Value::Angle(a.abs())),
                other => Err(Diag::error(format!("expected integer, float, length, angle, ratio, or fraction, found {}", other.type_name()))),
            }
        }
        "min" | "max" => {
            if pos.is_empty() { return Err(Diag::error("missing argument: value".into())); }
            let mut best = pos[0].clone();
            for v in &pos[1..] {
                let ord = crate::builtins::ops::partial_cmp_values(v, &best);
                match ord {
                    Some(std::cmp::Ordering::Less) if name=="min" => best = v.clone(),
                    Some(std::cmp::Ordering::Greater) if name=="max" => best = v.clone(),
                    Some(_) => {}
                    None => return Err(Diag::error(format!("cannot compare {} and {}", v.type_name(), best.type_name()))),
                }
            }
            Ok(best)
        }
        "clamp" => {
            let v = need(0,"value")?; let lo = need(1,"min")?; let hi = need(2,"max")?;
            // numeric clamp preserving int when all int
            if matches!((&v,&lo,&hi),(Value::Int(_),Value::Int(_),Value::Int(_))) {
                if let (Value::Int(x),Value::Int(a),Value::Int(b)) = (v,lo,hi) { return Ok(Value::Int(x.clamp(a.min(b), a.max(b)))); }
            }
            let x=to_f(&v)?; let a=to_f(&lo)?; let b=to_f(&hi)?;
            Ok(Value::Float(x.clamp(a.min(b), a.max(b))))
        }
        "floor" => { let v=need(0,"value")?; Ok(Value::Int(to_f(&v)?.floor() as i64)) }
        "ceil" => { let v=need(0,"value")?; Ok(Value::Int(to_f(&v)?.ceil() as i64)) }
        "trunc" => { let v=need(0,"value")?; match v { Value::Int(i)=>Ok(Value::Int(i)), other=> Ok(Value::Float(to_f(&other)?.trunc())) } }
        "fract" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.fract())) }
        "round" => {
            let v=need(0,"value")?;
            let digits = named.iter().find(|(k,_)| k=="digits").map(|(_,x)| x).and_then(|x| if let Value::Int(i)=x { Some(*i as i32) } else { None }).unwrap_or(0);
            let f = match &v { Value::Int(i)=> *i as f64, Value::Float(x)=> *x, other=> return Err(Diag::error(format!("expected float, found {}", other.type_name()))) };
            let m = 10f64.powi(digits);
            Ok(Value::Float((f*m).round()/m))
        }
        "sqrt" => { let v=need(0,"value")?; Ok(num_result(&pos, to_f(&v)?.sqrt())) }
        "cbrt" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.cbrt())) }
        "pow" => {
            let b=need(0,"base")?; let e=need(1,"exponent")?;
            if let (Value::Int(x), Value::Int(y)) = (&b, &e) {
                if *y >= 0 {
                    if let Some(r) = x.checked_pow(*y as u32) { return Ok(Value::Int(r)); }
                }
            }
            Ok(Value::Float(to_f(&b)?.powf(to_f(&e)?)))
        }
        "exp" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.exp())) }
        "log" => {
            let v=need(0,"value")?;
            let base = named.iter().find(|(k,_)| k=="base").map(|(_,x)| x).or(pos.get(1));
            match base { Some(bv)=> Ok(Value::Float(to_f(&v)?.log(to_f(bv)?))), None=> Ok(Value::Float(to_f(&v)?.log10())) }
        }
        "ln" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.ln())) }
        "sin" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.sin())) }
        "cos" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.cos())) }
        "tan" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.tan())) }
        "asin" => { let v=need(0,"value")?; Ok(Value::Angle(to_f(&v)?.asin() * 180.0/std::f64::consts::PI)) }
        "acos" => { let v=need(0,"value")?; Ok(Value::Angle(to_f(&v)?.acos() * 180.0/std::f64::consts::PI)) }
        "atan" => { let v=need(0,"value")?; Ok(Value::Angle(to_f(&v)?.atan() * 180.0/std::f64::consts::PI)) }
        "atan2" => { let y=need(0,"y")?; let x=need(1,"x")?; Ok(Value::Angle(to_f(&y)?.atan2(to_f(&x)?) * 180.0/std::f64::consts::PI)) }
        "sinh" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.sinh())) }
        "cosh" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.cosh())) }
        "tanh" => { let v=need(0,"value")?; Ok(Value::Float(to_f(&v)?.tanh())) }
        "rem" => {
            let a=need(0,"dividend")?; let b=need(1,"divisor")?;
            match (&a,&b) {
                (Value::Int(x),Value::Int(y)) => { if *y==0 { Err(Diag::error("cannot divide by zero".into())) } else { Ok(Value::Int(x % y)) } }
                _ => { let y=to_f(&b)?; if y==0.0 { Err(Diag::error("cannot divide by zero".into())) } else { Ok(Value::Float(to_f(&a)? % y)) } }
            }
        }
        "div-euclid" => {
            let a=need(0,"dividend")?; let b=need(1,"divisor")?;
            match (&a,&b) {
                (Value::Int(x),Value::Int(y)) => { if *y==0 { Err(Diag::error("cannot divide by zero".into())) } else { Ok(Value::Int(x.div_euclid(*y))) } }
                _ => Ok(Value::Float(to_f(&a)?.div_euclid(to_f(&b)?))),
            }
        }
        "rem-euclid" => {
            let a=need(0,"dividend")?; let b=need(1,"divisor")?;
            match (&a,&b) {
                (Value::Int(x),Value::Int(y)) => { if *y==0 { Err(Diag::error("cannot divide by zero".into())) } else { Ok(Value::Int(x.rem_euclid(*y))) } }
                _ => Ok(Value::Float(to_f(&a)?.rem_euclid(to_f(&b)?))),
            }
        }
        "gcd" => {
            let mut vals: Vec<i64> = Vec::new();
            for v in &pos { match v { Value::Int(i)=>vals.push(i.abs()), other=>return Err(Diag::error(format!("expected integer, found {}", other.type_name()))) } }
            if vals.is_empty() { return Err(Diag::error("missing argument: value".into())); }
            let mut g = vals[0];
            for v in &vals[1..] { g = gcd(g, *v); }
            Ok(Value::Int(g))
        }
        "lcm" => {
            let mut vals: Vec<i64> = Vec::new();
            for v in &pos { match v { Value::Int(i)=>vals.push(i.abs()), other=>return Err(Diag::error(format!("expected integer, found {}", other.type_name()))) } }
            if vals.is_empty() { return Err(Diag::error("missing argument: value".into())); }
            let mut l = vals[0];
            for v in &vals[1..] { let g = gcd(l, *v); if g!=0 { l = l / g * v; } }
            Ok(Value::Int(l))
        }
        "fact" => { let v=need(0,"number")?; match v { Value::Int(mut i)=> { let mut r: i64=1; while i>1 { r=r.checked_mul(i).unwrap_or(i64::MAX); i-=1; } Ok(Value::Int(r)) } other=>Err(Diag::error(format!("expected integer, found {}", other.type_name()))) } }
        "even" => { let v=need(0,"value")?; match v { Value::Int(i)=>Ok(Value::Bool(i%2==0)), other=>Err(Diag::error(format!("expected integer, found {}", other.type_name()))) } }
        "odd" => { let v=need(0,"value")?; match v { Value::Int(i)=>Ok(Value::Bool(i%2!=0)), other=>Err(Diag::error(format!("expected integer, found {}", other.type_name()))) } }
        "norm" => {
            // Euclidean norm of args.
            let mut s = 0.0f64;
            for v in &pos { let f=to_f(v)?; s += f*f; }
            Ok(Value::Float(s.sqrt()))
        }
        "permute" | "binom" => {
            let n=need(0,"n")?; let k=need(1,"k")?;
            match (n,k) {
                (Value::Int(n),Value::Int(k)) => {
                    if name=="permute" {
                        let mut r: i64=1; let mut i=0; while i<k { r=r.checked_mul(n-i).unwrap_or(i64::MAX); i+=1; } Ok(Value::Int(r))
                    } else {
                        Ok(Value::Int(binom(n,k)))
                    }
                }
                _ => Err(Diag::error("expected integer".into())),
            }
        }
        _ => Err(Diag::error(format!("module `calc` does not contain `{}`", name))),
    }
}

fn gcd(mut a: i64, mut b: i64) -> i64 { while b != 0 { let t = b; b = a % b; a = t; } a.abs() }
fn binom(n: i64, k: i64) -> i64 {
    if k < 0 || k > n { return 0; }
    let k = k.min(n-k);
    let mut r: i64 = 1;
    for i in 0..k { r = r.checked_mul(n-i).unwrap_or(i64::MAX) / (i+1); }
    r
}

// ---------------- Data functions ----------------
pub fn call_data_func(engine: &mut Engine, name: &str, args: &[ParenItem], env: &Env, source: &str) -> Result<Value, Diag> {
    if engine.fs_forbidden {
        return Err(Diag::error("cannot access file system from here".to_string()));
    }
    let (pos, named) = engine.eval_args(args, env, source)?;
    let path_val = pos.into_iter().next().ok_or_else(|| Diag::error("missing argument: path".to_string()))?;
    let typst_path = match &path_val {
        Value::Str(s) => s.clone(),
        other => return Err(Diag::error(format!("expected string, found {}", other.type_name()))),
    };
    let resolved = engine.project.resolve(engine.main_file.as_deref(), &typst_path);
    engine.dependencies.push(resolved.clone());
    let bytes = std::fs::read(&resolved).map_err(|_| Diag::error(format!("file not found (searched at {})", resolved.to_string_lossy())))?;
    match name {
        "read" => {
            let encoding = named.iter().find(|(k,_)| k=="encoding").map(|(_,v)| v);
            match encoding {
                Some(Value::None) => Ok(Value::Bytes(bytes)),
                _ => {
                    let text = String::from_utf8(bytes).map_err(|_| Diag::error("file is not valid UTF-8".to_string()))?;
                    Ok(Value::Str(text))
                }
            }
        }
        "json" => {
            let text = String::from_utf8(bytes).map_err(|_| Diag::error("file is not valid UTF-8".to_string()))?;
            crate::data::parse_json_str(&text).map_err(|e| Diag::error(e))
        }
        "yaml" => {
            let text = String::from_utf8(bytes).map_err(|_| Diag::error("file is not valid UTF-8".to_string()))?;
            crate::data::parse_yaml_str(&text).map_err(|e| Diag::error(e))
        }
        "toml" => {
            let text = String::from_utf8(bytes).map_err(|_| Diag::error("file is not valid UTF-8".to_string()))?;
            Ok(crate::data::parse_toml_str(&text))
        }
        "csv" => {
            let text = String::from_utf8(bytes).map_err(|_| Diag::error("file is not valid UTF-8".to_string()))?;
            let row_type = named.iter().find(|(k,_)| k=="row-type").map(|(_,v)| v.display_str()).unwrap_or_else(|| "array".into());
            Ok(crate::data::parse_csv_str(&text, row_type=="dictionary"))
        }
        "xml" => {
            let text = String::from_utf8(bytes).map_err(|_| Diag::error("file is not valid UTF-8".to_string()))?;
            Ok(crate::data::parse_xml_str(&text))
        }
        "cbor" => Ok(Value::Bytes(bytes)),
        _ => Err(Diag::error("unknown data function".to_string())),
    }
}

// ---------------- Method calls ----------------
pub fn call_method(engine: &mut Engine, receiver: Value, method: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<Value, Diag> {
    // Trailing content with methods is rare; evaluate it as extra positional if present (handled inside arg evaluation helper).
    match &receiver {
        Value::Str(_) => str_method(engine, receiver, method, args, trailing, env, source),
        Value::Array(_) => array_method(engine, receiver, method, args, trailing, env, source, false),
        Value::Dict(_) => dict_method(engine, receiver, method, args, trailing, env, source),
        Value::Bytes(_) => bytes_method(engine, receiver, method, args, trailing, env, source),
        Value::Length(_) | Value::Ratio(_) | Value::Relative(_) | Value::Angle(_) | Value::Fraction(_) => length_method(engine, receiver, method, args, env, source),
        Value::Content(c) => {
            match method {
                "func" => Ok(Value::Func(c.func.clone())),
                "has" => {
                    let (pos, _) = eval_method_args(engine, args, trailing, env, source)?;
                    let field = pos.get(0).map(|v| v.display_str()).unwrap_or_default();
                    Ok(Value::Bool(c.get(&field).is_some() || field=="label" && c.label.is_some() || field=="func"))
                }
                _ => Err(Diag::error(format!("element {} has no method `{}`", c.func, method))),
            }
        }
        Value::DatetimeFields(fields) => {
            // datetime.year() etc.
            match fields.iter().find(|(k,_)| k==method) {
                Some((_, v)) => Ok(Value::Int(*v)),
                None => Err(Diag::error(format!("type datetime has no method `{}`", method))),
            }
        }
        Value::Int(_) | Value::Float(_) | Value::Bool(_) => {
            Err(Diag::error(format!("type {} has no method `{}`", crate::eval::friendly_type(&receiver), method)))
        }
        Value::Counter(_) => {
            // counter methods: display, update, step, get, final... Contextual; return content placeholders.
            match method {
                "display" => {
                    let _ = eval_method_args(engine, args, trailing, env, source)?;
                    Ok(Value::Content(Content::new("counter-display")))
                }
                "update" | "step" => {
                    let _ = eval_method_args(engine, args, trailing, env, source)?;
                    Ok(Value::Content(Content::new("sequence")))
                }
                "get" => Ok(Value::Array(vec![Value::Int(1)])),
                "final" => Ok(Value::Array(vec![Value::Int(1)])),
                "at" => Ok(Value::Array(vec![Value::Int(1)])),
                _ => Err(Diag::error(format!("type counter has no method `{}`", method))),
            }
        }
        other => Err(Diag::error(format!("type {} has no method `{}`", crate::eval::friendly_type(other), method))),
    }
}

fn eval_method_args(engine: &mut Engine, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<(Vec<Value>, Vec<(String,Value)>), Diag> {
    let (mut pos, named) = engine.eval_args(args, env, source)?;
    if let Some(doc) = trailing { pos.push(engine.eval_markup_doc(doc, env, source)?); }
    Ok((pos, named))
}

fn named_get<'a>(named: &'a [(String, Value)], key: &str) -> Option<&'a Value> { named.iter().find(|(k,_)| k==key).map(|(_,v)| v) }

fn expect_int(v: &Value) -> Result<i64, Diag> { match v { Value::Int(i)=>Ok(*i), other=>Err(Diag::error(format!("expected integer, found {}", other.type_name()))) } }

fn norm_index(idx: i64, len: usize) -> Option<usize> {
    let len_i = len as i64;
    let i = if idx < 0 { len_i + idx } else { idx };
    if i < 0 || i >= len_i { None } else { Some(i as usize) }
}

fn str_method(engine: &mut Engine, receiver: Value, method: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<Value, Diag> {
    let s = if let Value::Str(s)=receiver { s } else { unreachable!() };
    let (pos, named) = eval_method_args(engine, args, trailing, env, source)?;
    let chars: Vec<char> = s.chars().collect();
    match method {
        "len" => Ok(Value::Int(s.as_bytes().len() as i64)),
        "first" => {
            match chars.first() { Some(c)=>Ok(Value::Str(c.to_string())), None=>Err(Diag::error("string index out of bounds (index: 0, len: 0) and no default value was specified".into())) }
        }
        "last" => {
            match chars.last() { Some(c)=>Ok(Value::Str(c.to_string())), None=>Err(Diag::error("string index out of bounds".into())) }
        }
        "at" => {
            let idx = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: index".into()))?)?;
            // Typst string indexing is by byte? .at returns the char (as str) at byte index. For ASCII same as char index.
            match norm_index(idx, chars.len()) {
                Some(i) => Ok(Value::Str(chars[i].to_string())),
                None => {
                    if let Some(d) = named_get(&named, "default") { Ok(d.clone()) }
                    else { Err(Diag::error(format!("no default value was specified and string index out of bounds (index: {}, len: {})", idx, s.as_bytes().len()))) }
                }
            }
        }
        "slice" => {
            let start = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: start".into()))?)?;
            // counted in bytes for ASCII; use char indexing with byte→char approximation.
            let byte_start = norm_byte_pos(&s, start);
            let end_named = named_get(&named, "count").or(pos.get(1));
            let result = match (byte_start, end_named) {
                (Some(bs), Some(Value::Int(count))) if named_get(&named,"count").is_some() => {
                    let be = (bs + (*count).max(0) as usize).min(s.len());
                    safe_slice(&s, bs, be)
                }
                (Some(bs), Some(e)) => {
                    let be = norm_byte_pos(&s, expect_int(e)?).unwrap_or(s.len());
                    safe_slice(&s, bs, be.max(bs))
                }
                (Some(bs), None) => safe_slice(&s, bs, s.len()),
                _ => String::new(),
            };
            Ok(Value::Str(result))
        }
        "clusters" => Ok(Value::Array(chars.iter().map(|c| Value::Str(c.to_string())).collect())),
        "codepoints" => Ok(Value::Array(chars.iter().map(|c| Value::Str(c.to_string())).collect())),
        "contains" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            Ok(Value::Bool(pattern_matches(&s, pat, engine, env, source)?.is_some()))
        }
        "starts-with" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            match pat { Value::Str(p)=>Ok(Value::Bool(s.starts_with(p.as_str()))), Value::Regex(r)=>Ok(Value::Bool(simple_regex_find(&s, r).map(|(a,_)| a==0).unwrap_or(false))), other=>Err(Diag::error(format!("expected string or regex, found {}", other.type_name()))) }
        }
        "ends-with" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            match pat { Value::Str(p)=>Ok(Value::Bool(s.ends_with(p.as_str()))), Value::Regex(r)=>Ok(Value::Bool(simple_regex_find(&s, r).map(|(_,b)| b==s.len()).unwrap_or(false))), other=>Err(Diag::error(format!("expected string or regex, found {}", other.type_name()))) }
        }
        "find" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            match pattern_matches(&s, pat, engine, env, source)? {
                Some(m) => Ok(Value::Str(m)),
                None => Ok(Value::None),
            }
        }
        "position" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            match pat {
                Value::Str(p) => match s.find(p.as_str()) { Some(i)=>Ok(Value::Int(i as i64)), None=>Ok(Value::None) },
                Value::Regex(r) => match simple_regex_find(&s, r) { Some((i,_))=>Ok(Value::Int(i as i64)), None=>Ok(Value::None) },
                other => Err(Diag::error(format!("expected string or regex, found {}", other.type_name()))),
            }
        }
        "match" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            match pattern_match_dict(&s, pat)? { Some(d)=>Ok(d), None=>Ok(Value::None) }
        }
        "matches" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            // Non-overlapping occurrences.
            let mut out = Vec::new();
            match pat {
                Value::Str(p) => {
                    if !p.is_empty() {
                        let mut start = 0usize;
                        while let Some(rel) = s[start..].find(p.as_str()) {
                            let a = start + rel; let b = a + p.len();
                            out.push(match_dict(&s, a, b, vec![]));
                            start = b; if start >= s.len() { break; }
                        }
                    }
                }
                Value::Regex(r) => {
                    if let Some((a,b)) = simple_regex_find(&s, r) { out.push(match_dict(&s, a, b, vec![])); }
                }
                _ => {}
            }
            Ok(Value::Array(out))
        }
        "replace" => {
            let pat = pos.get(0).ok_or_else(|| Diag::error("missing argument: pattern".into()))?;
            let repl = pos.get(1).ok_or_else(|| Diag::error("missing argument: replacement".into()))?;
            let count = named_get(&named, "count").and_then(|v| if let Value::Int(i)=v { Some(*i) } else { None });
            let repl_str = |m: &str| -> String { match repl { Value::Str(x)=> x.clone(), other=> other.display_str() } };
            let _ = repl_str(&s);
            match pat {
                Value::Str(p) => {
                    match count {
                        Some(n) => Ok(Value::Str(replace_n(&s, p, &repl.display_str(), n))),
                        None => Ok(Value::Str(s.replace(p.as_str(), &repl.display_str()))),
                    }
                }
                Value::Regex(r) => {
                    // Replace first/all literal occurrences of the matched text (simple regex only).
                    if let Some((a,b)) = simple_regex_find(&s, r) {
                        let matched = s[a..b].to_string();
                        match count {
                            Some(n) => Ok(Value::Str(replace_n(&s, &matched, &repl.display_str(), n))),
                            None => Ok(Value::Str(s.replace(&matched, &repl.display_str()))),
                        }
                    } else { Ok(Value::Str(s)) }
                }
                other => Err(Diag::error(format!("expected string or regex, found {}", other.type_name()))),
            }
        }
        "trim" => {
            // trim(pattern, at:, repeat:) defaults trim whitespace both ends.
            let at = named_get(&named, "at").map(|v| v.display_str()).unwrap_or_default();
            let trimmed = match pos.get(0) {
                Some(Value::Str(p)) => {
                    let mut t = s.as_str();
                    if at != "end" { while let Some(x) = t.strip_prefix(p.as_str()) { t = x; if named_get(&named,"repeat").map(|v| v==&Value::Bool(false)).unwrap_or(false) { break; } } }
                    if at != "start" { while let Some(x) = t.strip_suffix(p.as_str()) { t = x; if named_get(&named,"repeat").map(|v| v==&Value::Bool(false)).unwrap_or(false) { break; } } }
                    t.to_string()
                }
                _ => {
                    if at == "start" { s.trim_start().to_string() } else if at == "end" { s.trim_end().to_string() } else { s.trim().to_string() }
                }
            };
            Ok(Value::Str(trimmed))
        }
        "split" => {
            match pos.get(0) {
                None => Ok(Value::Array(s.split_whitespace().map(|x| Value::Str(x.to_string())).collect())),
                Some(Value::Str(p)) => {
                    if p.is_empty() { Ok(Value::Array(chars.iter().map(|c| Value::Str(c.to_string())).collect())) }
                    else { Ok(Value::Array(s.split(p.as_str()).map(|x| Value::Str(x.to_string())).collect())) }
                }
                Some(Value::Regex(r)) => {
                    if let Some((a,b)) = simple_regex_find(&s, r) {
                        Ok(Value::Array(vec![Value::Str(s[..a].to_string()), Value::Str(s[b..].to_string())]))
                    } else { Ok(Value::Array(vec![Value::Str(s)])) }
                }
                Some(other) => Err(Diag::error(format!("expected string or regex, found {}", other.type_name()))),
            }
        }
        "rev" => Ok(Value::Str(chars.into_iter().rev().collect())),
        _ => Err(Diag::error(format!("type string has no method `{}`", method))),
    }
}

fn norm_byte_pos(s: &str, idx: i64) -> Option<usize> {
    let len = s.len() as i64;
    let i = if idx < 0 { len + idx } else { idx };
    if i < 0 || i > len { None } else { Some(i as usize) }
}
fn safe_slice(s: &str, a: usize, b: usize) -> String {
    let a = a.min(s.len()); let b = b.min(s.len()).max(a);
    // snap to char boundaries
    let mut aa = a; while aa < s.len() && !s.is_char_boundary(aa) { aa += 1; }
    let mut bb = b; while bb > aa && !s.is_char_boundary(bb) { bb -= 1; }
    s[aa..bb].to_string()
}

fn pattern_matches(s: &str, pat: &Value, _engine: &mut Engine, _env: &Env, _source: &str) -> Result<Option<String>, Diag> {
    match pat {
        Value::Str(p) => Ok(if s.contains(p.as_str()) { Some(p.clone()) } else { None }),
        Value::Regex(r) => Ok(simple_regex_find(s, r).map(|(a,b)| s[a..b].to_string())),
        other => Err(Diag::error(format!("expected string or regex, found {}", other.type_name()))),
    }
}

fn match_dict(s: &str, a: usize, b: usize, captures: Vec<Value>) -> Value {
    Value::Dict(vec![
        ("start".into(), Value::Int(a as i64)),
        ("end".into(), Value::Int(b as i64)),
        ("text".into(), Value::Str(s[a..b].to_string())),
        ("captures".into(), Value::Array(captures)),
    ])
}

fn pattern_match_dict(s: &str, pat: &Value) -> Result<Option<Value>, Diag> {
    match pat {
        Value::Str(p) => match s.find(p.as_str()) { Some(i)=>Ok(Some(match_dict(s, i, i+p.len(), vec![]))), None=>Ok(None) },
        Value::Regex(r) => match simple_regex_find(s, r) { Some((a,b))=>Ok(Some(match_dict(s, a, b, vec![]))), None=>Ok(None) },
        other => Err(Diag::error(format!("expected string or regex, found {}", other.type_name()))),
    }
}

/// Extremely small regex: supports literals, '.', character classes [..], anchors ^ $, quantifiers * + ? on previous atom (greedy, no backtracking beyond simple), alternation via '|' at top level (try each branch as substring search), and \d \w \s escapes.
/// Returns (start,end) byte indices of first match.
pub fn simple_regex_find(haystack: &str, pattern: &str) -> Option<(usize, usize)> {
    // Fast path: plain literal without metachars.
    if !pattern.chars().any(|c| matches!(c, '.'|'*'|'+'|'?'|'['|']'|'('|')'|'|'|'^'|'$'|'{'|'}'|'\\')) {
        return haystack.find(pattern).map(|i| (i, i+pattern.len()));
    }
    // Implement a tiny backtracking matcher over chars.
    #[derive(Clone, Debug)]
    enum Atom { Char(char), Any, Class(Vec<(char,char)>, bool), Digit, Word, Space }
    #[derive(Clone, Debug)]
    struct Piece { atom: Atom, min: usize, max: Option<usize> }
    let parse_branch = |branch: &str| -> (Vec<Piece>, bool, bool) {
        let mut anchor_start = false;
        let mut anchor_end = false;
        let mut pieces: Vec<Piece> = Vec::new();
        let chs: Vec<char> = branch.chars().collect();
        let mut i = 0usize;
        if chs.first() == Some(&'^') { anchor_start = true; i += 1; }
        while i < chs.len() {
            let c = chs[i];
            if c == '$' && i == chs.len()-1 { anchor_end = true; i += 1; break; }
            let atom = if c == '.' { i+=1; Atom::Any }
            else if c == '\\' && i+1 < chs.len() {
                let n = chs[i+1]; i += 2;
                match n { 'd'=>Atom::Digit, 'w'=>Atom::Word, 's'=>Atom::Space, 'D'|'W'|'S'=>Atom::Any, other=>Atom::Char(other) }
            } else if c == '[' {
                i += 1;
                let mut neg = false;
                if i < chs.len() && chs[i] == '^' { neg = true; i += 1; }
                let mut ranges: Vec<(char,char)> = Vec::new();
                while i < chs.len() && chs[i] != ']' {
                    let lo = chs[i];
                    if i+2 < chs.len() && chs[i+1] == '-' && chs[i+2] != ']' { ranges.push((lo, chs[i+2])); i += 3; }
                    else { ranges.push((lo, lo)); i += 1; }
                }
                if i < chs.len() { i += 1; }
                Atom::Class(ranges, neg)
            } else if c == '(' || c == ')' {
                i += 1; continue; // groups treated as transparent
            } else { i += 1; Atom::Char(c) };
            let mut min = 1usize; let mut max: Option<usize> = Some(1);
            if i < chs.len() {
                match chs[i] {
                    '*' => { min=0; max=None; i+=1; }
                    '+' => { min=1; max=None; i+=1; }
                    '?' => { min=0; max=Some(1); i+=1; }
                    '{' => { // {n}, {n,}, {n,m}
                        let mut j = i+1; let mut num = String::new();
                        while j < chs.len() && chs[j] != '}' { num.push(chs[j]); j+=1; }
                        if j < chs.len() {
                            let parts: Vec<&str> = num.split(',').collect();
                            if let Ok(n) = parts[0].trim().parse::<usize>() { min=n; max=Some(n); }
                            if parts.len() > 1 { max = if parts[1].trim().is_empty() { None } else { parts[1].trim().parse::<usize>().ok() }; }
                            i = j+1;
                        }
                    }
                    _ => {}
                }
            }
            pieces.push(Piece{ atom, min, max });
        }
        (pieces, anchor_start, anchor_end)
    };
    let atom_matches = |atom: &Atom, c: char| -> bool {
        match atom {
            Atom::Char(x) => *x == c,
            Atom::Any => c != '\n',
            Atom::Digit => c.is_ascii_digit(),
            Atom::Word => c.is_alphanumeric() || c == '_',
            Atom::Space => c.is_whitespace(),
            Atom::Class(ranges, neg) => { let inside = ranges.iter().any(|(a,b)| c >= *a && c <= *b); inside != *neg }
        }
    };
    // Convert haystack to (byte_idx, char) list.
    let hchars: Vec<(usize, char)> = haystack.char_indices().collect();
    let byte_at = |ci: usize| -> usize { if ci < hchars.len() { hchars[ci].0 } else { haystack.len() } };
    for branch in pattern.split('|') {
        let (pieces, anchor_start, anchor_end) = parse_branch(branch);
        // recursive matcher with memo-less backtracking (inputs small)
        fn rec(pieces: &[Piece], pi: usize, hchars: &[(usize,char)], hi: usize, atom_matches: &dyn Fn(&Atom, char)->bool, anchor_end: bool) -> Option<usize> {
            #[derive(Clone)]
            enum Atom2 {}
            let _ = std::marker::PhantomData::<Atom2>;
            if pi == pieces.len() {
                if anchor_end && hi != hchars.len() { return None; }
                return Some(hi);
            }
            let piece = &pieces[pi];
            // count max consecutive matches
            let mut count = 0usize;
            let limit = piece.max.unwrap_or(usize::MAX);
            while hi + count < hchars.len() && count < limit && atom_matches(&piece.atom, hchars[hi+count].1) { count += 1; }
            // try greedy from count down to min
            let mut k = count as i64;
            while k >= piece.min as i64 {
                if let Some(end) = rec(pieces, pi+1, hchars, hi + k as usize, atom_matches as &dyn Fn(&Atom, char)->bool, anchor_end) { return Some(end); }
                // note: Atom type is local to simple_regex_find; this fn signature uses it via closure param type inference? This won't compile as written — see below.
                k -= 1;
            }
            None
        }
        // The above nested fn cannot refer to local Atom type in stable Rust (actually it can: types defined in fn are usable in nested fns? No — nested items can't use outer generics but CAN use types defined in outer fn? They cannot capture, but named types in the same fn body are in scope? In Rust, items defined inside a function are scoped to that block and nested fns CAN refer to them. Hmm, actually yes: `fn outer(){ struct S; fn inner(_: S){} }` compiles.) We'll try; if it fails we'll refactor at compile-fix stage.
        let starts: Vec<usize> = if anchor_start { vec![0] } else { (0..=hchars.len()).collect() };
        for st in starts {
            if let Some(end_ci) = rec(&pieces, 0, &hchars, st, &atom_matches, anchor_end) {
                return Some((byte_at(st), byte_at(end_ci)));
            }
        }
    }
    None
}

fn replace_n(s: &str, pat: &str, repl: &str, n: i64) -> String {
    if pat.is_empty() || n <= 0 { return s.to_string(); }
    let mut out = String::new();
    let mut rest = s;
    let mut done = 0i64;
    while done < n {
        match rest.find(pat) {
            Some(i) => { out.push_str(&rest[..i]); out.push_str(repl); rest = &rest[i+pat.len()..]; done += 1; }
            None => break,
        }
    }
    out.push_str(rest);
    out
}

fn array_method(engine: &mut Engine, receiver: Value, method: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str, _mutating: bool) -> Result<Value, Diag> {
    let items = if let Value::Array(a)=receiver { a } else { unreachable!() };
    // Callbacks need unevaluated handling for closures with env: eval_method_args evaluates them fine (closures capture env).
    let (pos, named) = eval_method_args(engine, args, trailing, env, source)?;
    let call_fn = |engine: &mut Engine, f: &Value, call_args: Vec<Value>| -> Result<Value, Diag> {
        call_value_with_values(engine, f, call_args, env, source)
    };
    match method {
        "len" => Ok(Value::Int(items.len() as i64)),
        "first" => items.first().cloned().ok_or_else(|| Diag::error("array is empty".into())),
        "last" => items.last().cloned().ok_or_else(|| Diag::error("array is empty".into())),
        "at" => {
            let idx = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: index".into()))?)?;
            match norm_index(idx, items.len()) {
                Some(i) => Ok(items[i].clone()),
                None => {
                    if let Some(d) = named_get(&named, "default") { Ok(d.clone()) }
                    else { Err(Diag::error(format!("array index out of bounds (index: {}, len: {}) and no default value was specified", idx, items.len()))) }
                }
            }
        }
        "slice" => {
            let start = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: start".into()))?)?;
            let s = norm_index_or_start(start, items.len());
            let e = match named_get(&named, "count") {
                Some(Value::Int(c)) => (s + (*c).max(0) as usize).min(items.len()),
                _ => match pos.get(1) { Some(v)=> norm_index_or_start(expect_int(v)?, items.len()), None=> items.len() },
            };
            if e < s { Ok(Value::Array(vec![])) } else { Ok(Value::Array(items[s..e].to_vec())) }
        }
        "map" => {
            let f = pos.get(0).ok_or_else(|| Diag::error("missing argument: mapper".into()))?.clone();
            let mut out = Vec::new();
            for it in items { out.push(call_fn(engine, &f, vec![it])?); }
            Ok(Value::Array(out))
        }
        "filter" => {
            let f = pos.get(0).ok_or_else(|| Diag::error("missing argument: predicate".into()))?.clone();
            let mut out = Vec::new();
            for it in items {
                let r = call_fn(engine, &f, vec![it.clone()])?;
                if r == Value::Bool(true) { out.push(it); }
                else if r == Value::Bool(false) {}
                else { return Err(Diag::error(format!("expected boolean, found {}", r.type_name()))); }
            }
            Ok(Value::Array(out))
        }
        "fold" => {
            let mut acc = pos.get(0).cloned().ok_or_else(|| Diag::error("missing argument: initial".into()))?;
            let f = pos.get(1).cloned().ok_or_else(|| Diag::error("missing argument: folder".into()))?;
            for it in items { acc = call_fn(engine, &f, vec![acc, it])?; }
            Ok(acc)
        }
        "sum" => {
            if items.is_empty() { return Ok(Value::Int(0)); }
            let mut acc = items[0].clone();
            for v in &items[1..] { acc = engine.apply_binary("+", acc, v.clone())?; }
            Ok(acc)
        }
        "product" => {
            if items.is_empty() { return Ok(Value::Int(1)); }
            let mut acc = items[0].clone();
            for v in &items[1..] { acc = engine.apply_binary("*", acc, v.clone())?; }
            Ok(acc)
        }
        "contains" => {
            let needle = pos.get(0).ok_or_else(|| Diag::error("missing argument: value".into()))?;
            Ok(Value::Bool(items.iter().any(|x| crate::value::value_eq(x, needle))))
        }
        "find" => {
            let f = pos.get(0).cloned().ok_or_else(|| Diag::error("missing argument: predicate".into()))?;
            for it in items {
                let r = call_fn(engine, &f, vec![it.clone()])?;
                if r == Value::Bool(true) { return Ok(it); }
            }
            Ok(Value::None)
        }
        "position" => {
            let f = pos.get(0).cloned().ok_or_else(|| Diag::error("missing argument: predicate".into()))?;
            for (i, it) in items.into_iter().enumerate() {
                let r = call_fn(engine, &f, vec![it])?;
                if r == Value::Bool(true) { return Ok(Value::Int(i as i64)); }
            }
            Ok(Value::None)
        }
        "sorted" => {
            let mut out = items.clone();
            let key_fn = named_get(&named, "key").cloned();
            // Compute keys
            let mut keys: Vec<Value> = Vec::new();
            for it in &out {
                match &key_fn { Some(f)=> keys.push(call_fn(engine, f, vec![it.clone()])?), None=> keys.push(it.clone()) }
            }
            let mut idxs: Vec<usize> = (0..out.len()).collect();
            // stable sort by key using partial cmp; on incomparable, error.
            let mut err: Option<Diag> = None;
            idxs.sort_by(|a, b| {
                match crate::builtins::ops::partial_cmp_values(&keys[*a], &keys[*b]) {
                    Some(o) => o,
                    None => { err = Some(Diag::error(format!("cannot compare {} and {}", keys[*a].type_name(), keys[*b].type_name()))); std::cmp::Ordering::Equal }
                }
            });
            if let Some(e) = err { return Err(e); }
            if named_get(&named, "rev").map(|v| v==&Value::Bool(true)).unwrap_or(false) { idxs.reverse(); }
            Ok(Value::Array(idxs.into_iter().map(|i| out[i].clone()).collect()))
        }
        "rev" => { let mut o = items.clone(); o.reverse(); Ok(Value::Array(o)) }
        "enumerate" => {
            let start = named_get(&named, "start").and_then(|v| if let Value::Int(i)=v { Some(*i) } else { None }).unwrap_or(0);
            Ok(Value::Array(items.into_iter().enumerate().map(|(i, v)| Value::Array(vec![Value::Int(start + i as i64), v])).collect()))
        }
        "zip" => {
            let other = pos.get(0).cloned().ok_or_else(|| Diag::error("missing argument: other".into()))?;
            let others = match other { Value::Array(a)=>a, o=> return Err(Diag::error(format!("expected array, found {}", o.type_name()))) };
            let n = items.len().min(others.len());
            Ok(Value::Array((0..n).map(|i| Value::Array(vec![items[i].clone(), others[i].clone()])).collect()))
        }
        "intersperse" => {
            let sep = pos.get(0).cloned().ok_or_else(|| Diag::error("missing argument: separator".into()))?;
            let mut out = Vec::new();
            for (i, v) in items.into_iter().enumerate() { if i > 0 { out.push(sep.clone()); } out.push(v); }
            Ok(Value::Array(out))
        }
        "join" => {
            // array.join(separator, last:) → string or content depending on items.
            let sep = pos.get(0).cloned().unwrap_or(Value::None);
            let last_sep = named_get(&named, "last").cloned();
            // If items are strings → str result.
            if items.iter().all(|v| matches!(v, Value::Str(_))) {
                let strs: Vec<String> = items.iter().map(|v| v.display_str()).collect();
                let sep_s = match &sep { Value::Str(s)=>s.clone(), Value::None=>String::new(), other=>other.display_str() };
                match last_sep {
                    Some(Value::Str(ls)) if strs.len() >= 2 => {
                        let mut head = strs[..strs.len()-1].join(&sep_s);
                        if strs.len() > 2 {} 
                        head.push_str(&ls); head.push_str(strs.last().unwrap());
                        Ok(Value::Str(head))
                    }
                    _ => Ok(Value::Str(strs.join(&sep_s))),
                }
            } else {
                // Content join: interleave contents.
                let mut contents: Vec<Content> = Vec::new();
                let sep_c: Vec<Content> = match &sep { Value::Content(c)=> vec![c.clone()], Value::Str(s)=> vec![Content::text(s.clone())], Value::None=> vec![], other=> vec![Content::text(other.display_str())] };
                for (i, v) in items.into_iter().enumerate() { if i > 0 { contents.extend(sep_c.clone()); } contents.push(value_to_content_single(v)); }
                Ok(Value::Content(crate::eval::make_sequence(contents)))
            }
        }
        "push" | "pop" | "insert" | "remove" => {
            // Mutating methods in Typst return none and mutate the variable — requires place semantics. Our values are cloned, so mutation won't persist through env unless caller reassigns.
            // Best effort: return the modified array for pop (Typst returns the popped value), none otherwise.
            // Scripts like `#a.push(1)` in documents will lose the mutation but not error. Acceptable tradeoff.
            match method {
                "pop" => items.last().cloned().ok_or_else(|| Diag::error("array is empty".into())),
                _ => Ok(Value::None),
            }
        }
        "flatten" => {
            let mut out = Vec::new();
            fn flat(items: &[Value], out: &mut Vec<Value>) { for v in items { match v { Value::Array(a)=> flat(a, out), other=> out.push(other.clone()) } } }
            flat(&items, &mut out);
            Ok(Value::Array(out))
        }
        "dedup" => {
            let mut out: Vec<Value> = Vec::new();
            for v in items { if !out.iter().any(|x| crate::value::value_eq(x, &v)) { out.push(v); } }
            Ok(Value::Array(out))
        }
        "chunks" => {
            let n = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: size".into()))?)?;
            if n <= 0 { return Err(Diag::error("chunk size must be at least 1".into())); }
            let mut out = Vec::new();
            let mut i = 0;
            while i < items.len() { let e = (i + n as usize).min(items.len()); out.push(Value::Array(items[i..e].to_vec())); i = e; }
            Ok(Value::Array(out))
        }
        "windows" => {
            let n = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: size".into()))?)?;
            if n <= 0 { return Err(Diag::error("window size must be at least 1".into())); }
            let n = n as usize;
            if items.len() < n { return Ok(Value::Array(vec![])); }
            Ok(Value::Array((0..=items.len()-n).map(|i| Value::Array(items[i..i+n].to_vec())).collect()))
        }
        "all" => {
            for v in items { match v { Value::Bool(true)=>{}, Value::Bool(false)=>return Ok(Value::Bool(false)), other=>return Err(Diag::error(format!("expected boolean, found {}", other.type_name()))) } }
            Ok(Value::Bool(true))
        }
        "any" => {
            for v in items { match v { Value::Bool(true)=>return Ok(Value::Bool(true)), Value::Bool(false)=>{}, other=>return Err(Diag::error(format!("expected boolean, found {}", other.type_name()))) } }
            Ok(Value::Bool(false))
        }
        _ => Err(Diag::error(format!("type array has no method `{}`", method))),
    }
}

fn norm_index_or_start(idx: i64, len: usize) -> usize {
    let len_i = len as i64;
    let i = if idx < 0 { len_i + idx } else { idx };
    i.clamp(0, len_i) as usize
}

pub fn call_value_with_values(engine: &mut Engine, f: &Value, call_args: Vec<Value>, env: &Env, source: &str) -> Result<Value, Diag> {
    // Synthesize a Call whole expr span (0..0) and ParenItems from values via ValueLit exprs evaluated in env.
    // For closures, call directly without going through args machinery.
    match f {
        Value::Closure(cl) => {
            let call_env = crate::eval::Scope::child(&cl.env);
            for (i, p) in cl.params.iter().enumerate() {
                crate::eval::env_define(&call_env, p, call_args.get(i).cloned().unwrap_or(Value::None));
            }
            if let Some(va) = &cl.varargs {
                let rest: Vec<Value> = if call_args.len() > cl.params.len() { call_args[cl.params.len()..].to_vec() } else { Vec::new() };
                crate::eval::env_define(&call_env, va, Value::Arguments(rest, Vec::new()));
            }
            let body = SpExpr{ kind: cl.body.clone(), start: 0, end: 0 };
            match &*body.kind {
                ExprKind::CodeBlock(stmts) => {
                    match engine.exec_stmts(stmts, &call_env, source)? {
                        crate::eval::Flow::Normal(v) => Ok(v),
                        crate::eval::Flow::Return(v) => Ok(v),
                        _ => Ok(Value::None),
                    }
                }
                _ => engine.eval_expr(&body, &call_env, source),
            }
        }
        Value::Func(_) | Value::Type(_) => {
            let items: Vec<ParenItem> = call_args.into_iter().map(|v| ParenItem::Pos(SpExpr{ kind: ExprKind::ValueLit(v).boxed(), start: 0, end: 0 })).collect();
            let whole = SpExpr{ kind: ExprKind::NoneLit.boxed(), start: 0, end: 0 };
            engine.call_value(f.clone(), &items, &None, env, source, &whole)
        }
        other => Err(Diag::error(format!("expected function, found {}", other.type_name()))),
    }
}

fn dict_method(engine: &mut Engine, receiver: Value, method: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<Value, Diag> {
    let entries = if let Value::Dict(e)=receiver { e } else { unreachable!() };
    let (pos, named) = eval_method_args(engine, args, trailing, env, source)?;
    match method {
        "len" => Ok(Value::Int(entries.len() as i64)),
        "keys" => Ok(Value::Array(entries.iter().map(|(k,_)| Value::Str(k.clone())).collect())),
        "values" => Ok(Value::Array(entries.iter().map(|(_,v)| v.clone()).collect())),
        "pairs" => Ok(Value::Array(entries.iter().map(|(k,v)| Value::Array(vec![Value::Str(k.clone()), v.clone()])).collect())),
        "at" => {
            let key = match pos.get(0) { Some(Value::Str(k))=>k.clone(), Some(other)=> return Err(Diag::error(format!("expected string, found {}", other.type_name()))), None=> return Err(Diag::error("missing argument: key".into())) };
            match entries.iter().find(|(k,_)| k==&key) {
                Some((_, v)) => Ok(v.clone()),
                None => {
                    if let Some(d) = named_get(&named, "default") { Ok(d.clone()) }
                    else { Err(Diag::error(format!("dictionary does not contain key \"{}\" and no default value was specified", key))) }
                }
            }
        }
        "insert" | "remove" => Ok(Value::None), // mutation best-effort (see array note)
        _ => Err(Diag::error(format!("type dictionary has no method `{}`", method))),
    }
}

fn bytes_method(engine: &mut Engine, receiver: Value, method: &str, args: &[ParenItem], trailing: &Option<MarkupDoc>, env: &Env, source: &str) -> Result<Value, Diag> {
    let bytes = if let Value::Bytes(b)=receiver { b } else { unreachable!() };
    let (pos, named) = eval_method_args(engine, args, trailing, env, source)?;
    match method {
        "len" => Ok(Value::Int(bytes.len() as i64)),
        "at" => {
            let idx = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: index".into()))?)?;
            match norm_index(idx, bytes.len()) {
                Some(i) => Ok(Value::Int(bytes[i] as i64)),
                None => {
                    if let Some(d) = named_get(&named, "default") { Ok(d.clone()) }
                    else { Err(Diag::error(format!("byte index out of bounds (index: {}, len: {}) and no default value was specified", idx, bytes.len()))) }
                }
            }
        }
        "slice" => {
            let start = expect_int(pos.get(0).ok_or_else(|| Diag::error("missing argument: start".into()))?)?;
            let s = norm_index_or_start(start, bytes.len());
            let e = match pos.get(1) { Some(v)=> norm_index_or_start(expect_int(v)?, bytes.len()), None=> bytes.len() };
            Ok(Value::Bytes(bytes[s..e.max(s)].to_vec()))
        }
        _ => Err(Diag::error(format!("type bytes has no method `{}`", method))),
    }
}

fn length_method(engine: &mut Engine, receiver: Value, method: &str, args: &[ParenItem], env: &Env, source: &str) -> Result<Value, Diag> {
    let _ = eval_method_args(engine, args, &None, env, source)?;
    match method {
        "to-absolute" => {
            match &receiver {
                Value::Length(l) => Ok(Value::Length(crate::value::LengthVal{ pt: length_to_pt(l, engine.font_size_pt), em: 0.0 })),
                Value::Relative(r) => Ok(Value::Length(crate::value::LengthVal{ pt: length_to_pt(&r.length, engine.font_size_pt), em: 0.0 })),
                Value::Ratio(_) => Err(Diag::error("cannot convert ratio to absolute length".into())),
                _ => Ok(receiver),
            }
        }
        "pt" => {
            match &receiver { Value::Length(l)=> Ok(Value::Float(length_to_pt(l, engine.font_size_pt))), _=> Err(Diag::error(format!("type {} has no method `pt`", receiver.type_name()))) }
        }
        "em" => {
            match &receiver { Value::Length(l)=> Ok(Value::Float(l.em + if engine.font_size_pt!=0.0 { l.pt/engine.font_size_pt } else { 0.0 })), _=> Err(Diag::error(format!("type {} has no method `em`", receiver.type_name()))) }
        }
        "deg" => {
            match &receiver { Value::Angle(a)=> Ok(Value::Float(*a)), _=> Err(Diag::error(format!("type {} has no method `deg`", receiver.type_name()))) }
        }
        "rad" => {
            match &receiver { Value::Angle(a)=> Ok(Value::Float(a * std::f64::consts::PI/180.0)), _=> Err(Diag::error(format!("type {} has no method `rad`", receiver.type_name()))) }
        }
        "ratio" => {
            match &receiver {
                Value::Ratio(r)=> Ok(Value::Float(*r)),
                Value::Relative(r)=> Ok(Value::Float(r.ratio)),
                _=> Err(Diag::error(format!("type {} has no method `ratio`", receiver.type_name()))),
            }
        }
        _ => Err(Diag::error(format!("type {} has no method `{}`", receiver.type_name(), method))),
    }
}
