use std::path::PathBuf;
use crate::world::Project;

#[derive(Clone, Debug)]
pub struct BareSpec {
    pub namespace: String,
    pub name: String,
    pub version: Option<(u64,u64,u64)>,
}

/// Parse an init template spec / package spec for error messages matching observations.
/// Returns Err(message) where message is the text after "error: ".
pub fn parse_bare_spec(spec: &str) -> Result<BareSpec, String> {
    if !spec.starts_with('@') {
        return Err("package specification must start with '@'".to_string());
    }
    let body = &spec[1..];
    let (namespace, rest) = match body.split_once('/') {
        Some((a,b)) => (a, b),
        None => {
            // No slash at all: e.g. "@preview" — treat as missing name? Unprobed; choose missing name if namespace non-empty else missing namespace.
            if body.is_empty() { return Err("package specification is missing namespace".into()); }
            return Err("package specification is missing name".into());
        }
    };
    if namespace.is_empty() {
        return Err("package specification is missing namespace".to_string());
    }
    // Namespace validity: "@@preview/foo" gives namespace "@preview" → invalid (starts with @). General rule: lowercase ascii + digits + '-'? Observed "@PREVIEW/foo" did NOT give namespace error but "please specify the desired version" (treated as unknown namespace without version?). Hmm.
    // So invalid-namespace check is narrower: probably namespaces must match [a-z0-9-_]+ but uppercase... observed @PREVIEW passed this check. Wait re-read: run gave `error: please specify the desired version` for @PREVIEW/foo. That error occurs when namespace != "preview" (only preview queries index; others require explicit version). So @PREVIEW is a *valid* (non-preview) namespace. And @@preview → namespace "@preview" contains '@' → invalid.
    // Rule: namespace must be non-empty and consist of [A-Za-z0-9_-]? Let's require alphanumeric start and chars in [A-Za-z0-9_-].
    let ns_valid = !namespace.is_empty() && namespace.chars().all(|c| c.is_ascii_alphanumeric() || c=='-' || c=='_') && namespace.chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false);
    if !ns_valid {
        return Err(format!("`{}` is not a valid package namespace", namespace));
    }
    if rest.is_empty() {
        return Err("package specification is missing name".to_string());
    }
    // rest = name[:version]  — but name may contain '/' if extra path (init treats as invalid name, probed "foo/bar").
    let (name, version_str) = match rest.split_once(':') {
        Some((n,v)) => (n, Some(v)),
        None => (rest, None),
    };
    // Name validity (observed "foo/bar" invalid). Names: start alphanumeric? Typst package names: lowercase letters/digits/'-'/'_' starting with letter/digit? "Foo_Bar" passed name check (went to network). So allow [A-Za-z0-9_-]+ starting with alphanumeric.
    let name_valid = !name.is_empty() && name.chars().all(|c| c.is_ascii_alphanumeric() || c=='-' || c=='_') && name.chars().next().map(|c| c.is_ascii_alphanumeric()).unwrap_or(false);
    if !name_valid {
        return Err(format!("`{}` is not a valid package name", name));
    }
    let version = match version_str {
        None => None,
        Some(vs) => Some(parse_version(vs)?),
    };
    Ok(BareSpec{ namespace: namespace.to_string(), name: name.to_string(), version })
}

pub fn parse_version(vs: &str) -> Result<(u64,u64,u64), String> {
    let parts: Vec<&str> = vs.split('.').collect();
    // Observed messages:
    // "abc" → "`abc` is not a valid major version"
    // "1.0" → "version number is missing patch version"
    // By analogy: "1" → missing minor version; "1.x.0" → "`x` is not a valid minor version" etc.
    let labels = ["major", "minor", "patch"];
    let mut nums: Vec<u64> = Vec::new();
    for (i, p) in parts.iter().enumerate() {
        let label = labels.get(i).copied().unwrap_or("patch");
        match p.parse::<u64>() {
            Ok(n) => nums.push(n),
            Err(_) => return Err(format!("`{}` is not a valid {} version", p, label)),
        }
        if i >= 3 {
            // Too many components — unprobed; treat extra as invalid patch-ish. Keep first 3.
        }
    }
    if nums.len() < 2 {
        return Err("version number is missing minor version".to_string());
    }
    if nums.len() < 3 {
        return Err("version number is missing patch version".to_string());
    }
    Ok((nums[0], nums[1], nums[2]))
}

pub fn version_str(v: &(u64,u64,u64)) -> String { format!("{}.{}.{}", v.0, v.1, v.2) }

/// List locally available versions of a package in package_path/<ns>/<name>/<ver> plus cache path for preview.
pub fn local_versions(project: &Project, namespace: &str, name: &str) -> Vec<(u64,u64,u64)> {
    let mut out = Vec::new();
    let mut bases = vec![project.package_path.clone()];
    if namespace == "preview" { bases.push(project.package_cache_path.clone()); }
    for base in bases {
        let dir = base.join(namespace).join(name);
        if let Ok(rd) = std::fs::read_dir(&dir) {
            for e in rd.flatten() {
                let fname = e.file_name().to_string_lossy().to_string();
                if let Ok(v) = parse_version(&fname) {
                    if !out.contains(&v) { out.push(v); }
                }
            }
        }
    }
    out.sort();
    out
}

pub fn package_dir(project: &Project, namespace: &str, name: &str, version: &(u64,u64,u64)) -> Option<PathBuf> {
    let vs = version_str(version);
    let mut bases = vec![project.package_path.clone()];
    if namespace == "preview" { bases.push(project.package_cache_path.clone()); }
    for base in bases {
        let d = base.join(namespace).join(name).join(&vs);
        if d.is_dir() { return Some(d); }
    }
    None
}

#[derive(Clone, Debug)]
pub struct PackageManifest {
    pub name: String,
    pub version: String,
    pub entrypoint: String,
    pub template_path: Option<String>,
    pub template_entrypoint: Option<String>,
}

pub fn read_manifest(dir: &std::path::Path) -> Option<PackageManifest> {
    let text = std::fs::read_to_string(dir.join("typst.toml")).ok()?;
    let v = crate::data::parse_toml_str(&text);
    let get = |path: &[&str]| -> Option<String> {
        let mut cur = &v;
        for p in path {
            match cur { crate::value::Value::Dict(entries) => { cur = entries.iter().find(|(k,_)| k==p).map(|(_,val)| val)?; } _ => return None }
        }
        if let crate::value::Value::Str(s) = cur { Some(s.clone()) } else { None }
    };
    Some(PackageManifest{
        name: get(&["package","name"]).unwrap_or_default(),
        version: get(&["package","version"]).unwrap_or_default(),
        entrypoint: get(&["package","entrypoint"]).unwrap_or_else(|| "lib.typ".into()),
        template_path: get(&["template","path"]),
        template_entrypoint: get(&["template","entrypoint"]),
    })
}

#[derive(Clone, Debug)]
pub struct PackageImport {
    pub namespace: String,
    pub name: String,
    pub version: (u64,u64,u64),
    pub subpath: Option<String>,
}

/// Parse a Typst import path like "@preview/name:1.0.0" or "@preview/name:1.0.0/file.typ".
pub fn parse_package_import(spec: &str) -> Result<PackageImport, String> {
    // Split subpath: after version, a '/' introduces a file path.
    if let Some(idx) = find_subpath_split(spec) {
        let (head, tail) = (&spec[..idx], &spec[idx+1..]);
        let bare = parse_bare_spec(head)?;
        let version = bare.version.ok_or_else(|| "please specify the desired version".to_string())?;
        return Ok(PackageImport{ namespace: bare.namespace, name: bare.name, version, subpath: if tail.is_empty() { None } else { Some(tail.to_string()) } });
    }
    let bare = parse_bare_spec(spec)?;
    let version = bare.version.ok_or_else(|| "please specify the desired version".to_string())?;
    Ok(PackageImport{ namespace: bare.namespace, name: bare.name, version, subpath: None })
}

fn find_subpath_split(spec: &str) -> Option<usize> {
    // spec = @ns/name:ver[/sub...] — the subpath slash is the 2nd '/' overall (first is ns/name separator).
    let mut slashes = 0;
    for (i, c) in spec.char_indices() {
        if c == '/' {
            slashes += 1;
            if slashes == 2 { return Some(i); }
        }
    }
    None
}

pub fn resolve_package_file(project: &Project, imp: &PackageImport) -> Result<PathBuf, String> {
    let vs = version_str(&imp.version);
    let spec_str = format!("@{}/{}:{}", imp.namespace, imp.name, vs);
    let dir = package_dir(project, &imp.namespace, &imp.name, &imp.version)
        .ok_or_else(|| format!("package not found (searched for {})", spec_str))?;
    let manifest = read_manifest(&dir);
    let file = match &imp.subpath {
        Some(sp) => dir.join(sp),
        None => {
            let ep = manifest.map(|m| m.entrypoint).unwrap_or_else(|| "lib.typ".into());
            dir.join(ep)
        }
    };
    Ok(file)
}

