#[derive(Clone, Debug)]
pub struct InlineItem {
    pub text: String,
    pub bold: bool,
    pub italic: bool,
    pub size_scale: f64,
    pub is_space: bool,
    pub is_linebreak: bool,
}

pub fn collect_inline(c: &Content, bold: bool, italic: bool, scale: f64, out: &mut Vec<InlineItem>) {
    match c.func.as_str() {
        "text" => {
            if let Some(Value::Str(t)) = c.get("text") {
                // Split into words preserving spaces (already separate space nodes in markup eval; text may contain spaces when from code).
                let mut cur = String::new();
                for ch in t.chars() {
                    if ch == ' ' || ch == '\t' {
                        if !cur.is_empty() { out.push(InlineItem{ text: std::mem::take(&mut cur), bold, italic, size_scale: scale, is_space: false, is_linebreak: false }); }
                        out.push(InlineItem{ text: " ".into(), bold, italic, size_scale: scale, is_space: true, is_linebreak: false });
                    } else if ch == '\n' {
                        if !cur.is_empty() { out.push(InlineItem{ text: std::mem::take(&mut cur), bold, italic, size_scale: scale, is_space: false, is_linebreak: false }); }
                        out.push(InlineItem{ text: String::new(), bold, italic, size_scale: scale, is_space: false, is_linebreak: true });
                    } else { cur.push(ch); }
                }
                if !cur.is_empty() { out.push(InlineItem{ text: cur, bold, italic, size_scale: scale, is_space: false, is_linebreak: false }); }
            }
        }
        "space" => out.push(InlineItem{ text: " ".into(), bold, italic, size_scale: scale, is_space: true, is_linebreak: false }),
        "linebreak" => out.push(InlineItem{ text: String::new(), bold, italic, size_scale: scale, is_space: false, is_linebreak: true }),
        "strong" => { if let Some(Value::Content(b)) = c.get("body") { collect_inline(b, true, italic, scale, out); } }
        "emph" => { if let Some(Value::Content(b)) = c.get("body") { collect_inline(b, bold, true, scale, out); } }
        "sequence" => {
            if let Some(Value::Array(children)) = c.get("children") {
                for ch in children { if let Value::Content(cc) = ch { collect_inline(cc, bold, italic, scale, out); } }
            }
        }
        "raw" => {
            if let Some(Value::Str(t)) = c.get("text") { out.push(InlineItem{ text: t.clone(), bold, italic, size_scale: scale, is_space: false, is_linebreak: false }); }
        }
        "symbol" => {
            if let Some(Value::Str(t)) = c.get("text") { out.push(InlineItem{ text: t.clone(), bold, italic, size_scale: scale, is_space: false, is_linebreak: false }); }
        }
        "ref" => {
            // Render as label text placeholder (supplement+number in real Typst; best effort: show label).
            if let Some(Value::Label(l)) = c.get("target") { out.push(InlineItem{ text: l.clone(), bold, italic, size_scale: scale, is_space: false, is_linebreak: false }); }
        }
        "equation" => {
            if let Some(Value::Content(b)) = c.get("body") { collect_inline(b, bold, italic, scale, out); }
        }
        "attach" => {
            if let Some(Value::Content(b)) = c.get("base") { collect_inline(b, bold, italic, scale, out); }
            if let Some(Value::Content(b)) = c.get("b") { collect_inline(b, bold, italic, scale*0.7, out); }
            if let Some(Value::Content(b)) = c.get("t") { collect_inline(b, bold, italic, scale*0.7, out); }
        }
        "h" => out.push(InlineItem{ text: " ".into(), bold, italic, size_scale: scale, is_space: true, is_linebreak: false }),
        _ => {
            for (_, v) in &c.fields {
                match v {
                    Value::Content(inner) => collect_inline(inner, bold, italic, scale, out),
                    Value::Array(items) => { for it in items { if let Value::Content(inner) = it { collect_inline(inner, bold, italic, scale, out); } } }
                    _ => {}
                }
            }
        }
    }
}

