}

/// Split evaluated document content into pages of blocks (pagebreak splits pages).
pub fn document_blocks(root: &Content) -> Vec<Vec<BlockItem>> {
    let children = flatten_top(root);
    let mut pages: Vec<Vec<BlockItem>> = vec![Vec::new()];
    let mut cur_para: Vec<InlineItem> = Vec::new();
    let mut cur_list: Vec<Vec<InlineItem>> = Vec::new();
    let mut list_open = false;
    let flush_para = |pages: &mut Vec<Vec<BlockItem>>, cur: &mut Vec<InlineItem>| {
        let trimmed = trim_items(std::mem::take(cur));
        if !trimmed.is_empty() { pages.last_mut().unwrap().push(BlockItem::Paragraph(trimmed)); }
    };
    let flush_list = |pages: &mut Vec<Vec<BlockItem>>, cur_list: &mut Vec<Vec<InlineItem>>, open: &mut bool| {
        if *open && !cur_list.is_empty() { pages.last_mut().unwrap().push(BlockItem::List(std::mem::take(cur_list))); }
        *open = false;
        cur_list.clear();
    };
    for ch in &children {
        match ch.func.as_str() {
            "parbreak" => { flush_para(&mut pages, &mut cur_para); flush_list(&mut pages, &mut cur_list, &mut list_open); }
            "pagebreak" => { flush_para(&mut pages, &mut cur_para); flush_list(&mut pages, &mut cur_list, &mut list_open); pages.push(Vec::new()); }
            "heading" => {
                flush_para(&mut pages, &mut cur_para); flush_list(&mut pages, &mut cur_list, &mut list_open);
                let level = match ch.get("depth").or_else(|| ch.get("level")) { Some(Value::Int(i)) => (*i).clamp(1,6) as usize, _ => 1 };
                let mut items = Vec::new();
                if let Some(Value::Content(b)) = ch.get("body") { collect_inline(b, false, false, 1.0, &mut items); }
                pages.last_mut().unwrap().push(BlockItem::Heading(level, trim_items(items)));
            }
            "item" => {
                flush_para(&mut pages, &mut cur_para);
                let mut items = Vec::new();
                if let Some(Value::Content(b)) = ch.get("body") { collect_inline(b, false, false, 1.0, &mut items); }
                cur_list.push(trim_items(items));
                list_open = true;
            }
            "list" => {
                flush_para(&mut pages, &mut cur_para); flush_list(&mut pages, &mut cur_list, &mut list_open);
                let mut items_list = Vec::new();
                if let Some(Value::Array(kids)) = ch.get("children") {
                    for kid in kids { if let Value::Content(kc)=kid { let mut items=Vec::new(); if let Some(Value::Content(b))=kc.get("body") { collect_inline(b,false,false,1.0,&mut items); } items_list.push(trim_items(items)); } }
                }
                pages.last_mut().unwrap().push(BlockItem::List(items_list));
            }
            "enum" => {
                flush_para(&mut pages, &mut cur_para); flush_list(&mut pages, &mut cur_list, &mut list_open);
                let mut numbered = Vec::new();
                if let Some(Value::Array(kids)) = ch.get("children") {
                    for (idx, kid) in kids.iter().enumerate() { if let Value::Content(kc)=kid { let mut items=Vec::new(); if let Some(Value::Content(b))=kc.get("body") { collect_inline(b,false,false,1.0,&mut items); } numbered.push(((idx+1) as i64, trim_items(items))); } }
                }
                pages.last_mut().unwrap().push(BlockItem::Enum(numbered));
            }
            "raw" if matches!(ch.get("block"), Some(Value::Bool(true))) => {
                flush_para(&mut pages, &mut cur_para); flush_list(&mut pages, &mut cur_list, &mut list_open);
                if let Some(Value::Str(t)) = ch.get("text") { pages.last_mut().unwrap().push(BlockItem::RawBlock(t.clone())); }
            }
            "v" => {
                flush_para(&mut pages, &mut cur_para); flush_list(&mut pages, &mut cur_list, &mut list_open);
                let amt = match ch.get("amount") { Some(Value::Length(l)) => l.pt + l.em * 11.0, _ => 11.0 };
                pages.last_mut().unwrap().push(BlockItem::Spacer(amt));
            }
            "metadata" | "counter-display" => { /* invisible */ }
            _ => {
                // inline content → accumulate into paragraph
                // But nested sequences containing headings etc. already flattened.
                collect_inline(ch, false, false, 1.0, &mut cur_para);
            }
        }
    }
    flush_para(&mut pages, &mut cur_para);
    flush_list(&mut pages, &mut cur_list, &mut list_open);
    pages
}

pub fn flatten_top(root: &Content) -> Vec<Content> {
    let mut out = Vec::new();
    fn walk(c: &Content, out: &mut Vec<Content>) {
        if c.func == "sequence" {
            if let Some(Value::Array(children)) = c.get("children") {
                for ch in children { if let Value::Content(cc) = ch { walk(cc, out); } }
                return;
            }
        }
        if c.func == "styled" {
            if let Some(Value::Content(ch)) = c.get("child") { walk(ch, out); return; }
        }
        if c.func == "par" {
            // par body inline content + parbreak after? Emit body children flat; callers accumulate paragraph.
            if let Some(Value::Content(b)) = c.get("body") { walk(b, out); out.push(Content::new("parbreak")); return; }
        }
        out.push(c.clone());
    }
    walk(root, &mut out);
    out
}

fn trim_items(items: Vec<InlineItem>) -> Vec<InlineItem> {
    let mut items = items;
    while items.first().map(|i| i.is_space).unwrap_or(false) { items.remove(0); }
    while items.last().map(|i| i.is_space).unwrap_or(false) { items.pop(); }
    items
}

pub fn char_width_factor(ch: char) -> f64 {
    // Rough Helvetica-ish widths (fraction of font size). Only used for wrapping/placement approximations.
    match ch {
        ' ' => 0.278,
        'i' | 'l' | 'j' | '|' | '!' | '\'' | '.' | ',' | ':' | ';' => 0.278,
        'f' | 't' | 'r' => 0.333,
        'm' | 'w' => 0.833,
        'M' | 'W' => 0.944,
        '0'..='9' => 0.556,
        'A'..='Z' => 0.667,
        _ => 0.5,
    }
}

pub fn text_width(text: &str, size: f64) -> f64 {
    text.chars().map(|c| char_width_factor(c) * size).sum()
}

fn heading_scale(level: usize) -> f64 {
    match level { 1 => 1.68, 2 => 1.41, 3 => 1.19, _ => 1.0 }
}

/// Layout one input-page's blocks onto output pages (handles auto height + overflow to extra pages).
pub fn layout_pages(engine: &Engine, root: &Content) -> Vec<PageLayout> {
    let input_pages = document_blocks(root);
    let mut out_pages: Vec<PageLayout> = Vec::new();
    let auto_height = engine.page_height_pt.is_none();
    for blocks in input_pages {
        // Flatten blocks into lines with heights, then paginate (or single auto page).
        #[derive(Clone)]
        struct Line { runs: Vec<(String, bool, bool, f64, f64)>, height: f64, space_before: f64, space_after: f64, indent: f64 }
        // runs: (text, bold, italic, size, x_offset_from_margin+indent)
        let mut lines: Vec<Line> = Vec::new();
        let content_width = (engine.page_width_pt - 2.0 * engine.margin_pt).max(50.0);
        let base = engine.font_size_pt;
        let wrap = |items: &[InlineItem], size: f64, indent: f64, bold_all: bool, lines: &mut Vec<Line>, space_before: f64, space_after: f64| {
            // Greedy word wrap.
            let mut cur: Vec<(String,bool,bool,f64,f64)> = Vec::new();
            let mut cur_x = indent;
            let mut first_line = true;
            let mut push_line = |cur: &mut Vec<(String,bool,bool,f64,f64)>, lines: &mut Vec<Line>, first: bool, size: f64, indent: f64| {
                // trim trailing spaces
                while cur.last().map(|(t,_,_,_,_)| t.trim().is_empty()).unwrap_or(false) { cur.pop(); }
                lines.push(Line{ runs: std::mem::take(cur), height: size * 1.4, space_before: if first { space_before } else { 0.0 }, space_after: 0.0, indent });
            };
            for item in items {
                let sz = size * item.size_scale;
                let b = bold_all || item.bold;
                if item.is_linebreak {
                    push_line(&mut cur, lines, first_line, size, indent);
                    first_line = false;
                    cur_x = indent;
                    continue;
                }
                if item.is_space {
                    if cur.is_empty() { continue; }
                    let w = text_width(" ", sz);
                    cur.push((" ".into(), b, item.italic, sz, cur_x));
                    cur_x += w;
                    continue;
                }
                let w = text_width(&item.text, sz);
                if cur_x + w > content_width && !cur.iter().all(|(t,_,_,_,_)| t.trim().is_empty()) {
                    // break before this word (drop trailing space already in cur via push_line trim)
                    push_line(&mut cur, lines, first_line, size, indent);
                    first_line = false;
                    cur_x = indent;
                }
                cur.push((item.text.clone(), b, item.italic, sz, cur_x));
                cur_x += w;
            }
            // final line (even if empty for empty paragraphs? skip empties)
            if !cur.is_empty() {
                let sb = if first_line { space_before } else { 0.0 };
                while cur.last().map(|(t,_,_,_,_)| t.trim().is_empty()).unwrap_or(false) { cur.pop(); }
                lines.push(Line{ runs: cur, height: size * 1.4, space_before: sb, space_after, indent });
            } else if space_after > 0.0 {
                // empty block spacing ignored
                let _ = space_after;
            }
        };
        for block in &blocks {
            match block {
                BlockItem::Paragraph(items) => {
                    wrap(items, base, 0.0, false, &mut lines, 0.0, base * 0.6);
                    if let Some(last) = lines.last_mut() { last.space_after = base * 0.6; }
                }
                BlockItem::Heading(level, items) => {
                    let sz = base * heading_scale(*level);
                    wrap(items, sz, 0.0, true, &mut lines, sz * 0.8, sz * 0.4);
                    if let Some(last) = lines.last_mut() { last.space_after = sz * 0.4; }
                }
                BlockItem::List(list_items) => {
                    for items in list_items {
                        // bullet prefix: prepend a "•" word item
                        let mut with_bullet: Vec<InlineItem> = vec![InlineItem{ text: "•".into(), bold: false, italic: false, size_scale: 1.0, is_space: false, is_linebreak: false }, InlineItem{ text: " ".into(), bold: false, italic: false, size_scale: 1.0, is_space: true, is_linebreak: false }];
                        with_bullet.extend(items.clone());
                        wrap(&with_bullet, base, 14.0, false, &mut lines, 0.0, 0.0);
                    }
                    if let Some(last) = lines.last_mut() { last.space_after = base * 0.6; }
                }
                BlockItem::Enum(numbered) => {
                    for (n, items) in numbered {
                        let mut pre: Vec<InlineItem> = vec![InlineItem{ text: format!("{}.", n), bold: false, italic: false, size_scale: 1.0, is_space: false, is_linebreak: false }, InlineItem{ text: " ".into(), bold: false, italic: false, size_scale: 1.0, is_space: true, is_linebreak: false }];
                        pre.extend(items.clone());
                        wrap(&pre, base, 14.0, false, &mut lines, 0.0, 0.0);
                    }
                    if let Some(last) = lines.last_mut() { last.space_after = base * 0.6; }
                }
                BlockItem::RawBlock(text) => {
                    for line_text in text.lines() {
                        let runs = if line_text.is_empty() { vec![] } else { vec![(line_text.to_string(), false, false, base, 0.0)] };
                        lines.push(Line{ runs, height: base*1.4, space_before: 0.0, space_after: 0.0, indent: 0.0 });
                    }
                    if let Some(last) = lines.last_mut() { last.space_after = base * 0.6; }
                }
                BlockItem::Spacer(amt) => {
                    lines.push(Line{ runs: vec![], height: *amt, space_before: 0.0, space_after: 0.0, indent: 0.0 });
                }
            }
        }
        if auto_height {
            let mut y = engine.margin_pt;
            let mut runs = Vec::new();
            for line in &lines {
                y += line.space_before;
                let baseline = y + line.height * 0.75;
                for (text, bold, italic, size, xoff) in &line.runs {
                    runs.push(TextRun{ text: text.clone(), x_pt: engine.margin_pt + xoff, y_baseline_pt: baseline, size_pt: *size, bold: *bold, italic: *italic });
                }
                y += line.height + line.space_after;
            }
            let height = if lines.is_empty() { engine.margin_pt * 2.0 + base * 1.4 } else { y + engine.margin_pt - base * 0.6 };
            out_pages.push(PageLayout{ width_pt: engine.page_width_pt, height_pt: height.max(10.0), runs });
        } else {
            let page_h = engine.page_height_pt.unwrap();
            let bottom_limit = page_h - engine.margin_pt;
            let mut y = engine.margin_pt;
            let mut runs: Vec<TextRun> = Vec::new();
            let mut started = false;
            for line in &lines {
                let need = line.space_before + line.height;
                if y + need > bottom_limit && started {
                    out_pages.push(PageLayout{ width_pt: engine.page_width_pt, height_pt: page_h, runs: std::mem::take(&mut runs) });
                    y = engine.margin_pt;
                }
                y += line.space_before;
                let baseline = y + line.height * 0.75;
                for (text, bold, italic, size, xoff) in &line.runs {
                    runs.push(TextRun{ text: text.clone(), x_pt: engine.margin_pt + xoff, y_baseline_pt: baseline, size_pt: *size, bold: *bold, italic: *italic });
                }
                y += line.height + line.space_after;
                started = true;
            }
            out_pages.push(PageLayout{ width_pt: engine.page_width_pt, height_pt: page_h, runs });
        }
    }
    if out_pages.is_empty() {
        out_pages.push(PageLayout{ width_pt: engine.page_width_pt, height_pt: engine.page_height_pt.unwrap_or(841.88976378), runs: vec![] });
    }
    out_pages
}

// ---------------- PDF ----------------
fn pdf_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '(' | ')' | '\\' => { out.push('\\'); out.push(c); }
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 32 => out.push_str(&format!("\\{:03o}", c as u32)),
            c if (c as u32) > 126 => {
                // WinAnsi approximations for common chars; octal escapes for Latin-1 range.
                match c {
                    '•' => out.push_str("\\225"),
                    '–' => out.push_str("\\226"),
                    '—' => out.push_str("\\227"),
                    '“' => out.push_str("\\223"),
                    '”' => out.push_str("\\224"),
                    '‘' => out.push_str("\\221"),
                    '’' => out.push_str("\\222"),
                    '…' => out.push_str("\\205"),
                    '\u{00a0}' => out.push_str("\\240"),
                    _ => {
                        let n = c as u32;
                        if n <= 255 { out.push_str(&format!("\\{:03o}", n)); }
                    }
                }
            }
            c => out.push(c),
        }
    }
    out
}

fn fmt_num(x: f64) -> String {
    if x == x.trunc() && x.abs() < 1e12 { format!("{}", x as i64) } else { format!("{:.4}", x).trim_end_matches('0').trim_end_matches('.').to_string() }
}

pub struct PdfOptions {
    pub standard: Option<String>, // e.g. "1.4", "a-1b", "ua-1"
    pub tagged: bool,
    pub title: Option<String>,
    pub creation_timestamp: Option<i64>,
}

pub fn export_pdf(engine: &Engine, pages: &[PageLayout], opts: &PdfOptions) -> Result<Vec<u8>, String> {
    // Validate standards (errors observed).
    let version = match opts.standard.as_deref() {
        None => "1.7",
        Some(v) => {
            // v may be comma list already validated by caller for duplicates; pick the version component.
            pdf_version_for_standard(v)
        }
    };
    let ts = opts.creation_timestamp.unwrap_or_else(|| chrono::Utc::now().timestamp());
    let dt = chrono::DateTime::from_timestamp(ts, 0).unwrap_or_else(|| chrono::Utc::now());
    let date_str = dt.format("D:%Y%m%d%H%M%SZ").to_string();
    let doc_id = stable_id(engine_input_hint(pages), ts);
    let _ = opts.tagged; // structure tree approximated minimally below regardless (tagged differences not deeply checked).

    // Object allocation:
    // 1: Pages, 2: Catalog, 3: Info, 4: Metadata, 5..8: Fonts (F1..F4), then per page: Page + Contents.
    let mut objects: Vec<(usize, Vec<u8>)> = Vec::new();
    let fonts_base = 5usize;
    let page_obj_start = fonts_base + 4;
    let mut page_obj_nums: Vec<usize> = Vec::new();
    for i in 0..pages.len() { page_obj_nums.push(page_obj_start + i*2); }
    // Pages
    let kids = page_obj_nums.iter().map(|n| format!("{} 0 R", n)).collect::<Vec<_>>().join(" ");
    objects.push((1, format!("<<\n  /Type /Pages\n  /Count {}\n  /Kids [{}]\n>>", pages.len(), kids).into_bytes()));
    // Metadata XMP
    let title_xml = match &opts.title {
        Some(t) if !t.is_empty() => format!("<dc:title><rdf:Alt><rdf:li xml:lang=\"x-default\">{}</rdf:li></rdf:Alt></dc:title>", xml_escape(t)),
        _ => String::new(),
    };
    let iso = dt.format("%Y-%m-%dT%H:%M:%S+00:00").to_string();
    let xmp = format!("<?xpacket begin=\"\u{feff}\" id=\"W5M0MpCehiHzreSzNTczkc9d\"?><x:xmpmeta xmlns:x=\"adobe:ns:meta/\" x:xmptk=\"xmp-writer\"><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\"><rdf:Description rdf:about=\"\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\"  xmlns:xmp=\"http://ns.adobe.com/xap/1.0/\"  xmlns:xmpMM=\"http://ns.adobe.com/xap/1.0/mm/\"  xmlns:xmpTPg=\"http://ns.adobe.com/xap/1.0/t/pg/\"  xmlns:pdf=\"http://ns.adobe.com/pdf/1.3/\" >{}<xmp:CreatorTool>Typst 0.14.2</xmp:CreatorTool><dc:language><rdf:Bag><rdf:li>en</rdf:li></rdf:Bag></dc:language><xmp:ModifyDate>{}</xmp:ModifyDate><xmp:CreateDate>{}</xmp:CreateDate><xmpTPg:NPages>{}</xmpTPg:NPages><dc:format>application/pdf</dc:format><xmpMM:InstanceID>{}</xmpMM:InstanceID><xmpMM:DocumentID>{}</xmpMM:DocumentID><xmpMM:RenditionClass>proof</xmpMM:RenditionClass><pdf:PDFVersion>{}</pdf:PDFVersion></rdf:Description></rdf:RDF></x:xmpmeta><?xpacket end=\"r\"?>",
        title_xml, iso, iso, pages.len(), doc_id, doc_id, version);
    // Catalog
    objects.push((2, format!("<<\n  /Type /Catalog\n  /Pages 1 0 R\n  /Metadata 4 0 R\n  /Lang (en)\n  /ViewerPreferences <<\n    /Direction /L2R\n  >>\n>>").into_bytes()));
    // Info
    let title_entry = match &opts.title { Some(t) if !t.is_empty() => format!("\n  /Title ({})", pdf_escape(t)), _ => String::new() };
    objects.push((3, format!("<<\n  /Creator (Typst 0.14.2){}\n  /ModDate ({})\n  /CreationDate ({})\n>>", title_entry, date_str, date_str).into_bytes()));
    // Metadata stream
    objects.push((4, stream_object(&format!("<<\n  /Length {}\n  /Type /Metadata\n  /Subtype /XML\n>>", xmp.len()), xmp.as_bytes())));
    // Fonts
    let font_names = ["Helvetica", "Helvetica-Bold", "Helvetica-Oblique", "Helvetica-BoldOblique"];
    for (i, fname) in font_names.iter().enumerate() {
        objects.push((fonts_base + i, format!("<<\n  /Type /Font\n  /Subtype /Type1\n  /BaseFont /{}\n  /Encoding /WinAnsiEncoding\n>>", fname).into_bytes()));
    }
    // Pages + contents
    for (i, page) in pages.iter().enumerate() {
        let page_obj = page_obj_nums[i];
        let content_obj = page_obj + 1;
        let mut content = String::new();
        // white background
        content.push_str(&format!("1 1 1 rg\n0 0 {} {} re f\n0 0 0 rg\n", fmt_num(page.width_pt), fmt_num(page.height_pt)));
        for run in &page.runs {
            // merge spaces: runs include space runs; skip pure-space runs (positioning already accounts), render words.
            if run.text.is_empty() { continue; }
            let font = match (run.bold, run.italic) { (false,false)=>"F1", (true,false)=>"F2", (false,true)=>"F3", (true,true)=>"F4" };
            let y_pdf = page.height_pt - run.y_baseline_pt;
            content.push_str(&format!("BT /{} {} Tf {} {} Td ({}) Tj ET\n", font, fmt_num(run.size_pt), fmt_num(run.x_pt), fmt_num(y_pdf), pdf_escape(&run.text)));
        }
        let compressed = zlib_compress(content.as_bytes());
        objects.push((page_obj, format!("<<\n  /Type /Page\n  /Resources <<\n    /Font << /F1 {} 0 R /F2 {} 0 R /F3 {} 0 R /F4 {} 0 R >>\n    /ProcSet [/PDF /Text /ImageC /ImageB]\n  >>\n  /MediaBox [0 0 {} {}]\n  /Parent 1 0 R\n  /Contents {} 0 R\n>>", fonts_base, fonts_base+1, fonts_base+2, fonts_base+3, fmt_num(page.width_pt), fmt_num(page.height_pt), content_obj).into_bytes()));
        objects.push((content_obj, stream_object(&format!("<<\n  /Length {}\n  /Filter /FlateDecode\n>>", compressed.len()), &compressed)));
    }
    objects.sort_by_key(|(n, _)| *n);
    // Serialize
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(format!("%PDF-{}\n%\u{0080}\u{0080}\u{0080}\u{0080}\n\n", version).as_bytes());
    // The header comment bytes must be raw 0x80 bytes: write manually.
    // (The format! above used \u{0080} which encodes as UTF-8 0xC2 0x80 — fix by rebuilding header.)
    out.clear();
    out.extend_from_slice(format!("%PDF-{}\n%", version).as_bytes());
    out.extend_from_slice(&[0x80u8,0x80,0x80,0x80]);
    out.extend_from_slice(b"\n\n");
    let max_obj = objects.iter().map(|(n,_)| *n).max().unwrap_or(0);
    let mut offsets = vec![0usize; max_obj + 1];
    for (num, body) in &objects {
        offsets[*num] = out.len();
        out.extend_from_slice(format!("{} 0 obj\n", num).as_bytes());
        out.extend_from_slice(body);
        out.extend_from_slice(b"\nendobj\n\n");
    }
    let xref_start = out.len();
    let size = max_obj + 1;
    let mut xref = format!("xref\n0 {}\n0000000000 65535 f\r\n", size);
    for i in 1..=max_obj {
        xref.push_str(&format!("{:010} 00000 n\r\n", offsets.get(i).copied().unwrap_or(0)));
    }
    out.extend_from_slice(xref.as_bytes());
    out.extend_from_slice(format!("trailer\n<<\n  /Size {}\n  /Root 2 0 R\n  /Info 3 0 R\n  /ID [({}) ({})]\n>>\nstartxref\n{}\n%%EOF", size, doc_id, doc_id, xref_start).as_bytes());
    Ok(out)
}

fn engine_input_hint(pages: &[PageLayout]) -> String {
    pages.iter().flat_map(|p| p.runs.iter().map(|r| r.text.clone())).collect()
}

fn stream_object(dict: &str, data: &[u8]) -> Vec<u8> {
    let mut v: Vec<u8> = dict.as_bytes().to_vec();
    v.extend_from_slice(b"\nstream\n");
    v.extend_from_slice(data);
    v.extend_from_slice(b"\nendstream");
    v
}

fn zlib_compress(data: &[u8]) -> Vec<u8> {
    let mut enc = ZlibEncoder::new(Vec::new(), Compression::default());
    let _ = enc.write_all(data);
    enc.finish().unwrap_or_default()
}

pub fn pdf_version_for_standard(std_list: &str) -> &'static str {
    // std_list is the winning standard (single) or comma list; map A/UA standards to base versions.
    let first = std_list.split(',').next().unwrap_or("1.7");
    match first.trim() {
        "1.4" => "1.4", "1.5" => "1.5", "1.6" => "1.6", "1.7" => "1.7", "2.0" => "2.0",
        "a-1b" | "a-1a" => "1.4",
        "a-2b" | "a-2u" | "a-2a" | "a-3b" | "a-3u" | "a-3a" => "1.7",
        "a-4" | "a-4f" | "a-4e" => "2.0",
        "ua-1" => "1.7",
        _ => "1.7",
    }
}

pub fn validate_pdf_standards(standards: &[String]) -> Result<(), String> {
    // Duplicate base versions conflict (observed 1.4+1.5 message uses display names PDF 1.4 etc.)
    // Collect explicit version standards.
    let versions: Vec<&str> = standards.iter().map(|s| s.as_str()).filter(|s| matches!(*s, "1.4"|"1.5"|"1.6"|"1.7"|"2.0")).collect();
    let unique: Vec<&&str> = { let mut u: Vec<&&str> = Vec::new(); for v in &versions { if !u.contains(&v) { u.push(v); } } u };
    if unique.len() >= 2 {
        return Err(format!("PDF cannot conform to PDF {} and PDF {} at the same time", unique[0], unique[1]));
    }
    Ok(())
}

fn stable_id(hint: String, ts: i64) -> String {
    // Deterministic-ish base64-ish ID (16 bytes → base64). Reference generates random; any valid string is fine, but keep stable per (content, ts).
    let mut h: u64 = 0xcbf29ce484222325;
    for b in hint.bytes().chain(ts.to_le_bytes()) {
        h ^= b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    let mut bytes = [0u8; 16];
    let mut x = h;
    for i in 0..16 { x ^= x << 13; x ^= x >> 7; x ^= x << 17; bytes[i] = (x & 0xff) as u8; }
    base64_encode(&bytes)
}

pub fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        out.push(CHARS[(b[0] >> 2) as usize] as char);
        out.push(CHARS[(((b[0] & 3) << 4) | (b[1] >> 4)) as usize] as char);
        if chunk.len() > 1 { out.push(CHARS[(((b[1] & 15) << 2) | (b[2] >> 6)) as usize] as char); } else { out.push('='); }
        if chunk.len() > 2 { out.push(CHARS[(b[2] & 63) as usize] as char); } else { out.push('='); }
    }
    // Reference IDs look like "+6gwQr+3uAoRtEdyBO5ikg==" (standard base64 with padding). Keep.
    out
}

pub fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;")
}

// ---------------- SVG ----------------
pub fn export_svg(page: &PageLayout, _engine: &Engine) -> String {
    let mut s = String::new();
    s.push_str(&format!("<svg viewBox=\"0 0 {} {}\" width=\"{}pt\" height=\"{}pt\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" xmlns:h5=\"http://www.w3.org/1999/xhtml\">\n", trim_float(page.width_pt), trim_float(page.height_pt), trim_float(page.width_pt), trim_float(page.height_pt)));
    s.push_str(&format!("  <path fill=\"#ffffff\" fill-rule=\"nonzero\" d=\"M 0 0v {}h {}v -{}Z \"/>\n", trim_float(page.height_pt), trim_float(page.width_pt), trim_float(page.height_pt)));
    for run in &page.runs {
        if run.text.trim().is_empty() { continue; }
        let style = if run.bold { " font-weight=\"700\"" } else { "" };
        let style2 = if run.italic { " font-style=\"italic\"" } else { "" };
        s.push_str(&format!("  <text x=\"{}\" y=\"{}\" font-family=\"Libertinus Serif, serif\" font-size=\"{}\"{}{} fill=\"#000000\">{}</text>\n",
            trim_float(run.x_pt), trim_float(run.y_baseline_pt), trim_float(run.size_pt), style, style2, xml_escape(&run.text)));
    }
    s.push_str("  <defs/>\n");
    s.push_str("</svg>\n");
    s
}

pub fn trim_float(x: f64) -> String {
    if x == x.trunc() { format!("{}", x as i64) } else { let s = format!("{:.9}", x); s.trim_end_matches('0').trim_end_matches('.').to_string() }
}

// ---------------- PNG ----------------
// Tiny bitmap font: 6x8-ish? We use a 5x7 font for printable ASCII (public-domain style patterns written from scratch as generic block glyphs).
// For non-ASCII, draw a hollow box.

pub fn export_png(page: &PageLayout, ppi: f64) -> Vec<u8> {
    let scale = ppi / 72.0;
    let w = ((page.width_pt * scale).round() as i64).max(1) as u32;
    let h = ((page.height_pt * scale).round() as i64).max(1) as u32;
    let mut px: Vec<u8> = vec![255u8; (w as usize) * (h as usize) * 4]; // RGBA white (alpha 255 already)
    for run in &page.runs {
        let size_px = run.size_pt * scale;
        // Glyph cell: width = size*0.6, height = size. Baseline at y_baseline*scale; glyph top = baseline - size*0.8.
        let mut x = run.x_pt * scale;
        for ch in run.text.chars() {
            let adv = char_width_factor(ch) * size_px;
            draw_glyph(&mut px, w, h, ch, x, run.y_baseline_pt * scale - size_px * 0.8, size_px, run.bold);
            x += adv;
        }
    }
    encode_png_rgba(&px, w, h)
}

fn set_px(px: &mut [u8], w: u32, h: u32, x: i32, y: i32) {
    if x < 0 || y < 0 || x >= w as i32 || y >= h as i32 { return; }
    let idx = ((y as u32 * w + x as u32) * 4) as usize;
    px[idx] = 0; px[idx+1] = 0; px[idx+2] = 0; px[idx+3] = 255;
}

fn draw_glyph(px: &mut [u8], w: u32, h: u32, ch: char, x0: f64, y0: f64, size: f64, bold: bool) {
    if ch == ' ' { return; }
    let pattern = glyph_pattern(ch);
    let cw = size * 0.6;
    let scale_x = cw / 5.0;
    let scale_y = size / 7.0;
    let thickness_x = (scale_x.ceil() as i32).max(1) + if bold { 1 } else { 0 };
    let thickness_y = (scale_y.ceil() as i32).max(1);
    for (row, bits) in pattern.iter().enumerate() {
        for col in 0..5 {
            if (bits >> (4 - col)) & 1 == 1 {
                let gx = (x0 + col as f64 * scale_x) as i32;
                let gy = (y0 + row as f64 * scale_y) as i32;
                for dx in 0..thickness_x { for dy in 0..thickness_y { set_px(px, w, h, gx+dx, gy+dy); } }
            }
        }
    }
}

/// 5x7 glyphs (rows top→bottom, 5 bits each, MSB = leftmost). Compact original patterns.
