pub fn encode_png_rgba(px: &[u8], w: u32, h: u32) -> Vec<u8> {
    // Filter 0 per row + zlib (stored via flate2 default compression is fine; reference used a specific encoder but any valid PNG passes structural checks).
    let mut raw: Vec<u8> = Vec::with_capacity((1 + w as usize * 4) * h as usize);
    for y in 0..h as usize {
        raw.push(0u8);
        let row_start = y * w as usize * 4;
        raw.extend_from_slice(&px[row_start..row_start + w as usize * 4]);
    }
    let compressed = zlib_compress(&raw);
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    let mut ihdr: Vec<u8> = Vec::new();
    ihdr.extend_from_slice(&w.to_be_bytes());
    ihdr.extend_from_slice(&h.to_be_bytes());
    ihdr.push(8); ihdr.push(6); ihdr.push(0); ihdr.push(0); ihdr.push(0);
    write_chunk(&mut out, b"IHDR", &ihdr);
    write_chunk(&mut out, b"IDAT", &compressed);
    write_chunk(&mut out, b"IEND", &[]);
    out
}

fn write_chunk(out: &mut Vec<u8>, typ: &[u8;4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(typ);
    out.extend_from_slice(data);
    let mut crc_data: Vec<u8> = Vec::new();
    crc_data.extend_from_slice(typ);
    crc_data.extend_from_slice(data);
    out.extend_from_slice(&crc32(&crc_data).to_be_bytes());
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut c = i as u32;
        for _ in 0..8 { c = if c & 1 != 0 { 0xedb88320 ^ (c >> 1) } else { c >> 1 }; }
        table[i] = c;
    }
    let mut crc: u32 = 0xffffffff;
    for b in data { crc = table[((crc ^ (*b as u32)) & 0xff) as usize] ^ (crc >> 8); }
    crc ^ 0xffffffff
}

// ---------------- HTML ----------------
pub fn export_html(engine: &Engine, root: &Content) -> String {
    let mut body_lines: Vec<String> = Vec::new();
    let children = flatten_top(root);
    let mut para: Vec<String> = Vec::new(); // segments of HTML for current paragraph (already escaped, with tags)
    let mut in_list: Option<String> = None; // "ul" / "ol"
    let mut list_items: Vec<String> = Vec::new();
    let mut enum_counter = 1i64;
    let flush_para = |body: &mut Vec<String>, para: &mut Vec<String>| {
        let text: String = para.iter().cloned().collect::<String>();
        let text = collapse_ws_html(&text);
        if !text.trim().is_empty() { body.push(format!("    <p>{}</p>", text.trim())); }
        para.clear();
    };
    let flush_list = |body: &mut Vec<String>, kind: &mut Option<String>, items: &mut Vec<String>| {
        if let Some(k) = kind.take() {
            if !items.is_empty() {
                body.push(format!("    <{}>", k));
                for it in items.drain(..) { body.push(it); }
                body.push(format!("    </{}>", k));
            }
        }
    };
    for ch in &children {
        match ch.func.as_str() {
            "parbreak" => { flush_para(&mut body_lines, &mut para); flush_list(&mut body_lines, &mut in_list, &mut list_items); }
            "pagebreak" => { flush_para(&mut body_lines, &mut para); flush_list(&mut body_lines, &mut in_list, &mut list_items); }
            "heading" => {
                flush_para(&mut body_lines, &mut para); flush_list(&mut body_lines, &mut in_list, &mut list_items);
                let level = match ch.get("depth").or_else(|| ch.get("level")) { Some(Value::Int(i)) => (*i).clamp(0,5), _ => 1 };
                let tag = level + 1; // observed h2 for level 1
                let mut s = String::new();
                if let Some(Value::Content(b)) = ch.get("body") { html_inline(b, &mut s); }
                body_lines.push(format!("    <h{}>{}</h{}>", tag, collapse_ws_html(&s).trim(), tag));
            }
            "item" => {
                // Bare items from markup: list kind unknown (list vs enum lost). Default ul. (Enum items evaluated from markup lose numbering; enum element handled below.
                flush_para(&mut body_lines, &mut para);
                if in_list.as_deref() != Some("ul") { flush_list(&mut body_lines, &mut in_list, &mut list_items); in_list = Some("ul".into()); }
                let mut s = String::new();
                if let Some(Value::Content(b)) = ch.get("body") { html_inline(b, &mut s); }
                list_items.push(format!("      <li>{}</li>", collapse_ws_html(&s).trim()));
            }
            "list" => {
                flush_para(&mut body_lines, &mut para); flush_list(&mut body_lines, &mut in_list, &mut list_items);
                if let Some(Value::Array(kids)) = ch.get("children") {
                    body_lines.push("    <ul>".into());
                    for kid in kids { if let Value::Content(kc)=kid { let mut s=String::new(); if let Some(Value::Content(b))=kc.get("body") { html_inline(b,&mut s); } body_lines.push(format!("      <li>{}</li>", collapse_ws_html(&s).trim())); } }
                    body_lines.push("    </ul>".into());
                }
            }
            "enum" => {
                flush_para(&mut body_lines, &mut para); flush_list(&mut body_lines, &mut in_list, &mut list_items);
                if let Some(Value::Array(kids)) = ch.get("children") {
                    body_lines.push("    <ol>".into());
                    for (idx, kid) in kids.iter().enumerate() { if let Value::Content(kc)=kid { let mut s=String::new(); if let Some(Value::Content(b))=kc.get("body") { html_inline(b,&mut s); } body_lines.push(format!("      <li value=\"{}\">{}</li>", idx+1, collapse_ws_html(&s).trim())); } }
                    body_lines.push("    </ol>".into());
                }
            }
            "raw" if matches!(ch.get("block"), Some(Value::Bool(true))) => {
                flush_para(&mut body_lines, &mut para); flush_list(&mut body_lines, &mut in_list, &mut list_items);
                if let Some(Value::Str(t)) = ch.get("text") { body_lines.push(format!("    <pre><code>{}</code></pre>", xml_escape(t))); }
            }
            "metadata" => {}
            _ => {
                // Group consecutive bare enum items that came from markup EnumItem? They are "item" handled above (ul). Enum numbering for markup `1.` lists: our eval lost it — HTML for `1. one` docs would emit <ul>. Fix at eval site instead (see note in eval.rs). For now, inline.
                let mut s = String::new();
                html_inline(ch, &mut s);
                para.push(s);
                let _ = &mut enum_counter;
            }
        }
    }
    flush_para(&mut body_lines, &mut para);
    flush_list(&mut body_lines, &mut in_list, &mut list_items);
    let title_tag = match &engine.doc_title {
        Some(t) if !t.is_empty() => format!("\n    <title>{}</title>", xml_escape(t)),
        _ => String::new(),
    };
    if body_lines.is_empty() {
        format!("<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">{}\n  </head>\n  <body></body>\n</html>\n", title_tag)
    } else {
        format!("<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">{}\n  </head>\n  <body>\n{}\n  </body>\n</html>\n", title_tag, body_lines.join("\n"))
    }
}

fn collapse_ws_html(s: &str) -> String {
    // Collapse runs of spaces (but tags contain spaces too — collapsing inside tags is harmless for our emitted tags without attributes except <a/li value>... be careful: only collapse outside tags.)
    let mut out = String::new();
    let mut in_tag = false;
    let mut last_space = false;
    for c in s.chars() {
        match c {
            '<' => { in_tag = true; last_space = false; out.push(c); }
            '>' => { in_tag = false; out.push(c); }
            ' ' | '\n' | '\t' | '\r' if !in_tag => {
                if !last_space { out.push(' '); last_space = true; }
            }
            _ => { last_space = false; out.push(c); }
        }
    }
    out
}

pub fn html_inline(c: &Content, out: &mut String) {
    match c.func.as_str() {
        "text" => { if let Some(Value::Str(t)) = c.get("text") { out.push_str(&xml_escape(t)); } }
        "space" => out.push(' '),
        "parbreak" => out.push(' '),
        "linebreak" => out.push_str("<br>"),
        "strong" => { out.push_str("<strong>"); if let Some(Value::Content(b))=c.get("body") { html_inline(b, out); } out.push_str("</strong>"); }
        "emph" => { out.push_str("<em>"); if let Some(Value::Content(b))=c.get("body") { html_inline(b, out); } out.push_str("</em>"); }
        "sequence" => { if let Some(Value::Array(kids))=c.get("children") { for kid in kids { if let Value::Content(kc)=kid { html_inline(kc, out); } } } }
        "raw" => { if let Some(Value::Str(t))=c.get("text") { out.push_str(&format!("<code>{}</code>", xml_escape(t))); } }
        "link" => {
            let dest = match c.get("dest") { Some(Value::Str(s))=>s.clone(), _=>String::new() };
            out.push_str(&format!("<a href=\"{}\">", xml_escape(&dest)));
            if let Some(Value::Content(b))=c.get("body") { html_inline(b, out); }
            out.push_str("</a>");
        }
        "underline" => { out.push_str("<u>"); if let Some(Value::Content(b))=c.get("body") { html_inline(b, out); } out.push_str("</u>"); }
        "equation" => { if let Some(Value::Content(b))=c.get("body") { html_inline(b, out); } }
        "symbol" => { if let Some(Value::Str(t))=c.get("text") { out.push_str(&xml_escape(t)); } }
        _ => {
            for (_, v) in &c.fields {
                match v {
                    Value::Content(inner) => html_inline(inner, out),
                    Value::Array(items) => { for it in items { if let Value::Content(inner)=it { html_inline(inner, out); } } }
                    _ => {}
                }
            }
        }
    }
}
