        ColorMode::Never => false,
        ColorMode::Auto => {
            if std::env::var_os("NO_COLOR").is_some() { return false; }
            is_terminal_stderr()
        }
    }
}

fn is_terminal_stderr() -> bool {
    // No isatty crate: use libc via std? `std::io::IsTerminal` is stable since 1.70.
    use std::io::IsTerminal;
    std::io::stderr().is_terminal()
}

pub fn bin_name() -> String {
    std::env::args().next()
        .and_then(|a| Path::new(&a).file_name().map(|s| s.to_string_lossy().to_string()))
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "typst".to_string())
}

// ---------- value parsers ----------
#[derive(Clone, Debug)]
struct InputParser;
impl TypedValueParser for InputParser {
    type Value = String;
    fn parse_ref(&self, _cmd: &Command, _arg: Option<&Arg>, value: &std::ffi::OsStr) -> Result<Self::Value, clap::Error> {
        let s = value.to_string_lossy().to_string();
        // NOTE: clap's error formatting for custom parsers: to get exact `error: invalid value 'x' for '--input <key=value>': ...` we rely on clap wrapping our error message. Using Error::raw with format... Clap value-parser errors: return Err(clap::Error::new(...))? The idiomatic way: `.value_parser(parse_input)` fn returning Result<_, String> gives exactly that format. So this struct is unused; keep for clarity.
        Ok(s)
    }
}

fn parse_input(s: &str) -> Result<String, String> {
    match s.split_once('=') {
        None => Err("input must be a key and a value separated by an equal sign".to_string()),
        Some((k, _)) if k.is_empty() => Err("the key was missing or empty".to_string()),
        Some(_) => Ok(s.to_string()),
    }
}

fn parse_pages(s: &str) -> Result<String, String> {
    // Validate eagerly like reference (clap value parser). Empty string special: reference reports invalid value '' — clap will show the raw input in the message prefix; our Err text matches suffix.
    if s.is_empty() { return Err("page export range must not be empty".to_string()); }
    for part in s.split(',') {
        if part.is_empty() { return Err("page export range must not be empty".to_string()); }
        if let Some((a, b)) = part.split_once('-') {
            if a.is_empty() { return Err("not a valid page number".to_string()); }
            let start = parse_page_num(a)?;
            if b.is_empty() {
                // open range ok
                continue;
            }
            let end = parse_page_num(b)?;
            if end <= start {
                return Err("page export range must end at a page after the start".to_string());
            }
        } else {
            parse_page_num(part)?;
        }
    }
    Ok(s.to_string())
}

fn parse_page_num(s: &str) -> Result<u64, String> {
    match s.parse::<u64>() {
        Ok(0) => Err("page numbers start at one".to_string()),
        Ok(n) => Ok(n),
        Err(_) => Err("not a valid page number".to_string()),
    }
}

fn parse_ppi(s: &str) -> Result<f32, String> {
    s.parse::<f32>().map_err(|e| e.to_string())
}

fn parse_jobs(s: &str) -> Result<u64, String> {
    // Reference error for "abc": "invalid digit found in string" (Rust ParseIntError display).
    s.parse::<usize>().map(|v| v as u64).map_err(|e| e.to_string())
}

fn parse_timestamp(s: &str) -> Result<i64, String> {
    s.parse::<i64>().map_err(|e| e.to_string())
}

