pub fn run() -> i32 {
    let cli = build_cli();
    // Handle no-args welcome: if argv has no args at all.
    let raw_args: Vec<String> = std::env::args().skip(1).collect();
    if raw_args.is_empty() {
        print!("{}", welcome_text());
        return 0;
    }
    let matches = match cli.try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // Clap handles printing + exit code (0 for help/version, 2 for errors).
            e.exit()
        }
    };
    let color_mode = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("always") => ColorMode::Always,
        Some("never") => ColorMode::Never,
        _ => ColorMode::Auto,
    };
    let use_color = want_color(&color_mode);
    match matches.subcommand() {
        None => {
            // Matches reference: e.g. `typst --color always` with no command → ? Clap would... arg_required_else_help(false) + no subcommand. Reference behavior for `typst --color never` alone: unprobed. Likely prints welcome too (no command). Choose welcome.
            print!("{}", welcome_text());
            0
        }
        Some(("compile", sub)) | Some(("c", sub)) => cmd_compile_watch(sub, use_color, false),
        Some(("watch", sub)) | Some(("w", sub)) => cmd_compile_watch(sub, use_color, true),
        Some(("init", sub)) => cmd_init(sub, use_color),
        Some(("eval", sub)) => cmd_eval(sub, use_color),
        Some(("fonts", sub)) => cmd_fonts(sub),
        Some(("completions", sub)) => cmd_completions(sub),
        Some(("info", sub)) => cmd_info(sub, use_color),
        Some(("query", sub)) => cmd_query(sub, use_color),
        Some(("update", _sub)) => {
            eprint!("{}", render_simple_error("self-updating is not enabled for this executable, please update with the package manager or mechanism used for initial installation", use_color));
            1
        }
        _ => 2,
    }
}

