// ---------------- helpers ----------------
fn get_bool(matches: &clap::ArgMatches, id: &str) -> bool {
    matches.get_one::<bool>(id).copied().unwrap_or(false)
}

fn features_from(matches: &clap::ArgMatches) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    if let Some(vals) = matches.try_get_many::<String>("features").ok().flatten() {
        for v in vals { if !out.contains(v) { out.push(v.clone()); } }
    }
    out
}

fn features_from_env_only() -> Vec<String> {
    // For `info`, features come only from TYPST_FEATURES env (no CLI flag).
    match std::env::var("TYPST_FEATURES") {
        Ok(v) if !v.is_empty() => v.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect(),
        _ => Vec::new(),
    }
}

fn font_paths_from(matches: &clap::ArgMatches) -> Vec<PathBuf> {
    // Clap with env + Append: env value comes as a single value "a:b". Split each value on ':'.
    let mut out: Vec<PathBuf> = Vec::new();
    if let Some(vals) = matches.try_get_many::<String>("font-path").ok().flatten() {
        for v in vals {
            for part in v.split(':') {
                if !part.is_empty() { out.push(PathBuf::from(part)); }
            }
        }
    }
    out
}

fn inputs_from(matches: &clap::ArgMatches) -> Vec<(String,String)> {
    let mut out = Vec::new();
    if let Some(vals) = matches.try_get_many::<String>("input").ok().flatten() {
        for v in vals {
            if let Some((k, val)) = v.split_once('=') { out.push((k.to_string(), val.to_string())); }
        }
    }
    out
}

fn creation_ts_from(matches: &clap::ArgMatches) -> Option<i64> {
    matches.try_get_one::<i64>("creation-timestamp").ok().flatten().copied()
}

fn project_from_matches(matches: &clap::ArgMatches, input_path: Option<&Path>) -> Result<Project, String> {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let root: PathBuf = match matches.try_get_one::<String>("root").ok().flatten() {
        Some(r) => {
            let p = PathBuf::from(r);
            if !p.exists() {
                return Err(format!("root directory not found (searched at {})", r));
            }
            if p.is_absolute() { p } else { cwd.join(p) }
        }
        None => {
            match input_path {
                Some(ip) => {
                    let abs = if ip.is_absolute() { ip.to_path_buf() } else { cwd.join(ip) };
                    abs.parent().map(|p| p.to_path_buf()).unwrap_or(cwd.clone())
                }
                None => cwd.clone(),
            }
        }
    };
    let package_path = match matches.try_get_one::<String>("package-path").ok().flatten() {
        Some(p) => PathBuf::from(p),
        None => crate::world::default_package_path(None),
    };
    let package_cache_path = match matches.try_get_one::<String>("package-cache-path").ok().flatten() {
        Some(p) => PathBuf::from(p),
        None => crate::world::default_package_cache_path(None),
    };
    Ok(Project{
        root,
        main_path: input_path.map(|p| p.to_path_buf()),
        package_path,
        package_cache_path,
        font_paths: font_paths_from(matches),
        ignore_system_fonts: get_bool(matches, "ignore-system-fonts"),
        ignore_embedded_fonts: get_bool(matches, "ignore-embedded-fonts"),
        inputs: inputs_from(matches),
    })
}

fn read_stdin_bytes() -> Vec<u8> {
    let mut buf = Vec::new();
    let _ = std::io::stdin().lock().read_to_end(&mut buf);
    buf
}

fn read_input_source(input: &str) -> Result<(String, Option<PathBuf>, String), CliError> {
    // Returns (text, main_file, display_path)
    if input == "-" {
        let bytes = read_stdin_bytes();
        match String::from_utf8(bytes) {
            Ok(t) => Ok((t, None, "<stdin>".to_string())),
            Err(_) => Err(CliError::message_with_hint("file is not valid UTF-8".to_string(), "a file without an extension is not usually a Typst file")),
        }
    } else {
        let p = PathBuf::from(input);
        match std::fs::read(&p) {
            Ok(bytes) => {
                match String::from_utf8(bytes) {
                    Ok(t) => {
                        let display = crate::world::display_path(&p);
                        let abs = if p.is_absolute() { p.clone() } else { std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(&p) };
                        Ok((t, Some(crate::world::normalize(&abs)), display))
                    }
                    Err(_) => Err(CliError::message("file is not valid UTF-8".to_string())),
                }
            }
            Err(e) => {
                if !p.exists() {
                    Err(CliError::message(format!("input file not found (searched at {})", input)))
                } else if p.is_dir() {
                    Err(CliError::message("failed to load file (is a directory)".to_string()))
                } else {
                    Err(CliError::message(format!("failed to load file ({})", io_reason(&e))))
                }
            }
        }
    }
}

fn io_reason(e: &std::io::Error) -> String {
    // Rust io Error display: "No such file or directory (os error 2)" etc.
    e.to_string()
}

struct CliError { message: String, hint: Option<String> }
impl CliError {
    fn message(m: String) -> Self { CliError{ message: m, hint: None } }
    fn message_with_hint(m: String, h: &str) -> Self { CliError{ message: m, hint: Some(h.to_string()) } }
    fn render(&self, use_color: bool) -> String {
        let mut s = render_simple_error(&self.message, use_color);
        if let Some(h) = &self.hint { s.push_str(&format!(" = hint: {}\n", h)); }
        s
    }
}

fn emit_diag(d: &Diag, source: &str, display: &str, fmt: &str, use_color: bool) {
    if fmt == "short" {
        eprint!("{}", crate::diag::format_short(d, display));
        // hints in short mode? Reference short for warnings with hints — keep hints after? Observed short eval error had no hints. Append nothing.
    } else {
        eprint!("{}", crate::diag::format_human(d, source, display, use_color));
    }
}

// ---------------- info ----------------
fn cmd_info(sub: &clap::ArgMatches, use_color: bool) -> i32 {
    let feats = features_from_env_only();
    // Unknown features warning (printed to stderr AFTER stdout in observed capture; separate streams so relative order unobservable).
    let mut unknown_msgs: Vec<String> = Vec::new();
    let html_on = feats.iter().any(|f| f=="html");
    let a11y_on = feats.iter().any(|f| f=="a11y-extras");
    for f in &feats {
        if f != "html" && f != "a11y-extras" { unknown_msgs.push(format!("error: Unknown runtime feature: `{}`\n", f)); }
    }
    // Font paths for info come from env only.
    let font_paths: Vec<String> = match std::env::var("TYPST_FONT_PATHS") {
        Ok(v) if !v.is_empty() => v.split(':').map(|s| s.to_string()).collect(),
        _ => Vec::new(),
    };
    let sys_on = !env_bool("TYPST_IGNORE_SYSTEM_FONTS");
    let emb_on = !env_bool("TYPST_IGNORE_EMBEDDED_FONTS");
    let pkg_path = std::env::var("TYPST_PACKAGE_PATH").ok().filter(|s| !s.is_empty()).map(|s| PathBuf::from(s)).unwrap_or_else(|| crate::world::default_package_path(None));
    let pkg_cache = std::env::var("TYPST_PACKAGE_CACHE_PATH").ok().filter(|s| !s.is_empty()).map(|s| PathBuf::from(s)).unwrap_or_else(|| crate::world::default_package_cache_path(None));
    let fmt = sub.try_get_one::<String>("format").ok().flatten().map(|s| s.clone());
    let pretty = sub.get_flag("pretty");
    match fmt.as_deref() {
        None => {
            let text = render_info_human(&font_paths, sys_on, emb_on, &pkg_path, &pkg_cache, html_on, a11y_on, use_color);
            eprint!("{}", text);
        }
        Some("json") => {
            let value = info_json_value(&font_paths, sys_on, emb_on, &pkg_path, &pkg_cache, html_on, a11y_on);
            if pretty { println!("{}", serde_json::to_string_pretty(&value).unwrap()); }
            else { println!("{}", serde_json::to_string(&value).unwrap()); }
        }
        Some("yaml") => {
            let value = info_json_value(&font_paths, sys_on, emb_on, &pkg_path, &pkg_cache, html_on, a11y_on);
            let mut y = serde_yaml::to_string(&value).unwrap_or_default();
            if y.starts_with("---\n") { y = y[4..].to_string(); }
            print!("{}", y);
            if !y.ends_with('\n') { println!(); }
        }
        _ => {}
    }
    for m in unknown_msgs { eprint!("{}", m); }
    0
}

fn env_bool(name: &str) -> bool {
    match std::env::var(name) { Ok(v) => v == "true", Err(_) => false }
}

const INFO_ENV_KEYS: &[&str] = &[
    "TYPST_CERT","TYPST_FEATURES","TYPST_FONT_PATHS","TYPST_IGNORE_SYSTEM_FONTS","TYPST_IGNORE_EMBEDDED_FONTS","TYPST_PACKAGE_CACHE_PATH","TYPST_PACKAGE_PATH","TYPST_ROOT","TYPST_UPDATE_BACKUP_PATH","SOURCE_DATE_EPOCH","XDG_CACHE_HOME","XDG_DATA_HOME","FONTCONFIG_FILE","OPENSSL_CONF","NO_COLOR","NO_PROXY","HTTP_PROXY","HTTPS_PROXY","ALL_PROXY",
];

fn info_json_value(font_paths: &[String], sys_on: bool, emb_on: bool, pkg_path: &Path, pkg_cache: &Path, html_on: bool, a11y_on: bool) -> serde_json::Value {
    let mut env_map = serde_json::Map::new();
    for k in INFO_ENV_KEYS {
        env_map.insert(k.to_string(), match std::env::var(k) { Ok(v) => serde_json::Value::String(v), Err(_) => serde_json::Value::Null });
    }
    serde_json::json!({
        "version": "0.14.2",
        "build": {
            "commit": COMMIT_FULL,
            "platform": {"os": "linux", "arch": "x86_64"},
            "settings": {"self-update": false, "http-server": true}
        },
        "features": {"html": html_on, "a11y-extras": a11y_on},
        "fonts": {"paths": font_paths, "system": sys_on, "embedded": emb_on},
        "packages": {"package-path": pkg_path.to_string_lossy(), "package-cache-path": pkg_cache.to_string_lossy()},
        "env": env_map,
    })
}

fn render_info_human(font_paths: &[String], sys_on: bool, emb_on: bool, pkg_path: &Path, pkg_cache: &Path, html_on: bool, a11y_on: bool, use_color: bool) -> String {
    // Wrappers matching observed ANSI: label = \e[0m\e[36m<label padded>\e[0m + " " + value wrapped \e[0m\e[3Xm<value>\e[0m
    let label_plain = |s: &str| -> String { s.to_string() };
    let label = |s: &str| -> String {
        if use_color { format!("\x1b[0m\x1b[36m{}\x1b[0m ", s) } else { s.to_string() }
    };
    let good = |s: &str| -> String { if use_color { format!("\x1b[0m\x1b[32m{}\x1b[0m", s) } else { s.to_string() } }; // green
    let status = |s: &str| -> String { if use_color { format!("\x1b[0m\x1b[34m{}\x1b[0m", s) } else { s.to_string() } }; // blue
    let mut out = String::new();
    if use_color {
        out.push_str(&format!("{} {} ({}, {} on {})\n\n", label_plain(""), "", "", "", ""));
        // rebuild precisely:
        out = format!("\x1b[0m\x1b[36mVersion\x1b[0m \x1b[0m\x1b[32m0.14.2\x1b[0m (\x1b[0m\x1b[32m97ac4370\x1b[0m, \x1b[0m\x1b[32mlinux\x1b[0m on \x1b[0m\x1b[32mx86_64\x1b[0m)\n\n");
    } else {
        out.push_str("Version 0.14.2 (97ac4370, linux on x86_64)\n\n");
    }
    let _ = (label_plain, good, status);
    out.push_str("Build settings\n");
    let row = |out: &mut String, label_text: &str, value: &str, value_green: bool, suffix: &str| {
        if use_color {
            // label cyan WITHOUT manually adding space because label text already padded; observed: cyan(label) + " " + colored(value)
            let wrap = if value_green { format!("\x1b[0m\x1b[32m{}\x1b[0m", value) } else { format!("\x1b[0m\x1b[34m{}\x1b[0m", value) };
            out.push_str(&format!("  \x1b[0m\x1b[36m{}\x1b[0m {}{}\n", label_text, wrap, suffix));
        } else {
            // Plain: two spaces + label + " " + value + suffix. Labels are pre-padded by caller to observed alignment.
            out.push_str(&format!("  {} {}{}\n", label_text, value, suffix));
        }
    };
    row(&mut out, "self-update", "off", false, " (Update Typst via `typst update`)");
    row(&mut out, "http-server", if true { "on " } else { "on " }, false, " (Serve HTML via `typst watch`)");
    out.push_str("\nFeatures\n");
    row(&mut out, "html       ", if html_on { "on " } else { "off" }, false, " (Experimental HTML support)");
    row(&mut out, "a11y-extras", if a11y_on { "on " } else { "off" }, false, " (Experimental accessibility additions)");
    out.push_str("\nFonts\n");
    if font_paths.is_empty() {
        row(&mut out, "Custom font paths", "<none>", false, "");
    } else {
        if use_color {
            out.push_str("  \x1b[0m\x1b[36mCustom font paths\x1b[0m\n");
            for p in font_paths { out.push_str(&format!("    - \x1b[0m\x1b[32m{}\x1b[0m\n", p)); }
        } else {
            out.push_str("  Custom font paths\n");
            for p in font_paths { out.push_str(&format!("    - {}\n", p)); }
        }
    }
    row(&mut out, "System fonts  ", if sys_on { "on" } else { "off" }, false, "");
    row(&mut out, "Embedded fonts", if emb_on { "on" } else { "off" }, false, "");
    out.push_str("\nPackages\n");
    row(&mut out, "Package path      ", &pkg_path.to_string_lossy(), true, "");
    row(&mut out, "Package cache path", &pkg_cache.to_string_lossy(), true, "");
    out.push_str("\nEnvironment variables\n");
    // env labels padded: observed plain has two spaces between label and value? e.g. "  TYPST_CERT                  <unset>" — label column width: longest key TYPST_IGNORE_EMBEDDED_FONTS (27) then single space? Let's compute: plain lines show label padded to 27 then space? Count: "TYPST_CERT" (10) + 18 spaces = col 28? We'll pad labels to 28 chars then value? Check: TYPST_IGNORE_EMBEDDED_FONTS len 27, then 1 space, then <unset>. Others padded to 27 + space. So format "{:<27} {} " hmm with row() adding a space: pad label to 27.
    for k in INFO_ENV_KEYS {
        let padded = format!("{:<27}", k);
        match std::env::var(k) {
            Ok(v) => row(&mut out, &padded, &v, true, ""),
            Err(_) => row(&mut out, &padded, "<unset>", false, ""),
        }
    }
    out.push('\n');
    out
}

// ---------------- fonts ----------------
fn cmd_fonts(sub: &clap::ArgMatches) -> i32 {
    let font_paths = font_paths_from(sub);
    let ignore_system = get_bool(sub, "ignore-system-fonts");
    let ignore_embedded = get_bool(sub, "ignore-embedded-fonts");
    let variants = sub.get_flag("variants");
    let families = crate::world::discover_fonts(&font_paths, ignore_system, ignore_embedded);
    let mut out = String::new();
    for fam in &families {
        out.push_str(&fam.name);
        out.push('\n');
        if variants {
            for v in &fam.variants {
                out.push_str(&format!("- Style: {}, Weight: {}, Stretch: FontStretch({}), Path: {}\n", v.style, v.weight, v.stretch, v.path));
            }
        }
    }
    print!("{}", out);
    0
}

// ---------------- completions ----------------
fn cmd_completions(sub: &clap::ArgMatches) -> i32 {
    let shell = sub.get_one::<String>("SHELL").map(|s| s.as_str()).unwrap_or("");
    let mut cmd = build_cli();
    // Force binary name "typst" for completion generation (observed independent of argv[0]).
    // clap_complete::generate uses cmd.get_bin_name or name. Set explicitly:
    cmd = cmd.bin_name("typst");
    let gen_shell = match shell {
        "bash" => clap_complete::Shell::Bash,
        "elvish" => clap_complete::Shell::Elvish,
        "fish" => clap_complete::Shell::Fish,
        "powershell" => clap_complete::Shell::PowerShell,
        "zsh" => clap_complete::Shell::Zsh,
        _ => return 2,
    };
    clap_complete::generate(gen_shell, &mut cmd, "typst", &mut std::io::stdout().lock());
    0
}

// ---------------- compile/watch ----------------
fn infer_format(output: Option<&str>, format_flag: Option<&str>, input: &str) -> Result<String, String> {
    if let Some(f) = format_flag { return Ok(f.to_string()); }
    match output {
        None => {
            // derived from input stem + default .pdf (format pdf)
            Ok("pdf".to_string())
        }
        Some("-") => Ok("pdf".to_string()),
        Some(out) => {
            let lower = out.to_ascii_lowercase();
            // Template braces like {p} sit before extension; extension still at end.
            let ext = Path::new(out).extension().and_then(|e| e.to_str()).map(|e| e.to_ascii_lowercase());
            match ext.as_deref() {
                Some("pdf") => Ok("pdf".into()),
                Some("png") => Ok("png".into()),
                Some("svg") => Ok("svg".into()),
                Some("html") | Some("htm") => {
                    if lower.ends_with(".html") { Ok("html".into()) } else { Err(format!("could not infer output format for path {}.\nconsider providing the format manually with `--format/-f`", out)) }
                }
                _ => Err(format!("could not infer output format for path {}.\nconsider providing the format manually with `--format/-f`", out)),
            }
            .map(|s: String| { let _ = input; s })
        }
    }
}

fn default_output_path(input: &str, format: &str) -> String {
    let p = Path::new(input);
    let stem = p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "output".into());
    match p.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent.join(format!("{}.{}", stem, format)).to_string_lossy().to_string(),
        _ => format!("{}.{}", stem, format),
    }
}

fn page_selection(pages_args: &[String], total: usize) -> Vec<usize> {
    // pages_args already split by clap delimiter into parts like "2", "3-6", "8-".
    if pages_args.is_empty() { return (0..total).collect(); }
    let mut selected: Vec<usize> = Vec::new();
    let mut push = |idx0: usize| { if idx0 < total && !selected.contains(&idx0) { selected.push(idx0); } };
    for part in pages_args {
        // part may still contain commas if passed via `=`? clap delimiter splits. Handle both.
        for sub in part.split(',') {
            if let Some((a,b)) = sub.split_once('-') {
                let a: usize = a.parse().unwrap_or(1);
                if b.is_empty() {
                    for i in a..=total { push(i-1); }
                } else {
                    let b: usize = b.parse().unwrap_or(a);
                    for i in a..=b { push(i-1); }
                }
            } else if let Ok(n) = sub.parse::<usize>() {
                if n >= 1 { push(n-1); }
            }
        }
    }
    selected
}

fn make_engine(matches: &clap::ArgMatches, input_str: &str, main_file: &Option<PathBuf>) -> Result<Engine, CliError> {
    let input_path_buf = if input_str == "-" { None } else { Some(PathBuf::from(input_str)) };
    let project = project_from_matches(matches, input_path_buf.as_deref()).map_err(|e| CliError::message(e))?;
    let mut engine = Engine::new(project.clone());
    engine.inputs = inputs_from(matches);
    engine.main_file = main_file.clone();
    engine.base_dir = main_file.as_ref().and_then(|p| p.parent().map(|x| x.to_path_buf()));
    if let Some(ts) = creation_ts_from(matches) { engine.clock_unix = ts; }
    engine.dependencies = Vec::new();
    if let Some(mf) = main_file { engine.dependencies.push(mf.clone()); }
    // Known families for unknown-font warnings.
    let families = crate::world::font_family_names(&project.font_paths, project.ignore_system_fonts, project.ignore_embedded_fonts);
    engine.known_font_families_lower = families.into_iter().map(|f| f.to_ascii_lowercase()).collect();
    Ok(engine)
}

