fn compile_like_command(name: &str, about: &str, is_watch: bool) -> Command {
    let cmd = Command::new(name)
        .about(about)
        .arg(Arg::new("INPUT").required(true)
            .help("Path to input Typst file. Use `-` to read input from stdin")
            .long_help("Path to input Typst file. Use `-` to read input from stdin"))
        .arg(Arg::new("OUTPUT").required(false)
            .help("Path to output file (PDF, PNG, SVG, or HTML). Use `-` to write output to stdout")
            .long_help("Path to output file (PDF, PNG, SVG, or HTML). Use `-` to write output to stdout.\n\nFor output formats emitting one file per page (PNG & SVG), a page number template must be present if the source document renders to multiple pages. Use `{p}` for page numbers, `{0p}` for zero padded page numbers and `{t}` for page count. For example, `page-{0p}-of-{t}.png` creates `page-01-of-10.png`, `page-02-of-10.png`, and so on."))
        .arg(Arg::new("format").short('f').long("format").value_name("FORMAT")
            .help("The format of the output file, inferred from the extension by default")
            .long_help("The format of the output file, inferred from the extension by default")
            .value_parser(PossibleValuesParser::new(["pdf","png","svg","html"])));
    common_compile_args(cmd, is_watch)
}

pub fn build_cli() -> Command {
    let bin = bin_name();
    let after_help = "Resources:\n  Tutorial:                 https://typst.app/docs/tutorial/\n  Reference documentation:  https://typst.app/docs/reference/\n  Templates & Packages:     https://typst.app/universe/\n  Forum for questions:      https://forum.typst.app/";
    let mut cmd = Command::new("typst")
        .bin_name(bin.clone())
        .version(VERSION_STR)
        .disable_version_flag(true)
        // Clap prints "{name} {version}" for --version. Our version string is "0.14.2 (...)" and name is "typst" → "typst 0.14.2 (...)" ✓. Help header first line: clap with .version() doesn't print it by default in help. Reference first line "Typst 0.14.2 (97ac4370)" — that's clap's behavior when `version` is set? Actually clap's help template includes "{bin} {version}"? No. It comes from the crate's custom help template or `about`? Let's use .about with first line? Test at fix stage: use help_template.
        .help_template("{before-help}Typst 0.14.2 (97ac4370)\n\n{usage-heading} {usage}\n\n{all-args}{after-help}")
        .after_help(after_help)
        .arg_required_else_help(false)
        .arg(Arg::new("color").long("color").value_name("COLOR")
            .help("Whether to use color. When set to `auto` if the terminal to supports it")
            .value_parser(PossibleValuesParser::new(["auto","always","never"]))
            .default_value("auto")
            .global(true))
        .arg(Arg::new("cert").long("cert").value_name("CERT")
            .help("Path to a custom CA certificate to use when making network requests")
            .env("TYPST_CERT")
            .global(true))
        .arg(Arg::new("version").short('V').long("version")
            .help("Print version")
            .action(ArgAction::Version))
        .subcommand(compile_like_command("compile", "Compiles an input file into a supported output format", false).alias("c"))
        .subcommand(compile_like_command("watch", "Watches an input file and recompiles on changes", true).alias("w"))
        .subcommand(packages_args(Command::new("init")
            .about("Initializes a new project from a template")
            .arg(Arg::new("TEMPLATE").required(true)
                .help("The template to use, e.g. `@preview/charged-ieee`")
