            .arg(Arg::new("field").long("field").value_name("FIELD")
                .help("Extracts just one field from all retrieved elements"))
            .arg(Arg::new("one").long("one")
                .help("Expects and retrieves exactly one element")
                .action(ArgAction::SetTrue))
            .arg(Arg::new("format").long("format").value_name("FORMAT")
                .help("The format to serialize in")
                .value_parser(PossibleValuesParser::new(["json","yaml"]))
                .default_value("json"))
            .arg(Arg::new("pretty").long("pretty")
                .help("Whether to pretty-print the serialized output. Only applies to JSON format")
                .long_help("Whether to pretty-print the serialized output.\n\nOnly applies to JSON format.")
                .action(ArgAction::SetTrue))
            .arg(Arg::new("target").long("target").value_name("TARGET")
