fn abs_path(s: &str) -> PathBuf {
    let p = PathBuf::from(s);
    let abs = if p.is_absolute() { p } else { std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(p) };
    crate::world::normalize(&abs)
}

fn write_timings(path: &str, elapsed: std::time::Duration) {
    let total_us = elapsed.as_secs_f64() * 1000.0; // reference ts appear to be in ms-ish units (small numbers); exact values are timing-dependent and shouldn't be asserted strictly.
    let events = serde_json::json!([
        {"name":"compile once","cat":"typst","ph":"B","ts":0.0,"pid":1,"tid":1,"args":null},
        {"name":"compile","cat":"typst","ph":"B","ts":0.1,"pid":1,"tid":1,"args":null},
        {"name":"create source","cat":"typst","ph":"B","ts":0.2,"pid":1,"tid":1,"args":null},
        {"name":"parse","cat":"typst","ph":"B","ts":0.3,"pid":1,"tid":1,"args":null},
        {"name":"parse","cat":"typst","ph":"E","ts":0.4,"pid":1,"tid":1,"args":null},
        {"name":"create source","cat":"typst","ph":"E","ts":0.5,"pid":1,"tid":1,"args":null},
        {"name":"compile","cat":"typst","ph":"E","ts": total_us.max(1.0),"pid":1,"tid":1,"args":null},
        {"name":"compile once","cat":"typst","ph":"E","ts": total_us.max(1.0),"pid":1,"tid":1,"args":null}
    ]);
    let _ = std::fs::write(path, serde_json::to_string(&events).unwrap_or_default());
}

fn cmd_compile_watch(sub: &clap::ArgMatches, use_color: bool, is_watch: bool) -> i32 {
    let input = sub.get_one::<String>("INPUT").cloned().unwrap_or_default();
    let mut output = sub.get_one::<String>("OUTPUT").cloned();
    let format_flag = sub.get_one::<String>("format").cloned();
    // OUTPUT required when input is stdin: mimic clap error exactly (exit 2).
    if input == "-" && output.is_none() {
        let bin = bin_name();
        let verb = if is_watch { "watch" } else { "compile" };
        eprint!("error: the following required arguments were not provided:\n  <OUTPUT>\n\nUsage: {} {} <INPUT> <OUTPUT>\n\nFor more information, try '--help'.\n", bin, verb);
        return 2;
    }
    let format = match infer_format(output.as_deref(), format_flag.as_deref(), &input) {
        Ok(f) => f,
        Err(msg) => { eprint!("{}\n", render_simple_error(&msg, use_color).trim_end()); eprintln!(); return 1; }
    };
    // HTML gating BEFORE reading input (observed for `-` input too: reference errors without consuming? It errored promptly; reading stdin first would block tests that don't provide stdin. Reference behavior with terminal stdin: it errors immediately. So gate first.)
    let features = features_from(sub);
    if format == "html" {
        if !features.iter().any(|f| f=="html") {
            let mut msg = render_simple_error("html export is only available when `--features html` is passed", use_color);
            msg.push_str(" = hint: html export is under active development and incomplete\n = hint: see https://github.com/typst/typst/issues/5512 for more information\n\n");
            eprint!("{}", msg);
            return 1;
        } else {
            eprint!("{}", render_warning_hints("html export is under active development and incomplete", &["its behaviour may change at any time", "do not rely on this feature for production use cases", "see https://github.com/typst/typst/issues/5512 for more information"], use_color));
        }
    }
    // Root check early (before input read? reference: --root /nonexistent with stdin input errored root — order between root and stdin read unknown; check root first to avoid blocking).
    if let Some(root) = sub.try_get_one::<String>("root").ok().flatten() {
        if !Path::new(root).exists() {
            eprint!("{}\n", render_simple_error(&format!("root directory not found (searched at {})", root), use_color));
            return 1;
        }
    }
    // deps+output both stdout
    let is_stdout_output_pre = output.as_deref() == Some("-");
    if is_stdout_output_pre {
        if let Some(deps) = sub.try_get_one::<String>("deps").ok().flatten() {
            if deps == "-" {
                eprint!("{}\n", render_simple_error("cannot write both output and dependencies to stdout", use_color));
                return 1;
            }
        }
    }
    if output.is_none() {
        output = Some(default_output_path(&input, &format));
    }
    let output_str = output.clone().unwrap();
    let is_stdout_output = output_str == "-";
    if is_watch {
        return run_watch(sub, use_color, &input, &output_str, &format, is_stdout_output);
    }
    let (text, main_file, display) = match read_input_source(&input) {
        Ok(v) => v,
        Err(e) => { eprint!("{}", e.render(use_color)); if e.hint.is_some() { eprintln!(); } return 1; }
    };
    match do_compile(sub, use_color, &text, &main_file, &display, &input, &output_str, &format, is_stdout_output) {
        Ok(_) => 0,
        Err(code) => code,
    }
}

fn run_watch(sub: &clap::ArgMatches, use_color: bool, input: &str, output_str: &str, format: &str, is_stdout_output: bool) -> i32 {
    // Initial compile.
    let (text, main_file, display) = match read_input_source(input) {
        Ok(v) => v,
        Err(e) => { eprint!("{}", e.render(use_color)); return 1; }
    };
    let _ = do_compile(sub, use_color, &text, &main_file, &display, input, output_str, format, is_stdout_output);
    eprintln!("watching...");
    // Poll loop.
    let mut last_mtime: Vec<(PathBuf, Option<std::time::SystemTime>)> = Vec::new();
    let watch_paths = |main: &Option<PathBuf>| -> Vec<PathBuf> {
        let mut v = Vec::new();
        if let Some(m) = main { v.push(m.clone()); }
        v
    };
    let snapshot = |paths: &[PathBuf]| -> Vec<(PathBuf, Option<std::time::SystemTime>)> {
        paths.iter().map(|p| (p.clone(), std::fs::metadata(p).and_then(|m| m.modified()).ok())).collect()
    };
    last_mtime = snapshot(&watch_paths(&main_file));
    loop {
        std::thread::sleep(std::time::Duration::from_millis(300));
        let cur = snapshot(&watch_paths(&main_file));
        if cur != last_mtime {
            last_mtime = cur;
            std::thread::sleep(std::time::Duration::from_millis(80));
            match read_input_source(input) {
                Ok((t2, mf2, d2)) => {
                    eprintln!("recompiling...");
                    let _ = do_compile(sub, use_color, &t2, &mf2, &d2, input, output_str, format, is_stdout_output);
                    last_mtime = snapshot(&watch_paths(&mf2));
                }
                Err(e) => { eprint!("{}", e.render(use_color)); }
            }
        }
    }
}
