        // Document errors in --in file: reference behavior? It compiles the document; errors likely surface. We report eval-plain style? Use diagnostics with the --in display? Choose: human/short like compile would be wrong for eval. Probing unknown — use plain "error: ..." (eval surface has no spans). Hmm, but doc errors have spans. Compromise: if diagnostic-format short → short with display; else plain message only (consistent with eval).
        match crate::eval::eval_document(&mut engine, &text) {
            Ok(_) => {}
            Err(d) => {
                if diag_fmt == "short" {
                    eprint!("{}", crate::diag::format_short(&d, &display));
                } else {
                    eprint!("{}", crate::diag::format_plain(&d));
                }
                return 1;
            }
        }
    }
    // Parse + eval expression.
    let (expr, parse_errors, _parser) = crate::code::parse_eval_expression(&expr_src);
    if !parse_errors.is_empty() {
        for d in &parse_errors {
            if diag_fmt == "short" {
                // Eval short observed: "error: unknown variable: x\n" (no position!). For parse errors likely same plain form.
                eprint!("error: {}\n", d.message);
            } else {
                eprint!("{}", crate::diag::format_plain(d));
            }
        }
        return 0;
    }
    let env = engine.global_scope();
    let result = engine.eval_expr(&expr, &env, &expr_src);
    match result {
        Ok(value) => {
            let out = crate::builtins::serialize_value(&value, &format, pretty);
            print!("{}", out);
            0
        }
        Err(d) => {
            if diag_fmt == "short" {
                eprint!("error: {}\n", d.message);
                for h in &d.hints { eprint!(" = hint: {}\n", h); }
            } else {
                eprint!("{}", crate::diag::format_plain(&d));
            }
            0
        }
    }
}

// ---------------- query ----------------
fn cmd_query(sub: &clap::ArgMatches, use_color: bool) -> i32 {
    let input = sub.get_one::<String>("INPUT").cloned().unwrap_or_default();
    let selector_src = sub.get_one::<String>("SELECTOR").cloned().unwrap_or_default();
    let field = sub.get_one::<String>("field").cloned();
    let one = sub.get_flag("one");
    let format = sub.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("json").to_string();
    let pretty = sub.get_flag("pretty");
    let target = sub.get_one::<String>("target").map(|s| s.as_str()).unwrap_or("paged").to_string();
    let diag_fmt = sub.get_one::<String>("diagnostic-format").map(|s| s.as_str()).unwrap_or("human").to_string();
    let features = features_from(sub);
    let deprecation_hint: String = if one && field.is_some() {
        format!("use `typst eval 'query({}).first().{}'` instead", selector_src, field.as_deref().unwrap())
    } else if one {
        format!("use `typst eval 'query({}).first()'` instead", selector_src)
    } else if let Some(f) = &field {
        format!("use `typst eval 'query({}).map(it => it.{})'` instead", selector_src, f)
    } else {
        format!("use `typst eval 'query({})'` instead", selector_src)
    };
    let deprecation_text = format!("warning: the `typst query` subcommand is deprecated\n = hint: {}\n\n", deprecation_hint);
    // Validate selector parses as an expression (reference: "failed to evaluate selector: ..." exit 1, NO deprecation warning).
    let (sel_expr, sel_errors, _) = crate::code::parse_eval_expression(selector_src.trim());
    if !sel_errors.is_empty() {
        let msgs: Vec<String> = sel_errors.iter().map(|d| d.message.clone()).collect();
        eprint!("{}\n", render_simple_error(&format!("failed to evaluate selector: {}", msgs.join(", ")), use_color));
        return 1;
    }
    if target == "html" && !features.iter().any(|f| f=="html") {
        let mut msg = render_simple_error("html export is only available when `--features html` is passed", use_color);
        msg.push_str(" = hint: html export is under active development and incomplete\n = hint: see https://github.com/typst/typst/issues/5512 for more information\n\n");
        eprint!("{}", msg);
        return 1;
    }
    let (text, main_file, display) = match read_input_source(&input) {
        Ok(v) => v,
        Err(e) => { eprint!("{}\n", render_simple_error(&e.message, use_color)); return 1; }
    };
    let input_buf = if input == "-" { None } else { Some(PathBuf::from(&input)) };
    let project = match project_from_matches(sub, input_buf.as_deref()) {
        Ok(p) => p,
        Err(e) => { eprint!("{}\n", render_simple_error(&e, use_color)); return 1; }
    };
    let mut engine = Engine::new(project);
    engine.inputs = inputs_from(sub);
    engine.main_file = main_file.clone();
    engine.target = if target == "html" { Target::Html } else { Target::Paged };
    if let Some(ts) = creation_ts_from(sub) { engine.clock_unix = ts; }
    // Evaluate selector value (in fresh scope; selector exprs like heading.where need globals).
    let env = engine.global_scope();
    let sel_value = match engine.eval_expr(&sel_expr, &env, &selector_src) {
        Ok(v) => v,
        Err(d) => {
            eprint!("{}\n", render_simple_error(&format!("failed to evaluate selector: {}", d.message), use_color));
            return 1;
        }
    };
    match crate::eval::eval_document(&mut engine, &text) {
        Ok(_) => {}
        Err(d) => {
            emit_diag(&d, &text, &display, &diag_fmt, use_color);
            eprint!("{}", deprecation_text);
            return 1;
        }
    }
    let results = match crate::builtins::query_elements(&engine, &sel_value) {
        Ok(r) => r,
        Err(d) => { eprint!("{}", crate::diag::format_plain(&d)); eprint!("{}", deprecation_text); return 1; }
    };
    // Apply field extraction.
    let mapped: Result<Vec<Value>, Diag> = match &field {
        None => Ok(results),
        Some(f) => {
            let mut out = Vec::new();
            for v in results {
                match &v {
                    Value::Content(c) => {
                        if f == "label" {
                            out.push(match &c.label { Some(l)=>Value::Label(l.clone()), None=>Value::None });
                        } else if f == "func" {
                            out.push(Value::Func(c.func.clone()));
                        } else if let Some(fv) = c.get(f) {
                            out.push(fv.clone());
                        } else {
                            // decorated heading may have the field
                            let dec = crate::eval::decorate_for_query(c);
                            match dec.get(f) { Some(fv)=> out.push(fv.clone()), None=> return Err_and_warn_query(&deprecation_text, &format!("element {} has no field `{}`", c.func, f)) }
                        }
                    }
                    _ => out.push(Value::None),
                }
            }
            Ok(out)
        }
    };
    let mapped = match mapped { Ok(m)=>m, Err(code)=> return code };
    let final_value: Value = if one {
        if mapped.is_empty() {
            eprint!("error: no element found\n"); // unprobed exact message; also deprecation?
            eprint!("{}", deprecation_text);
            return 1;
        }
        if mapped.len() > 1 {
            eprint!("error: expected exactly one element, found {}\n", mapped.len());
            eprint!("{}", deprecation_text);
            return 1;
        }
        mapped.into_iter().next().unwrap()
    } else {
        Value::Array(mapped)
    };
    print!("{}", crate::builtins::serialize_value(&final_value, &format, pretty));
    eprint!("{}", deprecation_text);
    0
}

fn Err_and_warn_query(_deprecation: &str, _msg: &str) -> Result<Vec<Value>, i32> {
    // Helper shim: field errors — print error + deprecation, exit 1. Implemented inline below via unreachable path.
    // (This function is never actually used to return Ok; caller treats Err(i32) as exit code. Printing happens here.)
    eprint!("error: {}\n\n", _msg);
    eprint!("{}", _deprecation);
    Err(1)
}

// ---------------- init ----------------
fn cmd_init(sub: &clap::ArgMatches, use_color: bool) -> i32 {
    let template = sub.get_one::<String>("TEMPLATE").cloned().unwrap_or_default();
    let dir_arg = sub.get_one::<String>("DIR").cloned();
    let fail = |msg: &str| -> i32 { eprint!("{}\n", render_simple_error(msg, use_color)); 1 };
    let spec = match crate::packages::parse_bare_spec(&template) {
        Ok(s) => s,
        Err(m) => return fail(&m),
    };
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let project = Project{
        root: cwd.clone(), main_path: None,
        package_path: sub.try_get_one::<String>("package-path").ok().flatten().map(|s| PathBuf::from(s)).unwrap_or_else(|| crate::world::default_package_path(None)),
        package_cache_path: sub.try_get_one::<String>("package-cache-path").ok().flatten().map(|s| PathBuf::from(s)).unwrap_or_else(|| crate::world::default_package_cache_path(None)),
        font_paths: Vec::new(), ignore_system_fonts: false, ignore_embedded_fonts: false, inputs: Vec::new(),
    };
    let version: (u64,u64,u64) = match spec.version {
        Some(v) => v,
        None => {
            if spec.namespace == "preview" {
                return fail(&crate::packages::preview_index_error());
            }
            let versions = crate::packages::local_versions(&project, &spec.namespace, &spec.name);
            match versions.iter().max() {
                Some(v) => *v,
                None => return fail("please specify the desired version"),
            }
        }
    };
    let pkg_dir = match crate::packages::package_dir(&project, &spec.namespace, &spec.name, &version) {
        Some(d) => d,
        None => {
            if spec.namespace == "preview" {
                return fail(&crate::packages::preview_download_error(&spec.name, &version));
            } else {
                return fail(&format!("package not found (searched for @{}/{}:{})", spec.namespace, spec.name, crate::packages::version_str(&version)));
            }
        }
    };
    let manifest = crate::packages::read_manifest(&pkg_dir);
    let (tmpl_rel, tmpl_entry) = match &manifest {
        Some(m) => (m.template_path.clone(), m.template_entrypoint.clone()),
        None => (None, None),
    };
    let tmpl_rel = match tmpl_rel {
        Some(p) => p,
        None => return fail(&format!("package @{}/{}:{} is not a template", spec.namespace, spec.name, crate::packages::version_str(&version))),
    };
    let tmpl_entry = tmpl_entry.unwrap_or_else(|| "main.typ".to_string());
    let target_dir_str: String = dir_arg.clone().unwrap_or_else(|| spec.name.clone());
    let target_display = target_dir_str.clone();
    let target_dir = PathBuf::from(&target_dir_str);
    if target_dir.exists() {
        return fail(&format!("project directory already exists (at {})", target_display));
    }
    let src_dir = pkg_dir.join(&tmpl_rel);
    if let Err(e) = copy_dir_recursive(&src_dir, &target_dir) {
        return fail(&format!("failed to create project directory ({})", e));
    }
    eprintln!("Successfully created new project from @{}/{}:{} 🎉", spec.namespace, spec.name, crate::packages::version_str(&version));
    eprintln!("To start writing, run:");
    eprintln!("> cd {}", target_display);
    eprintln!("> typst watch {}", tmpl_entry);
    eprintln!();
    0
}

fn copy_dir_recursive(src: &Path, dst: &Path) -> Result<(), String> {
    std::fs::create_dir_all(dst).map_err(|e| e.to_string())?;
    let rd = std::fs::read_dir(src).map_err(|e| e.to_string())?;
    let mut entries: Vec<PathBuf> = rd.flatten().map(|e| e.path()).collect();
    entries.sort();
    for entry in entries {
        let name = entry.file_name().ok_or("bad path")?;
        let dest = dst.join(name);
        if entry.is_dir() { copy_dir_recursive(&entry, &dest)?; }
        else { std::fs::copy(&entry, &dest).map_err(|e| e.to_string())?; }
    }
    Ok(())
}
