//! Minimal terminal size detection (original implementation).
//! Tries TIOCGWINSZ on stdout, stderr, then stdin.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

/// Returns the size of the terminal as (Width, Height), if available.
pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [1i32, 2, 0] {
        if let Some((w, h)) = terminal_size_of(fd) {
            return Some((Width(w), Height(h)));
        }
    }
    None
}

/// FFI helper type kept for API compatibility with common callers.
pub fn terminal_size_of(fd: i32) -> Option<(u16, u16)> {
    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    const TIOCGWINSZ: u64 = 0x5413;
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let rc = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) };
    if rc == 0 && (ws.ws_col != 0 || ws.ws_row != 0) {
        Some((ws.ws_col, ws.ws_row))
    } else {
        None
    }
}
