// ---- place mutation support ----
#[derive(Clone, Debug)]
pub enum PlaceSeg {
    DictKey(String),
    First,
    Last,
    Index(usize),
}

pub fn place_chain(e: &SpExpr, engine: &mut Engine, env: &Env, source: &str) -> Option<(String, Vec<PlaceSeg>)> {
    match &*e.kind {
        ExprKind::Ident(name, _, _) => Some((name.clone(), Vec::new())),
        ExprKind::Field(base, field, _, _) => {
            let (root, mut segs) = place_chain(base, engine, env, source)?;
            segs.push(PlaceSeg::DictKey(field.clone()));
            Some((root, segs))
        }
        ExprKind::Call(callee, _args, _trailing) => {
            if let ExprKind::Field(base, method, _, _) = &*callee.kind {
                if method == "first" || method == "last" {
                    let (root, mut segs) = place_chain(base, engine, env, source)?;
                    // Resolve index against current value at that point (need length for last). Caller resolves lazily: keep First/Last markers.
                    segs.push(if method == "first" { PlaceSeg::First } else { PlaceSeg::Last });
                    return Some((root, segs));
                }
            }
            None
        }
        ExprKind::Parenthesized(inner) => place_chain(inner, engine, env, source),
        _ => None,
    }
}

pub fn place_get<'a>(root: &'a Value, segs: &[PlaceSeg]) -> Option<&'a Value> {
    let mut cur = root;
    for seg in segs {
        match (seg, cur) {
            (PlaceSeg::DictKey(k), Value::Dict(entries)) => {
                cur = entries.iter().find(|(ek, _)| ek == k).map(|(_, v)| v)?;
            }
            (PlaceSeg::First, Value::Array(items)) => { cur = items.first()?; }
            (PlaceSeg::Last, Value::Array(items)) => { cur = items.last()?; }
            (PlaceSeg::Index(i), Value::Array(items)) => { cur = items.get(*i)?; }
            _ => return None,
        }
    }
    Some(cur)
}

pub fn place_set(root: &mut Value, segs: &[PlaceSeg], new_val: Value) -> bool {
    if segs.is_empty() {
        *root = new_val;
        return true;
    }
    match (&segs[0], root) {
        (PlaceSeg::DictKey(k), Value::Dict(entries)) => {
            let k = k.clone();
            if let Some(entry) = entries.iter_mut().find(|(ek, _)| ek == &k) {
                place_set(&mut entry.1, &segs[1..], new_val)
            } else { false }
        }
        (PlaceSeg::First, Value::Array(items)) => {
            if let Some(first) = items.first_mut() { place_set(first, &segs[1..], new_val) } else { false }
        }
        (PlaceSeg::Last, Value::Array(items)) => {
            if let Some(last) = items.last_mut() { place_set(last, &segs[1..], new_val) } else { false }
        }
        (PlaceSeg::Index(i), Value::Array(items)) => {
            let i = *i;
            if let Some(v) = items.get_mut(i) { place_set(v, &segs[1..], new_val) } else { false }
        }
        _ => false,
    }
}
